#[path = "production_ranked_projection_v1/scalar_emission_fixture_v1_tests.rs"]
mod scalar_emission_fixture_v1_tests;

#[path = "production_ranked_projection_v1/reference_continuation_v1.rs"]
mod reference_continuation_v1;
use reference_continuation_v1::ProjectedReferenceRootsV1;

fn project_ranked_roots_v1(
    source: &RankedProjectionSourceV1<'_>,
    root_inputs: &[ProductionRankedRootInputV1],
    reference_bindings: &crate::reference_effect_v1::AuthenticatedReferenceEffectBindingsV1,
    budget: &mut fe2o3_kernel_ir::CanonicalKernelIrVerificationResourceBudgetV1<'_>,
) -> Result<Box<[ProductionRankedRootProgramV1]>, ProductionRankedProjectionErrorV1> {
    project_ranked_roots_with_progress_v1(source, root_inputs, reference_bindings, budget, None)?
        .finish(source, budget)
}

fn project_ranked_roots_with_progress_v1(
    source: &RankedProjectionSourceV1<'_>,
    root_inputs: &[ProductionRankedRootInputV1],
    reference_bindings: &crate::reference_effect_v1::AuthenticatedReferenceEffectBindingsV1,
    budget: &mut fe2o3_kernel_ir::CanonicalKernelIrVerificationResourceBudgetV1<'_>,
    mut progress: Option<&mut guarded_source_progress_v1::GuardedSourceProgressV1<'_, '_>>,
) -> Result<ProjectedReferenceRootsV1, ProductionRankedProjectionErrorV1> {
    source.require_floor(budget)?;
    source
        .semantic_ssa()
        .verify_replay()
        .map_err(ProductionRankedProjectionErrorV1::SemanticSsa)?;
    let semantic = source.semantic_ssa().source_semantic();
    let source_launch_roster = source.source_launch();
    if root_inputs.is_empty()
        || root_inputs.len() != source_launch_roster.roots().len()
        || source_launch_roster.semantic_sha256() != semantic.semantic_sha256().as_bytes()
    {
        return Err(ProductionRankedProjectionErrorV1::Unsupported(
            "an incomplete typed/semantic ranked root roster",
        ));
    }
    let root_logical_names = root_inputs
        .iter()
        .map(|input| input.logical_name.as_str())
        .collect::<Vec<_>>();
    let binding_logical_names = reference_bindings
        .as_slice()
        .iter()
        .map(|binding| binding.logical_kernel_name.as_str())
        .collect::<Vec<_>>();
    let root_reference_binding_indices =
        partition_reference_effect_binding_indices_v1(&root_logical_names, &binding_logical_names)?;
    let root_reference_bindings = root_reference_binding_indices
        .into_iter()
        .map(|binding_indices| {
            binding_indices
                .into_iter()
                .map(|binding_index| {
                    reference_bindings
                        .as_slice()
                        .get(binding_index)
                        .cloned()
                        .ok_or(ProductionRankedProjectionErrorV1::Unsupported(
                            "reference-effect root assignment produced an out-of-range binding",
                        ))
                })
                .collect::<Result<Vec<_>, ProductionRankedProjectionErrorV1>>()
                .map(crate::reference_effect_v1::AuthenticatedReferenceEffectBindingsV1::new)
        })
        .collect::<Result<Vec<_>, ProductionRankedProjectionErrorV1>>()?;

    let roots = with_canonical_assertions_source_budget_v1(source, budget, |session| {
        let callable_effects = session.callable_effect_summaries(source)?;
        let mut roots = Vec::with_capacity(root_inputs.len());
        for (root_ordinal, ((input, source_root), root_references)) in root_inputs
            .iter()
            .zip(source_launch_roster.roots())
            .zip(root_reference_bindings.iter())
            .enumerate()
        {
            let semantic_root = source_root.selected_root();
            let selection = semantic
                .select_kernel_body_for_root_v1(semantic_root)
                .ok_or(ProductionRankedProjectionErrorV1::Unsupported(
                    "a semantic KernelRoot without one direct body or transparent Result wrapper",
                ))?;
            let root = session
                .with_source_masked_assertions_v1(semantic_root, selection.body(), |facts| {
                    match progress.as_deref_mut() {
                        Some(progress) => progress.with_source(
                            root_ordinal,
                            semantic_root,
                            selection.body(),
                            facts,
                            |facts| {
                                project_and_verify_ranked_root_v1(
                                    semantic,
                                    &callable_effects,
                                    selection,
                                    input,
                                    *source_root,
                                    root_references,
                                    facts,
                                )
                            },
                        ),
                        None => project_and_verify_ranked_root_v1(
                            semantic,
                            &callable_effects,
                            selection,
                            input,
                            *source_root,
                            root_references,
                            facts,
                        ),
                    }
                })
                .map_err(|error| {
                    error.with_deterministic_root_context(
                        semantic_root,
                        selection.body(),
                        input.logical_name.as_bytes(),
                    )
                })?;
            if root.kernel_binding != input.kernel_binding {
                return Err(ProductionRankedProjectionErrorV1::Unsupported(
                    "a projected ranked root with a substituted kernel binding",
                ));
            }
            roots.push(root);
        }
        source
            .semantic_ssa()
            .verify_replay()
            .map_err(ProductionRankedProjectionErrorV1::SemanticSsa)?;
        Ok(roots.into_boxed_slice())
    })?;
    Ok(ProjectedReferenceRootsV1 {
        roots,
        references: root_reference_bindings,
    })
}

#[cfg(test)]
fn match_ranked_root_bindings_v1(
    root_inputs: &[ProductionRankedRootInputV1],
    semantic_roots: &[([u8; 32], SemanticFunctionIdV1)],
) -> Result<Vec<SemanticFunctionIdV1>, ProductionRankedProjectionErrorV1> {
    let inputs = root_inputs
        .iter()
        .map(source_launch_root_input_v1)
        .collect::<Vec<_>>();
    fe2o3_lower_mir_kernel::match_production_source_launch_root_bindings_v1(&inputs, semantic_roots)
        .map_err(source_launch_projection_error_v1)
}

fn project_and_verify_ranked_root_v1(
    semantic: &AdmittedInertSemanticMirV1,
    callable_effects: &DefinedCallableEmptyEffectSummariesV1,
    selection: SemanticKernelBodySelectionV1,
    input: &ProductionRankedRootInputV1,
    source_root: ProductionSourceLaunchRootV1,
    reference_bindings: &crate::reference_effect_v1::AuthenticatedReferenceEffectBindingsV1,
    assertion_facts: &mut impl ProjectedAssertionFactsV1,
) -> Result<ProductionRankedRootProgramV1, ProductionRankedProjectionErrorV1> {
    let function = semantic
        .functions()
        .get(selection.body().index() as usize)
        .ok_or(ProductionRankedProjectionErrorV1::Unsupported(
            "an out-of-range semantic kernel body",
        ))?;
    scalar_singleton_projection_v1::with_scalar_private_singletons_v1(
        semantic.types(),
        function,
        assertion_facts,
        |singletons, facts| {
            scalar_borrow_projection_v1::with_scalar_private_borrows_v1(
                semantic.types(),
                function,
                semantic.target(),
                facts,
                |borrows, facts| {
                    project_and_verify_ranked_root_with_singletons_v1(
                        semantic,
                        callable_effects,
                        selection,
                        input,
                        source_root,
                        reference_bindings,
                        facts,
                        singletons,
                        borrows,
                    )
                },
            )
        },
    )
}

#[allow(clippy::too_many_arguments)]
fn project_and_verify_ranked_root_with_singletons_v1(
    semantic: &AdmittedInertSemanticMirV1,
    callable_effects: &DefinedCallableEmptyEffectSummariesV1,
    selection: SemanticKernelBodySelectionV1,
    input: &ProductionRankedRootInputV1,
    source_root: ProductionSourceLaunchRootV1,
    reference_bindings: &crate::reference_effect_v1::AuthenticatedReferenceEffectBindingsV1,
    assertion_facts: &mut impl ProjectedAssertionFactsV1,
    singletons: &[u8],
    borrows: Option<&scalar_borrow_projection_v1::ScalarPrivateBorrowsV1<'_>>,
) -> Result<ProductionRankedRootProgramV1, ProductionRankedProjectionErrorV1> {
    multi_entry_induction_v1::with_scope(assertion_facts, |scope, facts| {
        project_and_verify_ranked_root_with_induction_scope_v1(
            semantic,
            callable_effects,
            selection,
            input,
            source_root,
            reference_bindings,
            facts,
            singletons,
            borrows,
            scope,
        )
    })
}

include!("production_ranked_projection_v1/root_recipe_core_v1.rs");

#[allow(clippy::too_many_arguments)]
fn project_and_verify_ranked_root_with_induction_scope_v1(
    semantic: &AdmittedInertSemanticMirV1,
    callable_effects: &DefinedCallableEmptyEffectSummariesV1,
    selection: SemanticKernelBodySelectionV1,
    input: &ProductionRankedRootInputV1,
    source_root: ProductionSourceLaunchRootV1,
    reference_bindings: &crate::reference_effect_v1::AuthenticatedReferenceEffectBindingsV1,
    assertion_facts: &mut impl ProjectedAssertionFactsV1,
    singletons: &[u8],
    borrows: Option<&scalar_borrow_projection_v1::ScalarPrivateBorrowsV1<'_>>,
    induction_scope: &mut multi_entry_induction_v1::Scope,
) -> Result<ProductionRankedRootProgramV1, ProductionRankedProjectionErrorV1> {
    with_prepared_ranked_root_recipe_v1(
        semantic,
        callable_effects,
        selection,
        input,
        source_root,
        reference_bindings,
        assertion_facts,
        singletons,
        borrows,
        induction_scope,
        |recipe, assertion_facts| {
            verify_prepared_ranked_root_recipe_v1(
                recipe,
                selection,
                input,
                source_root,
                reference_bindings,
                assertion_facts,
            )
        },
    )
}

fn projected_reference_gpu_writes_v2(
    types: &[SemanticTypeDeclV1],
    function: &SemanticFunctionDeclV1,
    callables: &[SemanticCallableDeclV1],
    blocks: &[ProductionRankedBlockV1],
    sources: &[ProjectedAccessSourceV1],
) -> Result<
    Vec<crate::production_reference_effect_join_v2::RankedGpuWriteV2>,
    ProductionRankedProjectionErrorV1,
> {
    let mut expressions = GpuSemanticExpressionResolverV2::with_ranked_reads(
        types, function, callables, blocks, sources,
    )?
    .with_scalar_callables_v1(callables)?;
    projected_reference_gpu_writes_inner_v2(function, callables, blocks, sources, &mut expressions)
}

fn projected_reference_gpu_writes_inner_v2<'a>(
    function: &'a SemanticFunctionDeclV1,
    callables: &[SemanticCallableDeclV1],
    blocks: &[ProductionRankedBlockV1],
    sources: &[ProjectedAccessSourceV1],
    expressions: &mut GpuSemanticExpressionResolverV2<'a>,
) -> Result<
    Vec<crate::production_reference_effect_join_v2::RankedGpuWriteV2>,
    ProductionRankedProjectionErrorV1,
> {
    let mut allocation_origins = HashMap::new();
    for block in blocks {
        for operation in block.operations() {
            match operation {
                ProductionRankedOperationV1::View {
                    result,
                    allocation_origin,
                    ..
                }
                | ProductionRankedOperationV1::ViewInSpace {
                    result,
                    allocation_origin,
                    ..
                } => {
                    allocation_origins
                        .insert(ProductionRankedValueV1::Local(*result), *allocation_origin);
                }
                _ => {}
            }
        }
    }
    let mut writes = Vec::new();
    for source in sources
        .iter()
        .filter(|source| source.access.writes_memory())
    {
        let operation = blocks
            .get(source.block)
            .and_then(|block| block.operations().get(source.operation))
            .ok_or(ProductionRankedProjectionErrorV1::Unsupported(
                "a projected write correspondence does not identify one ranked write",
            ))?;
        if matches!(
            operation,
            ProductionRankedOperationV1::AllocationEffect {
                memory_space: MemorySpaceAttr::Workgroup,
                ..
            }
        ) {
            continue;
        }
        let (view, indices) = match operation {
            ProductionRankedOperationV1::Access { view, indices, .. }
            | ProductionRankedOperationV1::AtomicAccess { view, indices, .. } => {
                (*view, indices.clone())
            }
            ProductionRankedOperationV1::PredicatedAccess { view, index, .. } => {
                (*view, vec![*index])
            }
            _ => {
                return Err(ProductionRankedProjectionErrorV1::Unsupported(
                    "a projected write correspondence does not identify one ranked write",
                ));
            }
        };
        let allocation_origin = allocation_origins.get(&view).copied().ok_or(
            ProductionRankedProjectionErrorV1::Unsupported(
                "a projected write view has no exact allocation origin",
            ),
        )?;
        let value = match source.semantic_site {
            Some(
                site @ ProjectedSemanticAccessSiteV1 {
                    statement: None, ..
                },
            ) if source.access == AccessKindAttr::Write
                && source.memory_space == MemorySpaceAttr::Global
                && matches!(
                    operation,
                    ProductionRankedOperationV1::Access {
                        kind: AccessKindAttr::Write,
                        ..
                    } | ProductionRankedOperationV1::PredicatedAccess {
                        kind: AccessKindAttr::Write,
                        ..
                    }
                ) =>
            {
                expressions.resolve_thread_write_v2(callables, site, source.source)
            }
            Some(ProjectedSemanticAccessSiteV1 {
                block,
                statement: Some(statement),
            }) => function
                .blocks()
                .get(block)
                .and_then(|block| block.statements().get(statement))
                .map_or(
                    Err("GPU write has no authenticated semantic MIR statement"),
                    |value| {
                        expressions.resolve_store_v2(
                            value.kind(),
                            ScalarAssignmentSiteV1 { block, statement },
                        )
                    },
                ),
            _ => Err("GPU write has no authenticated semantic MIR statement"),
        };
        writes.push(
            crate::production_reference_effect_join_v2::RankedGpuWriteV2 {
                block: source.block,
                operation: source.operation,
                allocation_origin,
                view,
                indices,
                value,
            },
        );
    }
    Ok(writes)
}

struct GpuSemanticExpressionResolverV2<'a> {
    types: &'a [SemanticTypeDeclV1],
    function: &'a SemanticFunctionDeclV1,
    definitions: SemanticAssertProofsV1<'a>,
    borrowed: HashSet<u32>,
    use_site: Option<ScalarAssignmentSiteV1>,
    visiting: HashSet<(u32, usize, usize)>,
    work: usize,
    loads: HashMap<*const SemanticRvalueV1, ProductionSemanticLoadV2>,
    place_loads: HashMap<*const SemanticPlaceV1, ProductionSemanticLoadV2>,
    inline_calls_v30: Option<gfx942_inline_value_projection_v30::InlineCallRosterV30<'a>>,
    scalar_callables: &'a [SemanticCallableDeclV1],
    scalar_calls: Vec<Option<(usize, &'a SemanticDirectCallV1)>>,
    helper_semantic: Option<&'a AdmittedInertSemanticMirV1>,
    helper_values: Option<&'a source_helper_value_context_v1::SourceHelperValues<'a>>,
    helper_meter: Option<&'a mut dyn helper_value_template_v1::Meter>,
    helper_reserved: usize,
}

fn semantic_rvalue_read_places_v2<'a>(
    value: &'a SemanticRvalueV1,
    places: &mut Vec<&'a SemanticPlaceV1>,
) {
    fn push_operand<'a>(operand: &'a SemanticOperandV1, places: &mut Vec<&'a SemanticPlaceV1>) {
        let (SemanticOperandV1::Copy(place) | SemanticOperandV1::Move(place)) = operand else {
            return;
        };
        if place
            .projections()
            .iter()
            .any(|projection| projection.kind() == SemanticProjectionKindV1::Dereference)
        {
            places.push(place);
        }
    }
    match value.kind() {
        SemanticRvalueKindV1::Load(load) => places.push(load.source()),
        SemanticRvalueKindV1::Use(operand)
        | SemanticRvalueKindV1::Unary { operand, .. }
        | SemanticRvalueKindV1::Cast { operand, .. } => push_operand(operand, places),
        SemanticRvalueKindV1::Binary { left, right, .. } => {
            push_operand(left, places);
            push_operand(right, places);
        }
        SemanticRvalueKindV1::CheckedBinary(binary) => {
            push_operand(binary.left(), places);
            push_operand(binary.right(), places);
        }
        SemanticRvalueKindV1::UncheckedBinary(binary) => {
            push_operand(binary.left(), places);
            push_operand(binary.right(), places);
        }
        SemanticRvalueKindV1::Aggregate(aggregate) => {
            for operand in aggregate.operands() {
                push_operand(operand, places);
            }
        }
        SemanticRvalueKindV1::Borrow { .. }
        | SemanticRvalueKindV1::AddressOf { .. }
        | SemanticRvalueKindV1::Length(_)
        | SemanticRvalueKindV1::Discriminant(_) => {}
    }
}

include!("production_ranked_projection_v1/read_source_index_v1.rs");
include!("production_ranked_projection_v1/statement_definition_index_v1.rs");

impl<'a> GpuSemanticExpressionResolverV2<'a> {
    fn new(
        types: &'a [SemanticTypeDeclV1],
        function: &'a SemanticFunctionDeclV1,
    ) -> Result<Self, ProductionRankedProjectionErrorV1> {
        let mut definitions = SemanticAssertProofsV1::new(types, function)?;
        let mut borrowed = HashSet::new();
        for statement in function
            .blocks()
            .iter()
            .flat_map(|block| block.statements())
        {
            let SemanticStatementKindV1::Assign(assignment) = statement.kind() else {
                continue;
            };
            if let SemanticRvalueKindV1::Borrow { place, .. }
            | SemanticRvalueKindV1::AddressOf { place, .. } = assignment.value().kind()
                && let Some(local) = local_definition_index(place)
            {
                borrowed.insert(local as u32);
            }
        }
        definitions.statement_definitions = Some(StatementDefinitionIndexV1::new(function)?);
        Ok(Self {
            types,
            function,
            definitions,
            borrowed,
            use_site: None,
            visiting: HashSet::new(),
            work: 0,
            loads: HashMap::new(),
            place_loads: HashMap::new(),
            inline_calls_v30: None,
            scalar_callables: &[],
            scalar_calls: Vec::new(),
            helper_semantic: None,
            helper_values: None,
            helper_meter: None,
            helper_reserved: 0,
        })
    }

    fn with_ranked_reads(
        types: &'a [SemanticTypeDeclV1],
        function: &'a SemanticFunctionDeclV1,
        callables: &'a [SemanticCallableDeclV1],
        blocks: &[ProductionRankedBlockV1],
        sources: &[ProjectedAccessSourceV1],
    ) -> Result<Self, ProductionRankedProjectionErrorV1> {
        let mut resolver =
            Self::new(types, function)?.with_gfx942_inline_callables_v30(callables)?;
        let mut allocation_origins = HashMap::new();
        for block in blocks {
            for operation in block.operations() {
                match operation {
                    ProductionRankedOperationV1::View {
                        result,
                        allocation_origin,
                        ..
                    }
                    | ProductionRankedOperationV1::ViewInSpace {
                        result,
                        allocation_origin,
                        ..
                    } => {
                        allocation_origins
                            .insert(ProductionRankedValueV1::Local(*result), *allocation_origin);
                    }
                    _ => {}
                }
            }
        }
        let read_sources = RankedReadSourceIndexV1::new(sources)?;
        for (source_index, source) in sources
            .iter()
            .enumerate()
            .filter(|(_, source)| source.access.reads_memory())
        {
            if source.access != AccessKindAttr::Read
                || source.memory_space != MemorySpaceAttr::Global
            {
                continue;
            }
            let Some(site) = source.semantic_site else {
                continue;
            };
            let Some(statement_index) = site.statement else {
                continue;
            };
            let Some(SemanticStatementKindV1::Assign(assignment)) = function
                .blocks()
                .get(site.block)
                .and_then(|block| block.statements().get(statement_index))
                .map(|statement| statement.kind())
            else {
                continue;
            };
            let mut read_places = Vec::new();
            semantic_rvalue_read_places_v2(assignment.value(), &mut read_places);
            let Some((ordinal, count)) = read_sources.get(source_index) else {
                continue;
            };
            if read_places.len() != count {
                continue;
            }
            let Some(read_place) = read_places.get(ordinal).copied() else {
                continue;
            };
            let Some(operation) = blocks
                .get(source.block)
                .and_then(|block| block.operations().get(source.operation))
            else {
                return Err(ProductionRankedProjectionErrorV1::Unsupported(
                    "a projected load correspondence does not identify one ranked read",
                ));
            };
            let (kind, view, indices) = match operation {
                ProductionRankedOperationV1::Access {
                    kind,
                    view,
                    indices,
                } => (*kind, *view, indices.clone()),
                ProductionRankedOperationV1::PredicatedAccess {
                    kind, view, index, ..
                } => (*kind, *view, vec![*index]),
                _ => {
                    return Err(ProductionRankedProjectionErrorV1::Unsupported(
                        "a projected load correspondence does not identify one ranked read",
                    ));
                }
            };
            if kind != AccessKindAttr::Read {
                return Err(ProductionRankedProjectionErrorV1::Unsupported(
                    "a projected scalar load changed ranked access kind",
                ));
            }
            let allocation_origin = allocation_origins.get(&view).copied().ok_or(
                ProductionRankedProjectionErrorV1::Unsupported(
                    "a projected load view has no exact allocation origin",
                ),
            )?;
            let scalar = resolver
                .scalar_v2(read_place.ty())
                .map_err(ProductionRankedProjectionErrorV1::Incomplete)?;
            let load = ProductionSemanticLoadV2 {
                block: u32::try_from(source.block).map_err(|_| {
                    ProductionRankedProjectionErrorV1::Unsupported(
                        "a projected load block exceeds the ranked identity width",
                    )
                })?,
                operation: u32::try_from(source.operation).map_err(|_| {
                    ProductionRankedProjectionErrorV1::Unsupported(
                        "a projected load operation exceeds the ranked identity width",
                    )
                })?,
                scalar,
                allocation_origin,
                view,
                indices: indices.into_boxed_slice(),
            };
            if resolver
                .place_loads
                .insert(read_place as *const SemanticPlaceV1, load.clone())
                .is_some()
            {
                return Err(ProductionRankedProjectionErrorV1::Incomplete(
                    "one semantic scalar read place maps to multiple ranked reads",
                ));
            }
            if matches!(assignment.value().kind(), SemanticRvalueKindV1::Load(_))
                && resolver
                    .loads
                    .insert(assignment.value() as *const SemanticRvalueV1, load)
                    .is_some()
            {
                return Err(ProductionRankedProjectionErrorV1::Incomplete(
                    "one semantic scalar load maps to multiple ranked reads",
                ));
            }
        }
        Ok(resolver)
    }

    fn resolve_store_v2(
        &mut self,
        kind: &'a SemanticStatementKindV1,
        site: ScalarAssignmentSiteV1,
    ) -> Result<ProductionSemanticExpressionV2, &'static str> {
        if !self
            .function
            .blocks()
            .get(site.block)
            .and_then(|block| block.statements().get(site.statement))
            .is_some_and(|statement| std::ptr::eq(statement.kind(), kind))
        {
            return Err("GPU write use site does not identify the exact semantic statement");
        }
        let previous = self.use_site.replace(site);
        let result = match kind {
            SemanticStatementKindV1::Assign(assignment) => {
                self.resolve_rvalue_v2(assignment.value())
            }
            SemanticStatementKindV1::Store(store) => self.resolve_operand_v2(store.value(), 0),
            _ => Err("GPU write semantic site is not a scalar assignment or store"),
        };
        self.use_site = previous;
        result
    }

    fn resolve_thread_write_v2(
        &mut self,
        callables: &[SemanticCallableDeclV1],
        site: ProjectedSemanticAccessSiteV1,
        source: SemanticSourceProvenanceV1,
    ) -> Result<ProductionSemanticExpressionV2, &'static str> {
        let block = self
            .function
            .blocks()
            .get(site.block)
            .ok_or("GPU write call site is outside the exact semantic function")?;
        if site.statement.is_some() || block.terminator().source() != source {
            return Err("GPU write call site does not identify the exact semantic terminator");
        }
        let SemanticTerminatorKindV1::Call(call) = block.terminator().kind() else {
            return Err("GPU write semantic terminator is not a direct call");
        };
        // Receiver and full callable ABI validation belong to the semantic importer.
        let Some(SemanticCallableDeclV1::CompilerIntrinsic {
            operation:
                SemanticCompilerIntrinsicOperationV1::WriteOnlyDisjointSliceWrite {
                    element,
                    witness,
                    kind: SemanticWriteOnlyDisjointWriteKindV1::Thread { .. },
                    ..
                },
            ..
        }) = callables.get(call.callee().index() as usize)
        else {
            return Err("GPU write call is not an authenticated write-only Thread intrinsic");
        };
        let [_, index, value] = call.arguments() else {
            return Err("GPU write-only Thread call argument count changed");
        };
        if index.ty() != *witness || value.ty() != *element {
            return Err("GPU write-only Thread call operand type changed");
        }
        let scalar = self.scalar_v2(*element)?;
        // The ranked projector already binds this call's guarded index and allocation.
        // Resolve its value at the terminator, after every statement in that block.
        let previous = self.use_site.replace(ScalarAssignmentSiteV1 {
            block: site.block,
            statement: block.statements().len(),
        });
        let result = self.resolve_operand_v2(value, 0).and_then(|value| {
            if value.scalar() == scalar {
                Ok(value)
            } else {
                Err("GPU write-only Thread value scalar type changed")
            }
        });
        self.use_site = previous;
        result
    }

    fn charge_v2(&mut self) -> Result<(), &'static str> {
        self.work = self
            .work
            .checked_add(1)
            .ok_or("GPU semantic expression work overflowed")?;
        if self.work > fe2o3_pliron::MAX_PRODUCTION_SEMANTIC_EXPRESSION_NODES_V2 {
            return Err("GPU semantic expression exceeds its bounded node budget");
        }
        Ok(())
    }

    fn require_depth_v2(depth: usize) -> Result<(), &'static str> {
        if depth > fe2o3_pliron::MAX_PRODUCTION_SEMANTIC_EXPRESSION_DEPTH_V2 {
            return Err("GPU semantic expression exceeds its bounded recursion depth");
        }
        Ok(())
    }

    fn scalar_v2(
        &self,
        ty: SemanticTypeIdV1,
    ) -> Result<ProductionSemanticScalarTypeV2, &'static str> {
        let Some(SemanticTypeShapeV1::Scalar(scalar)) = self
            .types
            .get(ty.index() as usize)
            .map(SemanticTypeDeclV1::shape)
        else {
            return Err("GPU semantic expression uses a non-scalar type");
        };
        match scalar {
            SemanticScalarTypeV1::Bool => Ok(ProductionSemanticScalarTypeV2::Bool),
            SemanticScalarTypeV1::Integer { signed, bits } if matches!(bits, 8 | 16 | 32 | 64) => {
                Ok(ProductionSemanticScalarTypeV2::Integer {
                    signed: *signed,
                    bits: *bits,
                })
            }
            SemanticScalarTypeV1::Float { bits } if matches!(bits, 32 | 64) => {
                Ok(ProductionSemanticScalarTypeV2::Float { bits: *bits })
            }
            SemanticScalarTypeV1::Char
            | SemanticScalarTypeV1::Integer { .. }
            | SemanticScalarTypeV1::Float { .. } => {
                Err("GPU semantic scalar width or character semantics are unsupported")
            }
        }
    }

    fn resolve_operand_v2(
        &mut self,
        operand: &'a SemanticOperandV1,
        depth: usize,
    ) -> Result<ProductionSemanticExpressionV2, &'static str> {
        Self::require_depth_v2(depth)?;
        self.charge_v2()?;
        match operand {
            SemanticOperandV1::Constant(constant) => {
                let scalar = self.scalar_v2(constant.ty())?;
                let SemanticConstantValueV1::Scalar(value) = constant.value() else {
                    return Err("GPU semantic expression constant is not an exact scalar");
                };
                let bits = u64::try_from(value.bits())
                    .map_err(|_| "GPU semantic expression constant exceeds 64 bits")?;
                Ok(ProductionSemanticExpressionV2::Constant { scalar, bits })
            }
            SemanticOperandV1::Copy(place) | SemanticOperandV1::Move(place) => {
                self.resolve_place_v2(place, depth)
            }
        }
    }

    fn resolve_place_v2(
        &mut self,
        place: &'a SemanticPlaceV1,
        depth: usize,
    ) -> Result<ProductionSemanticExpressionV2, &'static str> {
        self.resolve_projected_place_v2(place, &[], depth)
    }

    fn resolve_rvalue_v2(
        &mut self,
        value: &'a SemanticRvalueV1,
    ) -> Result<ProductionSemanticExpressionV2, &'static str> {
        self.resolve_rvalue_inner_v2(value, 0)
    }

    fn resolve_rvalue_inner_v2(
        &mut self,
        value: &'a SemanticRvalueV1,
        depth: usize,
    ) -> Result<ProductionSemanticExpressionV2, &'static str> {
        Self::require_depth_v2(depth)?;
        self.charge_v2()?;
        let result_scalar = self.scalar_v2(value.result_type())?;
        match value.kind() {
            SemanticRvalueKindV1::Use(operand) => {
                if operand.ty() != value.result_type() {
                    return Err("GPU semantic scalar alias changes type");
                }
                self.resolve_operand_v2(operand, depth + 1)
            }
            SemanticRvalueKindV1::Unary { operation, operand } => {
                let operation = match operation {
                    SemanticUnaryOpV1::Not => ProductionSemanticUnaryOpV2::Not,
                    SemanticUnaryOpV1::Negate => ProductionSemanticUnaryOpV2::Negate,
                    SemanticUnaryOpV1::PointerMetadata => {
                        return Err("GPU semantic pointer metadata is not scalar arithmetic");
                    }
                };
                Ok(ProductionSemanticExpressionV2::Unary {
                    operation,
                    scalar: result_scalar,
                    operand: Box::new(self.resolve_operand_v2(operand, depth + 1)?),
                })
            }
            SemanticRvalueKindV1::Binary {
                operation,
                left,
                right,
            } => self.resolve_binary_v2(
                *operation,
                // Post-rustc semantic MIR distinguishes plain wrapping
                // arithmetic from CheckedBinary and UncheckedBinary nodes.
                ProductionOverflowContractV2::Wrapping,
                result_scalar,
                left,
                right,
                depth,
            ),
            SemanticRvalueKindV1::CheckedBinary(checked) => self.resolve_checked_binary_v2(
                checked.operation(),
                result_scalar,
                checked.left(),
                checked.right(),
                depth,
            ),
            SemanticRvalueKindV1::UncheckedBinary(unchecked) => self.resolve_unchecked_binary_v2(
                unchecked.operation(),
                result_scalar,
                unchecked.left(),
                unchecked.right(),
                depth,
            ),
            SemanticRvalueKindV1::Cast { kind, operand } => {
                let source = self.scalar_v2(operand.ty())?;
                let kind = match (*kind, source, result_scalar) {
                    (
                        SemanticCastKindV1::Integer,
                        ProductionSemanticScalarTypeV2::Integer { .. },
                        ProductionSemanticScalarTypeV2::Integer { .. },
                    ) => ProductionSemanticCastV2::Integer,
                    (
                        SemanticCastKindV1::Integer,
                        ProductionSemanticScalarTypeV2::Float { .. },
                        ProductionSemanticScalarTypeV2::Integer { .. },
                    ) => ProductionSemanticCastV2::FloatToIntegerSaturating,
                    (
                        SemanticCastKindV1::Float,
                        ProductionSemanticScalarTypeV2::Integer { .. },
                        ProductionSemanticScalarTypeV2::Float { .. },
                    ) => ProductionSemanticCastV2::IntegerToFloat,
                    (
                        SemanticCastKindV1::Float,
                        ProductionSemanticScalarTypeV2::Float { .. },
                        ProductionSemanticScalarTypeV2::Float { .. },
                    ) => ProductionSemanticCastV2::FloatToFloat,
                    (SemanticCastKindV1::Integer | SemanticCastKindV1::Float, _, _) => {
                        return Err("GPU numeric cast has unsupported source or target type");
                    }
                    (
                        SemanticCastKindV1::Pointer
                        | SemanticCastKindV1::PointerExposeProvenance
                        | SemanticCastKindV1::PointerWithExposedProvenance
                        | SemanticCastKindV1::Transmute,
                        _,
                        _,
                    ) => {
                        return Err("GPU pointer or transmute cast is outside scalar refinement");
                    }
                };
                Ok(ProductionSemanticExpressionV2::Cast {
                    kind,
                    source,
                    target: result_scalar,
                    operand: Box::new(self.resolve_operand_v2(operand, depth + 1)?),
                })
            }
            SemanticRvalueKindV1::Load(_) => self
                .loads
                .get(&(value as *const SemanticRvalueV1))
                .cloned()
                .map(ProductionSemanticExpressionV2::Load)
                .ok_or("GPU semantic RHS load has no exact ranked read correspondence"),
            _ => Err("GPU semantic rvalue is outside typed scalar refinement V2"),
        }
    }

    fn resolve_checked_binary_v2(
        &mut self,
        operation: SemanticCheckedBinaryOpV1,
        scalar: ProductionSemanticScalarTypeV2,
        left: &'a SemanticOperandV1,
        right: &'a SemanticOperandV1,
        depth: usize,
    ) -> Result<ProductionSemanticExpressionV2, &'static str> {
        let operation = match operation {
            SemanticCheckedBinaryOpV1::Add => ProductionSemanticBinaryOpV2::Add,
            SemanticCheckedBinaryOpV1::Subtract => ProductionSemanticBinaryOpV2::Subtract,
            SemanticCheckedBinaryOpV1::Multiply => ProductionSemanticBinaryOpV2::Multiply,
        };
        self.binary_expression_v2(
            operation,
            ProductionOverflowContractV2::Checked,
            scalar,
            left,
            right,
            depth,
        )
    }

    fn resolve_unchecked_binary_v2(
        &mut self,
        _operation: SemanticUncheckedBinaryOpV1,
        _scalar: ProductionSemanticScalarTypeV2,
        _left: &'a SemanticOperandV1,
        _right: &'a SemanticOperandV1,
        _depth: usize,
    ) -> Result<ProductionSemanticExpressionV2, &'static str> {
        Err("GPU unchecked arithmetic requires a retained dominating no-overflow proof")
    }

    fn resolve_binary_v2(
        &mut self,
        operation: SemanticBinaryOpV1,
        overflow: ProductionOverflowContractV2,
        result_scalar: ProductionSemanticScalarTypeV2,
        left: &'a SemanticOperandV1,
        right: &'a SemanticOperandV1,
        depth: usize,
    ) -> Result<ProductionSemanticExpressionV2, &'static str> {
        let comparison = match operation {
            SemanticBinaryOpV1::Equal => Some(ProductionSemanticComparisonV2::Equal),
            SemanticBinaryOpV1::LessThan => Some(ProductionSemanticComparisonV2::LessThan),
            SemanticBinaryOpV1::LessOrEqual => Some(ProductionSemanticComparisonV2::LessOrEqual),
            SemanticBinaryOpV1::NotEqual => Some(ProductionSemanticComparisonV2::NotEqual),
            SemanticBinaryOpV1::GreaterOrEqual => {
                Some(ProductionSemanticComparisonV2::GreaterOrEqual)
            }
            SemanticBinaryOpV1::GreaterThan => Some(ProductionSemanticComparisonV2::GreaterThan),
            _ => None,
        };
        if let Some(operation) = comparison {
            let lhs = self.resolve_operand_v2(left, depth + 1)?;
            let rhs = self.resolve_operand_v2(right, depth + 1)?;
            return Ok(ProductionSemanticExpressionV2::Compare {
                operation,
                operand_scalar: lhs.scalar(),
                lhs: Box::new(lhs),
                rhs: Box::new(rhs),
            });
        }
        let operation = match operation {
            SemanticBinaryOpV1::Add => ProductionSemanticBinaryOpV2::Add,
            SemanticBinaryOpV1::Subtract => ProductionSemanticBinaryOpV2::Subtract,
            SemanticBinaryOpV1::Multiply => ProductionSemanticBinaryOpV2::Multiply,
            SemanticBinaryOpV1::Divide => ProductionSemanticBinaryOpV2::Divide,
            SemanticBinaryOpV1::Remainder => ProductionSemanticBinaryOpV2::Remainder,
            SemanticBinaryOpV1::BitXor => ProductionSemanticBinaryOpV2::BitXor,
            SemanticBinaryOpV1::BitAnd => ProductionSemanticBinaryOpV2::BitAnd,
            SemanticBinaryOpV1::BitOr => ProductionSemanticBinaryOpV2::BitOr,
            SemanticBinaryOpV1::ShiftLeft => ProductionSemanticBinaryOpV2::ShiftLeft,
            SemanticBinaryOpV1::ShiftRight => ProductionSemanticBinaryOpV2::ShiftRight,
            SemanticBinaryOpV1::Offset => {
                return Err("GPU pointer offset is outside scalar refinement");
            }
            SemanticBinaryOpV1::Equal
            | SemanticBinaryOpV1::LessThan
            | SemanticBinaryOpV1::LessOrEqual
            | SemanticBinaryOpV1::NotEqual
            | SemanticBinaryOpV1::GreaterOrEqual
            | SemanticBinaryOpV1::GreaterThan => unreachable!(),
        };
        self.binary_expression_v2(operation, overflow, result_scalar, left, right, depth)
    }

    fn binary_expression_v2(
        &mut self,
        operation: ProductionSemanticBinaryOpV2,
        overflow: ProductionOverflowContractV2,
        scalar: ProductionSemanticScalarTypeV2,
        left: &'a SemanticOperandV1,
        right: &'a SemanticOperandV1,
        depth: usize,
    ) -> Result<ProductionSemanticExpressionV2, &'static str> {
        Ok(ProductionSemanticExpressionV2::Binary {
            operation,
            scalar,
            overflow,
            lhs: Box::new(self.resolve_operand_v2(left, depth + 1)?),
            rhs: Box::new(self.resolve_operand_v2(right, depth + 1)?),
        })
    }
}

#[allow(
    clippy::too_many_arguments,
    reason = "Expand a checked initializer into the existing ranked block and source vectors"
)]
fn project_private_array_initializer_v1(
    types: &[SemanticTypeDeclV1],
    function: &SemanticFunctionDeclV1,
    statement: &fe2o3_mir_model::semantic_mir_v1::SemanticStatementV1,
    block: usize,
    statement_index: usize,
    projected_views: &mut ProjectedViewsV1<'_>,
    operations: &mut Vec<ProductionRankedOperationV1>,
    sources: &mut Vec<ProjectedAccessSourceV1>,
    next_value: &mut u32,
) -> Result<bool, ProductionRankedProjectionErrorV1> {
    // Statement/rvalue/tag, whole place, local key/lookup/role, and dispatch.
    projected_views.charge_private_array_work(8)?;
    let SemanticStatementKindV1::Assign(assignment) = statement.kind() else {
        return Ok(false);
    };
    let SemanticRvalueKindV1::Aggregate(aggregate) = assignment.value().kind() else {
        return Ok(false);
    };
    if aggregate.kind() != &SemanticAggregateKindV1::Array
        || !assignment.destination().projections().is_empty()
    {
        return Ok(false);
    }
    if function
        .locals()
        .get(assignment.destination().local().index() as usize)
        .is_none_or(|local| local.role().is_entry_argument())
    {
        return Ok(false);
    }
    let Some(length) = projected_views.private_array_initializer_count(block, statement_index)?
    else {
        // Only the destination is promoted. Preserve ordinary RHS projection,
        // including any independently supported memory reads in its operands.
        return Ok(false);
    };
    projected_views.charge_private_array_work(24)?;
    let place = assignment.destination();
    let Some(SemanticTypeShapeV1::Array {
        element,
        length: declared_length,
    }) = types.get(place.ty().index() as usize).map(|ty| ty.shape())
    else {
        return Err(ProductionRankedProjectionErrorV1::Unsupported(
            "checked initializer source type changed",
        ));
    };
    if length != *declared_length || length == 0 {
        return Err(ProductionRankedProjectionErrorV1::Unsupported(
            "checked initializer extent changed",
        ));
    }
    let count = usize::try_from(length).map_err(|_| {
        ProductionRankedProjectionErrorV1::Unsupported("initializer extent does not fit host")
    })?;
    let additional = count
        .checked_mul(2)
        .and_then(|count| count.checked_add(1))
        .ok_or(ProductionRankedProjectionErrorV1::Unsupported(
            "initializer ranked expansion overflows",
        ))?;
    reserve_projected_access(operations, sources, additional)?;
    sources.try_reserve(count).map_err(|_| {
        ProductionRankedProjectionErrorV1::Unsupported("initializer source rows cannot be reserved")
    })?;
    let width = type_width(types, *element)?;
    let origin = PRIVATE_ALLOCATION_ORIGIN_TAG_V1
        .checked_add(u64::from(place.local().index()))
        .and_then(|value| value.checked_add(1))
        .ok_or(ProductionRankedProjectionErrorV1::Unsupported(
            "private initializer origin overflows",
        ))?;
    projected_views.charge_private_array_work(12)?;
    let view_slot = projected_views
        .get_mut(place.local().index() as usize)
        .ok_or(ProductionRankedProjectionErrorV1::Unsupported(
            "private initializer view slot is absent",
        ))?;
    let view = if let Some(view) = view_slot {
        if view.element_width != width
            || !view.writable
            || view.shape.as_slice() != [length]
            || !view.dynamic_extents.is_empty()
            || view.memory_space != MemorySpaceAttr::Private
            || view.allocation_origin != origin
            || view.noalias_class != origin
        {
            return Err(ProductionRankedProjectionErrorV1::Incomplete(
                "one semantic allocation used through inconsistent ranked views",
            ));
        }
        view.result
    } else {
        let result = next_value_id(next_value)?;
        operations.push(ProductionRankedOperationV1::ViewInSpace {
            result,
            element_width: width,
            writable: true,
            shape: vec![length],
            dynamic_extents: Vec::new(),
            memory_space: MemorySpaceAttr::Private,
            allocation_origin: origin,
            noalias_class: origin,
        });
        *view_slot = Some(ProjectedViewV1 {
            result,
            element_width: width,
            writable: true,
            shape: vec![length],
            dynamic_extents: Vec::new(),
            memory_space: MemorySpaceAttr::Private,
            allocation_origin: origin,
            noalias_class: origin,
        });
        result
    };
    for component in 0..length {
        projected_views.charge_private_array_work(16)?;
        let index = next_value_id(next_value)?;
        operations.push(ProductionRankedOperationV1::IndexConstant {
            result: index,
            value: component,
        });
        let operation = operations.len();
        operations.push(ProductionRankedOperationV1::Access {
            kind: AccessKindAttr::Write,
            view: ProductionRankedValueV1::Local(view),
            indices: vec![ProductionRankedValueV1::Local(index)],
        });
        sources.push(ProjectedAccessSourceV1 {
            block: 0,
            operation,
            access: AccessKindAttr::Write,
            memory_space: MemorySpaceAttr::Private,
            source: statement.source(),
            output_extent: None,
            semantic_site: None,
        });
    }
    Ok(true)
}

fn private_array_write_source_v1(
    types: &[SemanticTypeDeclV1],
    function: &SemanticFunctionDeclV1,
    source: &ProjectedAccessSourceV1,
    component: u32,
) -> bool {
    let Some(site) = source.semantic_site else {
        return false;
    };
    let Some(statement) = site.statement.and_then(|statement| {
        function
            .blocks()
            .get(site.block)?
            .statements()
            .get(statement)
    }) else {
        return false;
    };
    if let SemanticStatementKindV1::Assign(assignment) = statement.kind()
        && let SemanticRvalueKindV1::Aggregate(aggregate) = assignment.value().kind()
    {
        let place = assignment.destination();
        let Some(local) = function.locals().get(place.local().index() as usize) else {
            return false;
        };
        let Some(SemanticTypeShapeV1::Array { element, length }) =
            types.get(local.ty().index() as usize).map(|ty| ty.shape())
        else {
            return false;
        };
        let Some(SemanticOperandV1::Constant(constant)) =
            aggregate.operands().get(component as usize)
        else {
            return false;
        };
        return !local.role().is_entry_argument()
            && place.projections().is_empty()
            && place.ty() == local.ty()
            && assignment.value().result_type() == local.ty()
            && aggregate.kind() == &SemanticAggregateKindV1::Array
            && u64::try_from(aggregate.operands().len()).ok() == Some(*length)
            && constant.ty() == *element
            && matches!(constant.value(), SemanticConstantValueV1::Scalar(_))
            && matches!(
                types.get(element.index() as usize).map(|ty| ty.shape()),
                Some(SemanticTypeShapeV1::Scalar(_))
            )
            && source.access == AccessKindAttr::Write;
    }
    let (destination, value) = match statement.kind() {
        SemanticStatementKindV1::Assign(assignment) => {
            let SemanticRvalueKindV1::Use(value) = assignment.value().kind() else {
                return false;
            };
            (assignment.destination(), value)
        }
        SemanticStatementKindV1::Store(store)
            if store.volatility() == SemanticVolatilityV1::NonVolatile
                && store.atomic().is_none() =>
        {
            (store.destination(), store.value())
        }
        _ => return false,
    };
    // Mixed private reads and indexed writes still lack an exact recipe. Keep this
    // scalar destination subset closed independently of
    // the general RHS-before-destination projection order.
    let value_type = match value {
        SemanticOperandV1::Copy(place) | SemanticOperandV1::Move(place) => {
            if !place.projections().is_empty() {
                return false;
            }
            place.ty()
        }
        SemanticOperandV1::Constant(constant) => constant.ty(),
    };
    let [projection] = destination.projections() else {
        return false;
    };
    if !matches!(
        projection.kind(),
        SemanticProjectionKindV1::Index(_) | SemanticProjectionKindV1::ConstantIndex { .. }
    ) {
        return false;
    }
    let Some(local) = function.locals().get(destination.local().index() as usize) else {
        return false;
    };
    let Some(SemanticTypeShapeV1::Array { element, .. }) =
        types.get(local.ty().index() as usize).map(|ty| ty.shape())
    else {
        return false;
    };
    !local.role().is_entry_argument()
        && matches!(
            types.get(element.index() as usize).map(|ty| ty.shape()),
            Some(SemanticTypeShapeV1::Scalar(_))
        )
        && value_type == *element
        && destination.ty() == *element
        && projection.result_type() == *element
        && source.access == AccessKindAttr::Write
}

fn retained_ranked_access_source_v1(
    memory_space: MemorySpaceAttr,
    operation: &ProductionRankedOperationV1,
) -> bool {
    if memory_space == MemorySpaceAttr::Private
        && matches!(
            operation,
            ProductionRankedOperationV1::Access { .. }
                | ProductionRankedOperationV1::PredicatedAccess { .. }
        )
    {
        return false;
    }
    matches!(
        operation,
        ProductionRankedOperationV1::Access { .. }
            | ProductionRankedOperationV1::PredicatedAccess { .. }
            | ProductionRankedOperationV1::ValueAccess { .. }
            | ProductionRankedOperationV1::AtomicAccess { .. }
            | ProductionRankedOperationV1::AtomicValueAccess { .. }
            | ProductionRankedOperationV1::AllocationEffect { .. }
    )
}

#[path = "production_ranked_projection_v1/private_array_read_source_v1.rs"]
mod private_array_read_source_v1;

fn production_access_sources(
    types: &[SemanticTypeDeclV1],
    function: &SemanticFunctionDeclV1,
    blocks: &[ProductionRankedBlockV1],
    sources: &[ProjectedAccessSourceV1],
    facts: &mut impl ProjectedAssertionFactsV1,
) -> Result<Vec<ProductionRankedAccessSourceV1>, ProductionRankedProjectionErrorV1> {
    let mut ordinals = HashMap::<(usize, Option<usize>), u32>::new();
    let mut retained = Vec::new();
    retained.try_reserve(sources.len()).map_err(|_| {
        ProductionRankedProjectionErrorV1::Unsupported(
            "ranked access correspondence storage cannot be reserved",
        )
    })?;
    for source in sources {
        let operation = blocks
            .get(source.block)
            .and_then(|block| block.operations().get(source.operation))
            .ok_or(ProductionRankedProjectionErrorV1::Unsupported(
                "ranked access correspondence is outside the projected graph",
            ))?;
        if source.memory_space == MemorySpaceAttr::Private
            && matches!(
                operation,
                ProductionRankedOperationV1::Access {
                    kind: AccessKindAttr::Read,
                    ..
                }
            )
        {
            if !private_array_read_source_v1::retained_read(types, function, source, facts)? {
                continue;
            }
            if source
                .semantic_site
                .is_some_and(|site| ordinals.contains_key(&(site.block, site.statement)))
            {
                return Err(ProductionRankedProjectionErrorV1::Unsupported(
                    "private array read has duplicate source correspondence",
                ));
            }
        } else if !retained_ranked_access_source_v1(source.memory_space, operation) {
            // Scalar indexed writes are final effects. Literal initializer
            // components contain no RHS slice queries; later sites reset the
            // shared cursor. Other private reads remain excluded.
            if source.memory_space != MemorySpaceAttr::Private
                || !matches!(
                    operation,
                    ProductionRankedOperationV1::Access {
                        kind: AccessKindAttr::Write,
                        ..
                    }
                )
            {
                continue;
            }
            // Fixed source/statement/local/type/projection checks only;
            // no projection, ancestry or value-definition walk.
            // Existing indexed predicate40 + initializer-dispatch4 + exact
            // source-site component-counter lookup4 also covers the literal case.
            facts.charge_private_array_work(48)?;
            let component = source
                .semantic_site
                .and_then(|site| ordinals.get(&(site.block, site.statement)))
                .copied()
                .unwrap_or(0);
            if !private_array_write_source_v1(types, function, source, component) {
                continue;
            }
        }
        let site = source
            .semantic_site
            .ok_or(ProductionRankedProjectionErrorV1::Unsupported(
                "ranked access correspondence has no exact semantic site",
            ))?;
        let ordinal = ordinals.entry((site.block, site.statement)).or_default();
        let mut retained_source = ProductionRankedAccessSourceV1::new(
            u32::try_from(site.block).map_err(|_| {
                ProductionRankedProjectionErrorV1::Unsupported(
                    "semantic access block does not fit u32",
                )
            })?,
            site.statement.map(u32::try_from).transpose().map_err(|_| {
                ProductionRankedProjectionErrorV1::Unsupported(
                    "semantic access statement does not fit u32",
                )
            })?,
            *ordinal,
            u32::try_from(source.block).map_err(|_| {
                ProductionRankedProjectionErrorV1::Unsupported(
                    "ranked access block does not fit u32",
                )
            })?,
            u32::try_from(source.operation).map_err(|_| {
                ProductionRankedProjectionErrorV1::Unsupported(
                    "ranked access operation does not fit u32",
                )
            })?,
        );
        if let Some(extent) = source.output_extent {
            facts.charge_private_array_work(8)?;
            retained_source = retained_source.with_output_extent(extent);
        }
        retained.push(retained_source);
        *ordinal = ordinal
            .checked_add(1)
            .ok_or(ProductionRankedProjectionErrorV1::Unsupported(
                "semantic access ordinal overflow",
            ))?;
    }
    Ok(retained)
}

#[cfg(test)]
fn project_rust_bounds_checks(
    function: &SemanticFunctionDeclV1,
    first_argument: usize,
    known_indices: &[Option<ProjectedDisjointIndexV1>],
    operations: &mut Vec<ProductionRankedOperationV1>,
    next_value: &mut u32,
) -> Result<ProjectedBoundsChecksV1, ProductionRankedProjectionErrorV1> {
    project_rust_bounds_checks_with_ordinary_v1(
        &[],
        function,
        first_argument,
        known_indices,
        &[],
        None,
        operations,
        next_value,
        None,
    )
}

include!("production_ranked_projection_v1/dynamic_local_array_v1.rs");

#[allow(clippy::too_many_arguments)]
fn project_rust_bounds_checks_with_ordinary_v1(
    types: &[SemanticTypeDeclV1],
    function: &SemanticFunctionDeclV1,
    first_argument: usize,
    known_indices: &[Option<ProjectedDisjointIndexV1>],
    ordinary_indices: &[Option<ProjectedOrdinaryIndexV1>],
    enum_payload_dominance: Option<&SemanticEnumPayloadDominanceV1>,
    operations: &mut Vec<ProductionRankedOperationV1>,
    next_value: &mut u32,
    mut slice_extents_source: Option<&mut slice_extent_projection_v1::Context<'_>>,
) -> Result<ProjectedBoundsChecksV1, ProductionRankedProjectionErrorV1> {
    #[derive(Clone, Copy)]
    struct BoundsGuardV1 {
        condition_local: SemanticLocalIdV1,
        index_local: SemanticLocalIdV1,
        length_local: SemanticLocalIdV1,
        access_block: usize,
        must_authorize_access: bool,
    }

    let constants = constant_locals(function)?;
    let mut definitions = vec![BoundsLocalDefinitionV1::default(); function.locals().len()];
    let mut argument_count = first_argument;
    let mut predecessors = vec![Vec::new(); function.blocks().len()];
    for (block_index, block) in function.blocks().iter().enumerate() {
        for statement in block.statements() {
            let SemanticStatementKindV1::Assign(assignment) = statement.kind() else {
                continue;
            };
            if !assignment.destination().projections().is_empty() {
                continue;
            }
            let definition = definitions
                .get_mut(assignment.destination().local().index() as usize)
                .ok_or(ProductionRankedProjectionErrorV1::Unsupported(
                    "a Rust bounds-check definition outside the semantic local table",
                ))?;
            definition.count = definition.count.saturating_add(1);
            definition.value = Some(assignment.value());
            definition.length_source = match assignment.value().kind() {
                SemanticRvalueKindV1::Length(place) => Some(
                    if place.projections().iter().any(|projection| {
                        matches!(projection.kind(), SemanticProjectionKindV1::Field(_))
                    }) {
                        ProjectedBoundsExtentSourceV1::CanonicalSlice
                    } else {
                        ProjectedBoundsExtentSourceV1::Slice(place.local())
                    },
                ),
                SemanticRvalueKindV1::Unary {
                    operation: SemanticUnaryOpV1::PointerMetadata,
                    operand,
                } => match operand {
                    SemanticOperandV1::Copy(place) | SemanticOperandV1::Move(place) => {
                        Some(if place.projections().is_empty() {
                            ProjectedBoundsExtentSourceV1::Slice(place.local())
                        } else {
                            ProjectedBoundsExtentSourceV1::CanonicalSlice
                        })
                    }
                    SemanticOperandV1::Constant(_) => None,
                },
                _ => None,
            };
        }
        if let SemanticTerminatorKindV1::Call(call) = block.terminator().kind()
            && let Some(destination) = call.destination()
            && destination.place().projections().is_empty()
        {
            let definition = definitions
                .get_mut(destination.place().local().index() as usize)
                .ok_or(ProductionRankedProjectionErrorV1::Unsupported(
                    "a Rust bounds-check call result outside the semantic local table",
                ))?;
            definition.count = definition.count.saturating_add(1);
            definition.length_source = None;
            definition.value = None;
        }
        block
            .terminator()
            .kind()
            .try_for_each_edge::<ProductionRankedProjectionErrorV1>(|edge| {
                let target = edge.target().index() as usize;
                let target_predecessors = predecessors.get_mut(target).ok_or(
                    ProductionRankedProjectionErrorV1::Unsupported(
                        "a Rust bounds-check CFG edge outside the semantic block table",
                    ),
                )?;
                target_predecessors.push(block_index);
                Ok(())
            })?;
    }

    if !ordinary_indices.is_empty() && ordinary_indices.len() != function.locals().len() {
        return Err(ProductionRankedProjectionErrorV1::Unsupported(
            "ordinary intrinsic index facts do not match the semantic local table",
        ));
    }
    let mut local_values = if known_indices.is_empty() {
        vec![None; function.locals().len()]
    } else {
        if known_indices.len() != function.locals().len() {
            return Err(ProductionRankedProjectionErrorV1::Unsupported(
                "intrinsic index facts do not match the semantic local table",
            ));
        }
        known_indices
            .iter()
            .map(|index| index.map(|index| index.value))
            .collect()
    };
    // Separate MIR `Len` temporaries for one stable slice describe one ranked extent.
    let mut slice_extents = vec![None; function.locals().len()];
    let mut checks = Vec::new();
    let mut fixed_proofs = None;
    for (block_index, block) in function.blocks().iter().enumerate() {
        let guard = match block.terminator().kind() {
            SemanticTerminatorKindV1::Assert {
                condition,
                expected,
                message: SemanticAssertMessageV1::BoundsCheck { length, index },
                target,
                unwind,
            } => {
                if !*expected || !matches!(unwind, SemanticUnwindActionV1::Unreachable) {
                    return Err(ProductionRankedProjectionErrorV1::Incomplete(
                        "a Rust bounds check without the canonical success/unreachable shape",
                    ));
                }
                if constant_operand_value(length, &constants).is_some()
                    && constant_operand_value(index, &constants).is_some()
                {
                    // Literal array checks do not authorize a dynamic access. The
                    // projected ranked access retains both constants and the static
                    // shape verifier accepts or rejects the exact relation.
                    continue;
                }
                if matches!(length, SemanticOperandV1::Constant(_)) {
                    if fixed_proofs.is_none() {
                        fixed_proofs = Some(SemanticAssertProofsV1::new(types, function)?);
                    }
                    let access_block = target.target().index() as usize;
                    let (index_local, extent_value) = authenticate_fixed_array_guard_v1(
                        fixed_proofs
                            .as_mut()
                            .expect("initialized fixed-array analysis"),
                        block_index,
                        access_block,
                        condition,
                        index,
                        length,
                    )?;
                    if predecessors.get(access_block).map(Vec::as_slice) != Some(&[block_index])
                        || access_block == function.entry().index() as usize
                    {
                        return Err(ProductionRankedProjectionErrorV1::Incomplete(
                            "a fixed-array bounds-check success block is not uniquely controlled",
                        ));
                    }
                    reconcile_bounds_ordinary_index_v1(
                        block_index,
                        index_local,
                        ordinary_indices,
                        enum_payload_dominance,
                        &mut local_values,
                    )?;
                    let slot = &mut local_values[index_local.index() as usize];
                    let index = if let Some(value) = *slot {
                        value
                    } else {
                        let result = next_value_id(next_value)?;
                        reserve_operation(operations)?;
                        operations.push(ProductionRankedOperationV1::IndexUnknown { result });
                        let value = ProductionRankedValueV1::Local(result);
                        *slot = Some(value);
                        value
                    };
                    let result = next_value_id(next_value)?;
                    reserve_operation(operations)?;
                    operations.push(ProductionRankedOperationV1::IndexConstant {
                        result,
                        value: extent_value,
                    });
                    checks.try_reserve(1).map_err(|_| {
                        ProductionRankedProjectionErrorV1::Unsupported(
                            "fixed-array bounds-check storage cannot be reserved",
                        )
                    })?;
                    checks.push(ProjectedBoundsCheckV1 {
                        assertion_block: Some(block_index as u32),
                        access_block,
                        extent_source: ProjectedBoundsExtentSourceV1::FixedArray(extent_value),
                        index_local,
                        index,
                        extent: ProductionRankedValueV1::Local(result),
                        must_authorize_access: true,
                    });
                    continue;
                }
                BoundsGuardV1 {
                    condition_local: simple_operand_local(condition).ok_or(
                        ProductionRankedProjectionErrorV1::Incomplete(
                            "a Rust bounds-check condition without one exact local",
                        ),
                    )?,
                    index_local: simple_operand_local(index).ok_or(
                        ProductionRankedProjectionErrorV1::Incomplete(
                            "a Rust bounds-check index without one exact local",
                        ),
                    )?,
                    length_local: simple_operand_local(length).ok_or(
                        ProductionRankedProjectionErrorV1::Incomplete(
                            "a Rust bounds-check length without one exact local",
                        ),
                    )?,
                    access_block: target.target().index() as usize,
                    must_authorize_access: true,
                }
            }
            SemanticTerminatorKindV1::SwitchInt {
                discriminant,
                targets,
            } => {
                let Some(condition_local) = simple_operand_local(discriminant) else {
                    continue;
                };
                let Some((index_local, length_local)) =
                    exact_less_than_definition_v1(block, condition_local)
                else {
                    continue;
                };
                let length_definition = definitions.get(length_local.index() as usize).ok_or(
                    ProductionRankedProjectionErrorV1::Unsupported(
                        "a Rust bounds-check length outside the semantic local table",
                    ),
                )?;
                if length_definition.length_source.is_none() {
                    continue;
                }
                let [target] = targets.values() else {
                    return Err(ProductionRankedProjectionErrorV1::Incomplete(
                        "a branch-form Rust bounds check without one exact boolean target",
                    ));
                };
                let access_block = match target.value() {
                    0 => targets.otherwise().target().index() as usize,
                    1 => target.edge().target().index() as usize,
                    _ => {
                        return Err(ProductionRankedProjectionErrorV1::Incomplete(
                            "a branch-form Rust bounds check with a non-boolean switch value",
                        ));
                    }
                };
                BoundsGuardV1 {
                    condition_local,
                    index_local,
                    length_local,
                    access_block,
                    must_authorize_access: false,
                }
            }
            _ => continue,
        };
        let BoundsGuardV1 {
            condition_local,
            index_local,
            length_local,
            access_block,
            must_authorize_access,
        } = guard;
        let condition_definition = definitions.get(condition_local.index() as usize).ok_or(
            ProductionRankedProjectionErrorV1::Unsupported(
                "a Rust bounds-check condition outside the semantic local table",
            ),
        )?;
        let index_definition = definitions.get(index_local.index() as usize).ok_or(
            ProductionRankedProjectionErrorV1::Unsupported(
                "a Rust bounds-check index outside the semantic local table",
            ),
        )?;
        let length_definition = definitions.get(length_local.index() as usize).ok_or(
            ProductionRankedProjectionErrorV1::Unsupported(
                "a Rust bounds-check length outside the semantic local table",
            ),
        )?;
        let index_is_immutable_argument = index_definition.count == 0
            && matches!(
                function.locals()[index_local.index() as usize].role(),
                SemanticLocalRoleV1::Argument(_)
            );
        if condition_definition.count != 1
            || (index_definition.count != 1 && !index_is_immutable_argument)
            || length_definition.count != 1
        {
            return Err(ProductionRankedProjectionErrorV1::Incomplete(
                "a Rust bounds check whose condition, index, or length is not stable",
            ));
        }
        let extent_source = length_definition.length_source.ok_or(
            ProductionRankedProjectionErrorV1::Incomplete(
                "a Rust bounds-check length not derived from one exact slice",
            ),
        )?;
        if exact_less_than_definition_v1(block, condition_local)
            != Some((index_local, length_local))
        {
            return Err(ProductionRankedProjectionErrorV1::Incomplete(
                "a Rust bounds-check message not backed by its exact index < length condition",
            ));
        }
        if predecessors.get(access_block).map(Vec::as_slice) != Some(&[block_index]) {
            return Err(ProductionRankedProjectionErrorV1::Incomplete(
                "a Rust bounds-check success block not uniquely controlled by that check",
            ));
        }
        reconcile_bounds_ordinary_index_v1(
            block_index,
            index_local,
            ordinary_indices,
            enum_payload_dominance,
            &mut local_values,
        )?;
        let mut unknown_for = |local: SemanticLocalIdV1| -> Result<
            ProductionRankedValueV1,
            ProductionRankedProjectionErrorV1,
        > {
            let slot = local_values.get_mut(local.index() as usize).ok_or(
                ProductionRankedProjectionErrorV1::Unsupported(
                    "a Rust bounds-check operand outside the semantic local table",
                ),
            )?;
            if let Some(value) = *slot {
                return Ok(value);
            }
            let result = ProductionRankedValueIdV1::new(*next_value);
            *next_value =
                next_value
                    .checked_add(1)
                    .ok_or(ProductionRankedProjectionErrorV1::Unsupported(
                        "dynamic ranked-analysis value count overflow",
                    ))?;
            reserve_operation(operations)?;
            operations.push(ProductionRankedOperationV1::IndexUnknown { result });
            let value = ProductionRankedValueV1::Local(result);
            *slot = Some(value);
            Ok(value)
        };
        let slice_local = match extent_source {
            ProjectedBoundsExtentSourceV1::Slice(local) => Some(local),
            ProjectedBoundsExtentSourceV1::CanonicalSlice => None,
            ProjectedBoundsExtentSourceV1::FixedArray(_) => unreachable!(),
        };
        let prior_extent = if let Some(local) = slice_local {
            *slice_extents.get(local.index() as usize).ok_or(
                ProductionRankedProjectionErrorV1::Unsupported(
                    "a Rust bounds-check slice outside the semantic local table",
                ),
            )?
        } else {
            None
        };
        if let Some(slice_local) = slice_local.filter(|_| prior_extent.is_some()) {
            let slice_definition = definitions.get(slice_local.index() as usize).ok_or(
                ProductionRankedProjectionErrorV1::Unsupported(
                    "a Rust bounds-check slice outside the semantic local table",
                ),
            )?;
            let stable = match function.locals()[slice_local.index() as usize].role() {
                SemanticLocalRoleV1::Argument(_) => slice_definition.count == 0,
                _ => slice_definition.count == 1,
            };
            if !stable {
                return Err(ProductionRankedProjectionErrorV1::Incomplete(
                    "repeated Rust bounds checks derive an extent from a mutable slice local",
                ));
            }
        }
        let index = unknown_for(index_local)?;
        let source_extent = match slice_extents_source.as_deref_mut() {
            Some(source) => source.extent(
                types,
                function,
                length_local,
                &definitions,
                &mut argument_count,
            )?,
            None => None,
        };
        if slice_extents_source.is_some() && prior_extent.is_some() && source_extent != prior_extent
        {
            return Err(ProductionRankedProjectionErrorV1::Incomplete(
                "slice extent changed its source argument relation",
            ));
        }
        let extent = if let Some(extent) = prior_extent.or(source_extent) {
            if local_values[length_local.index() as usize].is_some_and(|prior| prior != extent) {
                return Err(ProductionRankedProjectionErrorV1::Incomplete(
                    "slice extent changed an existing ranked local identity",
                ));
            }
            local_values[length_local.index() as usize] = Some(extent);
            if let Some(slice_local) = slice_local {
                slice_extents[slice_local.index() as usize] = Some(extent);
            }
            extent
        } else {
            let extent = unknown_for(length_local)?;
            if let Some(slice_local) = slice_local {
                slice_extents[slice_local.index() as usize] = Some(extent);
            }
            extent
        };
        checks.try_reserve(1).map_err(|_| {
            ProductionRankedProjectionErrorV1::Unsupported(
                "Rust bounds-check projection storage cannot be reserved",
            )
        })?;
        checks.push(ProjectedBoundsCheckV1 {
            assertion_block: must_authorize_access.then_some(block_index as u32),
            access_block,
            extent_source,
            index_local,
            index,
            extent,
            must_authorize_access,
        });
    }
    Ok(ProjectedBoundsChecksV1 {
        checks,
        argument_count,
    })
}

fn exact_less_than_definition_v1(
    block: &fe2o3_mir_model::semantic_mir_v1::SemanticBasicBlockV1,
    condition_local: SemanticLocalIdV1,
) -> Option<(SemanticLocalIdV1, SemanticLocalIdV1)> {
    block.statements().iter().rev().find_map(|statement| {
        let SemanticStatementKindV1::Assign(assignment) = statement.kind() else {
            return None;
        };
        if !assignment.destination().projections().is_empty()
            || assignment.destination().local() != condition_local
        {
            return None;
        }
        let SemanticRvalueKindV1::Binary {
            operation: SemanticBinaryOpV1::LessThan,
            left,
            right,
        } = assignment.value().kind()
        else {
            return None;
        };
        Some((simple_operand_local(left)?, simple_operand_local(right)?))
    })
}

fn project_authenticated_capabilities_v1(
    callables: &[SemanticCallableDeclV1],
    function: &SemanticFunctionDeclV1,
    enum_payload_dominance: &SemanticEnumPayloadDominanceV1,
    local_allocations: &[Option<AllocationContractV1>],
    constants: &[Option<u64>],
) -> Result<ProjectedCapabilityEffectsV1, ProductionRankedProjectionErrorV1> {
    let block_count = function.blocks().len();
    let entry = function.entry().index() as usize;
    if entry >= block_count {
        return Err(ProductionRankedProjectionErrorV1::Unsupported(
            "a capability projection entry outside the semantic CFG",
        ));
    }
    let mut work = 0_usize;
    let pipeline_owners = workgroup_pipeline_local_owners_v1(callables, function)?;
    let initial_entries = propagate_capability_dataflow_v1(
        callables,
        function,
        enum_payload_dominance,
        local_allocations,
        constants,
        &pipeline_owners,
        &HashMap::new(),
        entry,
        &mut work,
    )?;
    let pipeline_payloads = collect_workgroup_pipeline_payloads_v1(
        callables,
        function,
        enum_payload_dominance,
        &pipeline_owners,
        &initial_entries,
        &mut work,
    )?;
    let entries = propagate_capability_dataflow_v1(
        callables,
        function,
        enum_payload_dominance,
        local_allocations,
        constants,
        &pipeline_owners,
        &pipeline_payloads,
        entry,
        &mut work,
    )?;

    let mut layouts = vec![None; block_count];
    let mut global_reads = vec![None; block_count];
    let mut transpose_workgroups = vec![None; block_count];
    let mut read_views = vec![None; block_count];
    for (block_index, entry_state) in entries.into_iter().enumerate() {
        let Some(mut state) = entry_state else {
            continue;
        };
        charge_capability_dataflow_work_v1(
            &mut work,
            state
                .len()
                .checked_add(function.blocks()[block_index].statements().len())
                .and_then(|work| work.checked_add(1))
                .ok_or(ProductionRankedProjectionErrorV1::Unsupported(
                    "capability replay work overflow",
                ))?,
        )?;
        transfer_capability_statements_v1(
            function,
            block_index,
            &mut state,
            enum_payload_dominance,
        )?;
        let effects = transfer_capability_terminator_v1(
            callables,
            function,
            block_index,
            &mut state,
            local_allocations,
            constants,
            &pipeline_owners,
            &pipeline_payloads,
            true,
        )?;
        layouts[block_index] = effects.layout;
        global_reads[block_index] = effects.global_read;
        transpose_workgroups[block_index] = effects.transpose_workgroup;
        read_views[block_index] = effects.read_view;
    }
    Ok(ProjectedCapabilityEffectsV1 {
        layouts,
        global_reads,
        transpose_workgroups,
        read_views,
    })
}

fn workgroup_pipeline_local_owners_v1(
    callables: &[SemanticCallableDeclV1],
    function: &SemanticFunctionDeclV1,
) -> Result<Vec<Option<usize>>, ProductionRankedProjectionErrorV1> {
    let mut owners = vec![None; function.locals().len()];
    for block in function.blocks() {
        let SemanticTerminatorKindV1::Call(call) = block.terminator().kind() else {
            continue;
        };
        if !matches!(
            callables.get(call.callee().index() as usize),
            Some(SemanticCallableDeclV1::CompilerIntrinsic {
                operation: SemanticCompilerIntrinsicOperationV1::WorkgroupPipelineCreate { .. },
                ..
            })
        ) {
            continue;
        }
        let destination = simple_call_destination(call)?.index() as usize;
        let slot =
            owners
                .get_mut(destination)
                .ok_or(ProductionRankedProjectionErrorV1::Unsupported(
                    "a workgroup pipeline destination is outside the semantic local table",
                ))?;
        if slot.replace(destination).is_some() {
            return Err(ProductionRankedProjectionErrorV1::Incomplete(
                "one Rust local receives multiple workgroup pipeline origins",
            ));
        }
    }
    propagate_workgroup_pipeline_aliases_v1(function, &mut owners)?;
    Ok(owners)
}

fn propagate_workgroup_pipeline_aliases_v1(
    function: &SemanticFunctionDeclV1,
    owners: &mut [Option<usize>],
) -> Result<(), ProductionRankedProjectionErrorV1> {
    if owners.len() != function.locals().len() {
        return Err(ProductionRankedProjectionErrorV1::Unsupported(
            "pipeline owner storage does not match the semantic local table",
        ));
    }
    if owners.iter().all(Option::is_none) {
        return Ok(());
    }
    let mut aliases = Vec::new();
    aliases.try_reserve_exact(owners.len()).map_err(|_| {
        ProductionRankedProjectionErrorV1::Unsupported(
            "pipeline alias adjacency storage cannot be reserved",
        )
    })?;
    aliases.resize_with(owners.len(), Vec::new);
    let mut alias_count = 0_usize;
    for block in function.blocks() {
        for statement in block.statements() {
            let SemanticStatementKindV1::Assign(assignment) = statement.kind() else {
                continue;
            };
            if !assignment.destination().projections().is_empty() {
                continue;
            }
            let source = match assignment.value().kind() {
                SemanticRvalueKindV1::Use(operand) => raw_operand_place(operand),
                SemanticRvalueKindV1::Borrow { place, .. }
                | SemanticRvalueKindV1::AddressOf { place, .. } => Some(place),
                _ => None,
            };
            let Some(source) = source else {
                continue;
            };
            push_local_provenance_edge_v1(
                &mut aliases,
                source.local().index() as usize,
                assignment.destination().local().index() as usize,
                &mut alias_count,
            )?;
        }
    }
    propagate_exact_local_origins_v1(
        owners,
        &aliases,
        "one Rust local may alias two workgroup pipelines",
    )
}

#[allow(clippy::too_many_arguments)]
fn propagate_capability_dataflow_v1(
    callables: &[SemanticCallableDeclV1],
    function: &SemanticFunctionDeclV1,
    enum_payload_dominance: &SemanticEnumPayloadDominanceV1,
    local_allocations: &[Option<AllocationContractV1>],
    constants: &[Option<u64>],
    pipeline_owners: &[Option<usize>],
    pipeline_payloads: &HashMap<usize, ProjectedMfmaOperandV1>,
    entry: usize,
    work: &mut usize,
) -> Result<Vec<Option<ProjectedCapabilityStateV1>>, ProductionRankedProjectionErrorV1> {
    let mut entries: Vec<Option<ProjectedCapabilityStateV1>> = vec![None; function.blocks().len()];
    entries[entry] = Some(HashMap::new());
    let mut worklist = VecDeque::from([entry]);
    let mut stored_entries = 0_usize;
    while let Some(block_index) = worklist.pop_front() {
        let entry_state = entries.get(block_index).and_then(Option::as_ref).ok_or(
            ProductionRankedProjectionErrorV1::Unsupported(
                "a queued capability dataflow block has no entry state",
            ),
        )?;
        charge_capability_dataflow_work_v1(
            work,
            entry_state.len().checked_add(1).ok_or(
                ProductionRankedProjectionErrorV1::Unsupported("capability clone work overflow"),
            )?,
        )?;
        let mut state = try_clone_capability_state_v1(entry_state)?;
        transfer_capability_statements_v1(
            function,
            block_index,
            &mut state,
            enum_payload_dominance,
        )?;
        transfer_capability_terminator_v1(
            callables,
            function,
            block_index,
            &mut state,
            local_allocations,
            constants,
            pipeline_owners,
            pipeline_payloads,
            false,
        )?;
        charge_capability_dataflow_work_v1(
            work,
            function.blocks()[block_index]
                .statements()
                .len()
                .checked_add(state.len())
                .ok_or(ProductionRankedProjectionErrorV1::Unsupported(
                    "capability dataflow work overflow",
                ))?,
        )?;
        if state.len() > MAX_PROJECTED_CAPABILITY_STATE_ENTRIES_V1 {
            return Err(ProductionRankedProjectionErrorV1::Unsupported(
                "capability dataflow exceeds the charged projection limit",
            ));
        }
        let successors = charged_unique_capability_successors_v1(
            function.blocks()[block_index].terminator().kind(),
            state.len(),
            work,
        )?;
        for target in successors {
            let target_entry =
                entries
                    .get_mut(target)
                    .ok_or(ProductionRankedProjectionErrorV1::Unsupported(
                        "a capability CFG edge outside the semantic function",
                    ))?;
            let changed = match target_entry {
                None => {
                    let next_stored_entries =
                        checked_capability_stored_entries_v1(stored_entries, state.len())?;
                    let successor_state = try_clone_capability_state_v1(&state)?;
                    stored_entries = next_stored_entries;
                    *target_entry = Some(successor_state);
                    true
                }
                Some(existing) => {
                    let additional = state
                        .keys()
                        .filter(|key| !existing.contains_key(key))
                        .count();
                    let next_stored_entries =
                        checked_capability_stored_entries_v1(stored_entries, additional)?;
                    let changed = merge_capability_states_v1(existing, &state)?;
                    stored_entries = next_stored_entries;
                    changed
                }
            };
            if changed {
                worklist.push_back(target);
            }
        }
    }
    Ok(entries)
}

fn collect_workgroup_pipeline_payloads_v1(
    callables: &[SemanticCallableDeclV1],
    function: &SemanticFunctionDeclV1,
    enum_payload_dominance: &SemanticEnumPayloadDominanceV1,
    pipeline_owners: &[Option<usize>],
    entries: &[Option<ProjectedCapabilityStateV1>],
    work: &mut usize,
) -> Result<HashMap<usize, ProjectedMfmaOperandV1>, ProductionRankedProjectionErrorV1> {
    let mut payloads = HashMap::new();
    for (block_index, block) in function.blocks().iter().enumerate() {
        let SemanticTerminatorKindV1::Call(call) = block.terminator().kind() else {
            continue;
        };
        let Some(SemanticCallableDeclV1::CompilerIntrinsic {
            operation: SemanticCompilerIntrinsicOperationV1::WorkgroupPipelineWrite { element, .. },
            ..
        }) = callables.get(call.callee().index() as usize)
        else {
            continue;
        };
        let Some(entry) = entries.get(block_index).and_then(Option::as_ref) else {
            continue;
        };
        charge_capability_dataflow_work_v1(work, entry.len().saturating_add(1))?;
        let mut state = try_clone_capability_state_v1(entry)?;
        transfer_capability_statements_v1(
            function,
            block_index,
            &mut state,
            enum_payload_dominance,
        )?;
        let [receiver, _, _, value] = call.arguments() else {
            return Err(ProductionRankedProjectionErrorV1::Incomplete(
                "a workgroup pipeline write lacks its exact receiver, epoch, index, and payload",
            ));
        };
        if value.ty() != *element {
            return Err(ProductionRankedProjectionErrorV1::Incomplete(
                "a workgroup pipeline write payload changed semantic type",
            ));
        }
        let owner = raw_operand_place(receiver)
            .and_then(|place| pipeline_owners.get(place.local().index() as usize))
            .copied()
            .flatten()
            .ok_or(ProductionRankedProjectionErrorV1::Incomplete(
                "a workgroup pipeline write lacks one compiler-owned origin",
            ))?;
        let Some(ProjectedCapabilityOriginV1::Operand(payload)) =
            capability_known_origin_v1(&state, value)
        else {
            return Err(ProductionRankedProjectionErrorV1::Incomplete(
                "a workgroup pipeline write lacks one authenticated typed payload",
            ));
        };
        match payloads.insert(owner, payload) {
            None => {}
            Some(existing) if existing == payload => {}
            Some(existing) => {
                payloads.insert(owner, existing);
                return Err(ProductionRankedProjectionErrorV1::Incomplete(
                    "one workgroup pipeline receives incompatible typed payload layouts",
                ));
            }
        }
    }
    Ok(payloads)
}

fn bind_capability_read_effects_to_call_blocks_v1(
    function: &SemanticFunctionDeclV1,
    global_reads: &[Option<AllocationContractV1>],
) -> Result<Vec<Option<ProjectedCapabilityReadEffectV1>>, ProductionRankedProjectionErrorV1> {
    if global_reads.len() != function.blocks().len() {
        return Err(ProductionRankedProjectionErrorV1::Unsupported(
            "capability read effects do not correspond one-to-one with semantic MIR blocks",
        ));
    }
    let mut effects = Vec::new();
    effects.try_reserve_exact(global_reads.len()).map_err(|_| {
        ProductionRankedProjectionErrorV1::Unsupported(
            "capability read effect storage cannot be reserved",
        )
    })?;
    for (block, allocation) in function.blocks().iter().zip(global_reads.iter().copied()) {
        effects.push(
            allocation.map(|allocation| ProjectedCapabilityReadEffectV1 {
                allocation,
                source: block.terminator().source(),
            }),
        );
    }
    Ok(effects)
}

fn project_read_value_to_ranked_v1(
    value: ProjectedReadValueV1,
    stable_argument_origins: &[Option<u32>],
    arguments: &mut [Option<u32>],
    next_argument: &mut usize,
    operations: &mut Vec<ProductionRankedOperationV1>,
    next_value: &mut u32,
) -> Result<ProductionRankedValueV1, ProductionRankedProjectionErrorV1> {
    match value {
        ProjectedReadValueV1::Constant(value) => {
            reserve_operation(operations)?;
            let result = next_value_id(next_value)?;
            operations.push(ProductionRankedOperationV1::IndexConstant { result, value });
            Ok(ProductionRankedValueV1::Local(result))
        }
        ProjectedReadValueV1::Local(local) => {
            let local_index = local.index() as usize;
            let origin = stable_argument_origins
                .get(local_index)
                .copied()
                .flatten()
                .unwrap_or(local.index()) as usize;
            let slot =
                arguments
                    .get_mut(origin)
                    .ok_or(ProductionRankedProjectionErrorV1::Unsupported(
                        "a strided read index origin outside the semantic local table",
                    ))?;
            let argument = match *slot {
                Some(argument) => argument,
                None => {
                    let argument = u32::try_from(*next_argument).map_err(|_| {
                        ProductionRankedProjectionErrorV1::Unsupported(
                            "too many strided read ranked arguments",
                        )
                    })?;
                    *next_argument = next_argument.checked_add(1).ok_or(
                        ProductionRankedProjectionErrorV1::Unsupported(
                            "strided read ranked argument count overflow",
                        ),
                    )?;
                    *slot = Some(argument);
                    argument
                }
            };
            Ok(ProductionRankedValueV1::Argument(argument))
        }
    }
}

#[allow(clippy::too_many_arguments)]
fn project_strided_read_effects_v1(
    types: &[fe2o3_mir_model::semantic_mir_v1::SemanticTypeDeclV1],
    function: &SemanticFunctionDeclV1,
    effects: &[Option<ProjectedReadViewAccessV1>],
    stable_argument_origins: &[Option<u32>],
    arguments: &mut [Option<u32>],
    next_argument: &mut usize,
    operations: &mut Vec<ProductionRankedOperationV1>,
    next_value: &mut u32,
) -> Result<Vec<Option<GuardedRankedAccessV1>>, ProductionRankedProjectionErrorV1> {
    if effects.len() != function.blocks().len() {
        return Err(ProductionRankedProjectionErrorV1::Unsupported(
            "strided read effects do not correspond one-to-one with semantic MIR blocks",
        ));
    }
    let mut views: HashMap<u64, (ProjectedReadViewV1, ProjectedViewV1)> = HashMap::new();
    let mut projected = Vec::new();
    projected.try_reserve_exact(effects.len()).map_err(|_| {
        ProductionRankedProjectionErrorV1::Unsupported(
            "strided read effect storage cannot be reserved",
        )
    })?;
    for (block, effect) in function.blocks().iter().zip(effects.iter().copied()) {
        let Some(effect) = effect else {
            projected.push(None);
            continue;
        };
        if effect.view.allocation.writable {
            return Err(ProductionRankedProjectionErrorV1::Unsupported(
                "a checked shared read view rooted in writable allocation authority",
            ));
        }
        let (view, rows, columns) = if let Some((source, view)) = views.get(&effect.view.root) {
            if *source != effect.view {
                return Err(ProductionRankedProjectionErrorV1::Unsupported(
                    "one checked read-view origin changed its element, extent, or allocation contract",
                ));
            }
            let [rows, columns] = view.dynamic_extents.as_slice() else {
                return Err(ProductionRankedProjectionErrorV1::Unsupported(
                    "a checked read view without exactly two dynamic extents",
                ));
            };
            (view.result, *rows, *columns)
        } else {
            let rows = project_read_value_to_ranked_v1(
                effect.view.rows,
                stable_argument_origins,
                arguments,
                next_argument,
                operations,
                next_value,
            )?;
            let columns = project_read_value_to_ranked_v1(
                effect.view.columns,
                stable_argument_origins,
                arguments,
                next_argument,
                operations,
                next_value,
            )?;
            reserve_operation(operations)?;
            let result = next_value_id(next_value)?;
            let view = ProjectedViewV1 {
                result,
                element_width: type_width(types, effect.view.element)?,
                writable: false,
                shape: vec![DYNAMIC_EXTENT, DYNAMIC_EXTENT],
                dynamic_extents: vec![rows, columns],
                memory_space: MemorySpaceAttr::Global,
                allocation_origin: effect.view.allocation.allocation_origin,
                noalias_class: effect.view.allocation.noalias_class,
            };
            operations.push(ProductionRankedOperationV1::ViewInSpace {
                result,
                element_width: view.element_width,
                writable: view.writable,
                shape: view.shape.clone(),
                dynamic_extents: view.dynamic_extents.clone(),
                memory_space: view.memory_space,
                allocation_origin: view.allocation_origin,
                noalias_class: view.noalias_class,
            });
            views.insert(effect.view.root, (effect.view, view));
            (result, rows, columns)
        };
        let row = project_read_value_to_ranked_v1(
            effect.row,
            stable_argument_origins,
            arguments,
            next_argument,
            operations,
            next_value,
        )?;
        let column = project_read_value_to_ranked_v1(
            effect.column,
            stable_argument_origins,
            arguments,
            next_argument,
            operations,
            next_value,
        )?;
        projected.push(Some(GuardedRankedAccessV1 {
            view,
            indices: vec![row, column],
            checked_success: None,
            comparisons: vec![(row, rows), (column, columns)],
            access: AccessKindAttr::Read,
            memory_space: MemorySpaceAttr::Global,
            source: block.terminator().source(),
            output_extent: None,
            semantic_site: None,
        }));
    }
    Ok(projected)
}

fn charge_capability_dataflow_work_v1(
    work: &mut usize,
    additional: usize,
) -> Result<(), ProductionRankedProjectionErrorV1> {
    *work = work
        .checked_add(additional)
        .ok_or(ProductionRankedProjectionErrorV1::Unsupported(
            "capability dataflow work overflow",
        ))?;
    if *work > MAX_PROJECTED_CAPABILITY_DATAFLOW_WORK_V1 {
        return Err(ProductionRankedProjectionErrorV1::Unsupported(
            "capability dataflow exceeds the charged projection limit",
        ));
    }
    Ok(())
}

fn charged_unique_capability_successors_v1(
    terminator: &SemanticTerminatorKindV1,
    state_entries: usize,
    work: &mut usize,
) -> Result<Vec<usize>, ProductionRankedProjectionErrorV1> {
    let mut unique = HashSet::new();
    terminator.try_for_each_edge::<ProductionRankedProjectionErrorV1>(|edge| {
        charge_capability_dataflow_work_v1(work, 1)?;
        let target = edge.target().index() as usize;
        if !unique.contains(&target) {
            unique.try_reserve(1).map_err(|_| {
                ProductionRankedProjectionErrorV1::Unsupported(
                    "capability successor storage cannot be reserved",
                )
            })?;
            unique.insert(target);
        }
        Ok(())
    })?;
    let mut successors = unique.into_iter().collect::<Vec<_>>();
    successors.sort_unstable();
    let merge_work =
        state_entries
            .checked_add(1)
            .ok_or(ProductionRankedProjectionErrorV1::Unsupported(
                "capability dataflow work overflow",
            ))?;
    for _ in &successors {
        charge_capability_dataflow_work_v1(work, merge_work)?;
    }
    Ok(successors)
}

fn transfer_capability_statements_v1(
    function: &SemanticFunctionDeclV1,
    block_index: usize,
    state: &mut (impl capability_state_access_v1::CapabilityStateAccessV1 + ?Sized),
    enum_payload_dominance: &SemanticEnumPayloadDominanceV1,
) -> Result<(), ProductionRankedProjectionErrorV1> {
    let block = &function.blocks()[block_index];
    let use_block = SemanticBlockIdV1::from_index(block_index as u32);
    for statement in block.statements() {
        match statement.kind() {
            SemanticStatementKindV1::Assign(assignment) => {
                let destination = assignment.destination().local().index() as usize;
                let origin = if assignment.destination().projections().is_empty() {
                    match assignment.value().kind() {
                        SemanticRvalueKindV1::Use(operand) => {
                            capability_origin_from_assignment_operand_v1(
                                operand,
                                state,
                                enum_payload_dominance,
                                use_block,
                            )
                        }
                        SemanticRvalueKindV1::Borrow { place, .. }
                        | SemanticRvalueKindV1::AddressOf { place, .. }
                            if place.projections().is_empty() =>
                        {
                            state.get(&(place.local().index() as usize)).copied()
                        }
                        SemanticRvalueKindV1::Aggregate(aggregate) => {
                            capability_origin_from_enum_aggregate_v1(
                                aggregate,
                                state,
                                enum_payload_dominance,
                                use_block,
                            )?
                        }
                        _ => None,
                    }
                } else {
                    None
                };
                consume_capability_rvalue_operands_v1(assignment.value().kind(), state);
                if !assignment.destination().projections().is_empty() {
                    invalidate_capability_local_v1(state, destination);
                    continue;
                }
                match origin {
                    Some(origin) => {
                        state.insert(destination, origin);
                    }
                    None => {
                        state.remove(&destination);
                    }
                }
            }
            SemanticStatementKindV1::Store(store) => {
                consume_capability_operand_v1(state, store.value());
            }
            SemanticStatementKindV1::AtomicRmw(atomic) => {
                consume_capability_operand_v1(state, atomic.value());
                invalidate_capability_place_v1(state, atomic.destination());
            }
            SemanticStatementKindV1::AtomicCompareExchange(atomic) => {
                consume_capability_operand_v1(state, atomic.expected());
                consume_capability_operand_v1(state, atomic.replacement());
                invalidate_capability_place_v1(state, atomic.destination());
            }
            SemanticStatementKindV1::SetDiscriminant { place, .. }
            | SemanticStatementKindV1::Deinitialize(place) => {
                invalidate_capability_place_v1(state, place);
            }
            SemanticStatementKindV1::StorageLive(local)
            | SemanticStatementKindV1::StorageDead(local) => {
                state.remove(&(local.index() as usize));
            }
            SemanticStatementKindV1::Assume(operand) => {
                consume_capability_operand_v1(state, operand);
            }
            SemanticStatementKindV1::Nop => {}
        }
    }
    Ok(())
}

fn consume_capability_rvalue_operands_v1(
    rvalue: &SemanticRvalueKindV1,
    state: &mut (impl capability_state_access_v1::CapabilityStateAccessV1 + ?Sized),
) {
    let _: Result<(), std::convert::Infallible> = rvalue.try_visit_operands(|operand| {
        consume_capability_operand_v1(state, operand);
        Ok(())
    });
}

fn consume_capability_operand_v1(
    state: &mut (impl capability_state_access_v1::CapabilityStateAccessV1 + ?Sized),
    operand: &SemanticOperandV1,
) {
    let place = match operand {
        SemanticOperandV1::Copy(place)
            if place.projections().is_empty()
                && state
                    .get(&(place.local().index() as usize))
                    .is_some_and(projected_value_is_shared_read_v1) =>
        {
            return;
        }
        SemanticOperandV1::Copy(place) | SemanticOperandV1::Move(place) => place,
        SemanticOperandV1::Constant(_) => return,
    };
    invalidate_capability_place_v1(state, place);
}

fn projected_value_is_shared_read_v1(value: &ProjectedCapabilityValueV1) -> bool {
    matches!(
        value,
        ProjectedCapabilityValueV1::Known(
            ProjectedCapabilityOriginV1::ReadViewResult(_)
                | ProjectedCapabilityOriginV1::ReadView(_)
        ) | ProjectedCapabilityValueV1::ConstructedEnum(ProjectedCapabilityEnumEnvelopeV1 {
            origin: ProjectedCapabilityOriginV1::ReadViewResult(_)
                | ProjectedCapabilityOriginV1::ReadView(_),
            ..
        })
    )
}

fn consume_capability_operands_v1(
    state: &mut (impl capability_state_access_v1::CapabilityStateAccessV1 + ?Sized),
    operands: &[SemanticOperandV1],
) {
    for operand in operands {
        consume_capability_operand_v1(state, operand);
    }
}

fn invalidate_capability_place_v1(
    state: &mut (impl capability_state_access_v1::CapabilityStateAccessV1 + ?Sized),
    place: &SemanticPlaceV1,
) {
    invalidate_capability_local_v1(state, place.local().index() as usize);
}

fn invalidate_capability_local_v1(
    state: &mut (impl capability_state_access_v1::CapabilityStateAccessV1 + ?Sized),
    local: usize,
) {
    if state.contains_key(&local) {
        state.insert(local, ProjectedCapabilityValueV1::Invalid);
    }
}

fn capability_origin_from_enum_aggregate_v1(
    aggregate: &fe2o3_mir_model::semantic_mir_v1::SemanticAggregateRvalueV1,
    state: &(impl capability_state_access_v1::CapabilityStateAccessV1 + ?Sized),
    enum_payload_dominance: &SemanticEnumPayloadDominanceV1,
    use_block: SemanticBlockIdV1,
) -> Result<Option<ProjectedCapabilityValueV1>, ProductionRankedProjectionErrorV1> {
    let (SemanticAggregateKindV1::EnumVariant(variant), [payload]) =
        (aggregate.kind(), aggregate.operands())
    else {
        return Ok(None);
    };
    capability_origin_from_assignment_operand_v1(payload, state, enum_payload_dominance, use_block)
        .map(|payload| wrap_capability_enum_value_v1(payload, *variant))
        .transpose()
}

fn capability_origin_from_assignment_operand_v1(
    operand: &SemanticOperandV1,
    state: &(impl capability_state_access_v1::CapabilityStateAccessV1 + ?Sized),
    enum_payload_dominance: &SemanticEnumPayloadDominanceV1,
    use_block: SemanticBlockIdV1,
) -> Option<ProjectedCapabilityValueV1> {
    let place = raw_operand_place(operand)?;
    if place.projections().is_empty() {
        return state.get(&(place.local().index() as usize)).copied();
    }
    let (carrier, variant) = enum_payload_projection(place)?;
    match state.get(&carrier).copied()? {
        ProjectedCapabilityValueV1::ConstructedEnum(envelope) => {
            unwrap_capability_enum_value_v1(envelope, variant)
        }
        ProjectedCapabilityValueV1::Known(ProjectedCapabilityOriginV1::ViewResult(view))
            if variant == 0
                && enum_payload_dominance
                    .availability(SemanticLocalIdV1::from_index(carrier as u32), variant)
                    .is_some_and(|availability| {
                        enum_payload_dominance.allows(availability, use_block)
                    }) =>
        {
            Some(ProjectedCapabilityValueV1::Known(
                ProjectedCapabilityOriginV1::View(view),
            ))
        }
        ProjectedCapabilityValueV1::Known(ProjectedCapabilityOriginV1::ReadViewResult(view))
            if variant == 0
                && enum_payload_dominance
                    .availability(SemanticLocalIdV1::from_index(carrier as u32), variant)
                    .is_some_and(|availability| {
                        enum_payload_dominance.allows(availability, use_block)
                    }) =>
        {
            Some(ProjectedCapabilityValueV1::Known(
                ProjectedCapabilityOriginV1::ReadView(view),
            ))
        }
        ProjectedCapabilityValueV1::Invalid => Some(ProjectedCapabilityValueV1::Invalid),
        _ => None,
    }
}

fn wrap_capability_enum_value_v1(
    payload: ProjectedCapabilityValueV1,
    variant: u32,
) -> Result<ProjectedCapabilityValueV1, ProductionRankedProjectionErrorV1> {
    let mut envelope = match payload {
        ProjectedCapabilityValueV1::Known(origin) => ProjectedCapabilityEnumEnvelopeV1 {
            origin,
            variants: [0; MAX_PROJECTED_CAPABILITY_ENUM_DEPTH_V1],
            depth: 0,
        },
        ProjectedCapabilityValueV1::ConstructedEnum(envelope) => envelope,
        ProjectedCapabilityValueV1::Invalid => return Ok(ProjectedCapabilityValueV1::Invalid),
    };
    let depth = usize::from(envelope.depth);
    if depth == MAX_PROJECTED_CAPABILITY_ENUM_DEPTH_V1 {
        return Err(ProductionRankedProjectionErrorV1::Unsupported(
            "capability enum transport exceeds the charged nesting limit",
        ));
    }
    envelope.variants[depth] = variant;
    envelope.depth =
        envelope
            .depth
            .checked_add(1)
            .ok_or(ProductionRankedProjectionErrorV1::Unsupported(
                "capability enum transport depth overflow",
            ))?;
    Ok(ProjectedCapabilityValueV1::ConstructedEnum(envelope))
}

fn unwrap_capability_enum_value_v1(
    mut envelope: ProjectedCapabilityEnumEnvelopeV1,
    variant: u32,
) -> Option<ProjectedCapabilityValueV1> {
    let outer = usize::from(envelope.depth).checked_sub(1)?;
    if envelope.variants[outer] != variant {
        return None;
    }
    envelope.variants[outer] = 0;
    envelope.depth -= 1;
    if envelope.depth == 0 {
        Some(ProjectedCapabilityValueV1::Known(envelope.origin))
    } else {
        Some(ProjectedCapabilityValueV1::ConstructedEnum(envelope))
    }
}

fn projected_read_value_v1(
    operand: &SemanticOperandV1,
    constants: &[Option<u64>],
) -> Option<ProjectedReadValueV1> {
    constant_operand_value(operand, constants)
        .map(ProjectedReadValueV1::Constant)
        .or_else(|| simple_operand_local(operand).map(ProjectedReadValueV1::Local))
}

fn authenticate_strided_read_v1(
    call: &SemanticDirectCallV1,
    state: &(impl capability_state_access_v1::CapabilityStateAccessV1 + ?Sized),
    element: SemanticTypeIdV1,
    constants: &[Option<u64>],
) -> Option<ProjectedReadViewAccessV1> {
    if call.arguments().len() != 4 {
        return None;
    }
    let ProjectedCapabilityOriginV1::ReadView(view) =
        capability_known_origin_v1(state, &call.arguments()[0])?
    else {
        return None;
    };
    if view.element != element {
        return None;
    }
    Some(ProjectedReadViewAccessV1 {
        view,
        row: projected_read_value_v1(&call.arguments()[1], constants)?,
        column: projected_read_value_v1(&call.arguments()[2], constants)?,
    })
}

const fn gfx950_transpose_workgroup_identity_v1(
    format: SemanticGfx950LdsTransposeFormatV1,
) -> (u64, u64) {
    match format {
        SemanticGfx950LdsTransposeFormatV1::Fp4E2M1 => (
            GFX950_TRANSPOSE_FP4_WORKGROUP_ALLOCATION_ORIGIN_V1,
            GFX950_TRANSPOSE_FP4_WORKGROUP_NOALIAS_CLASS_V1,
        ),
        SemanticGfx950LdsTransposeFormatV1::Fp8E4M3 => (
            GFX950_TRANSPOSE_FP8_WORKGROUP_ALLOCATION_ORIGIN_V1,
            GFX950_TRANSPOSE_FP8_WORKGROUP_NOALIAS_CLASS_V1,
        ),
    }
}
fn gfx950_transpose_profile_v1(
    format: SemanticGfx950LdsTransposeFormatV1,
) -> SemanticMfmaProfileV1 {
    match format {
        SemanticGfx950LdsTransposeFormatV1::Fp4E2M1 => SemanticMfmaProfileV1::Fp4E2M1F32M16N16K128,
        SemanticGfx950LdsTransposeFormatV1::Fp8E4M3 => SemanticMfmaProfileV1::Fp8E4M3F32M16N16K128,
    }
}

fn resolve_gfx950_transpose_tile_v1(
    operand: &SemanticOperandV1,
    state: &(impl capability_state_access_v1::CapabilityStateAccessV1 + ?Sized),
    expected_type: SemanticTypeIdV1,
    expected_state: ProjectedGfx950TransposeStateV1,
    expected_format: SemanticGfx950LdsTransposeFormatV1,
) -> Option<ProjectedGfx950TransposeTileV1> {
    if operand.ty() != expected_type {
        return None;
    }
    if let Some(ProjectedCapabilityOriginV1::Gfx950TransposeTile(tile)) =
        capability_known_origin_v1(state, operand)
    {
        return (tile.state == expected_state && tile.format == expected_format).then_some(tile);
    }
    if !matches!(
        operand,
        SemanticOperandV1::Constant(constant)
            if matches!(constant.value(), SemanticConstantValueV1::ZeroSized)
    ) {
        return None;
    }

    let mut candidates = state
        .precharged_values_v1()
        .filter_map(|value| match value {
            ProjectedCapabilityValueV1::Known(
                ProjectedCapabilityOriginV1::Gfx950TransposeTile(tile),
            ) if tile.state == expected_state && tile.format == expected_format => Some(*tile),
            _ => None,
        });
    let candidate = candidates.next()?;
    candidates.next().is_none().then_some(candidate)
}

fn project_gfx950_transpose_current_v1(
    call: &SemanticDirectCallV1,
    state: &(impl capability_state_access_v1::CapabilityStateAccessV1 + ?Sized),
    destination_type: SemanticTypeIdV1,
    tile_type: SemanticTypeIdV1,
    format: SemanticGfx950LdsTransposeFormatV1,
    token_root: u64,
) -> ProjectedCapabilityValueV1 {
    let lane = call
        .arguments()
        .first()
        .and_then(|operand| capability_known_origin_v1(state, operand));
    match lane {
        Some(ProjectedCapabilityOriginV1::Lane {
            root: lane_root,
            wave_width: 64,
        }) if call.arguments().len() == 1 && destination_type == tile_type => {
            ProjectedCapabilityValueV1::Known(ProjectedCapabilityOriginV1::Gfx950TransposeTile(
                ProjectedGfx950TransposeTileV1 {
                    state: ProjectedGfx950TransposeStateV1::Current,
                    format,
                    lane_root,
                    token_root,
                    source_allocation: None,
                },
            ))
        }
        _ => ProjectedCapabilityValueV1::Invalid,
    }
}

fn project_gfx950_transpose_stage_v1(
    call: &SemanticDirectCallV1,
    state: &(impl capability_state_access_v1::CapabilityStateAccessV1 + ?Sized),
    destination_type: SemanticTypeIdV1,
    input_tile_type: SemanticTypeIdV1,
    output_tile_type: SemanticTypeIdV1,
    format: SemanticGfx950LdsTransposeFormatV1,
    token_root: u64,
) -> ProjectedCapabilityValueV1 {
    let tile = call.arguments().first().and_then(|operand| {
        resolve_gfx950_transpose_tile_v1(
            operand,
            state,
            input_tile_type,
            ProjectedGfx950TransposeStateV1::Current,
            format,
        )
    });
    let view = call
        .arguments()
        .get(1)
        .and_then(|operand| capability_known_origin_v1(state, operand));
    match (tile, view) {
        (
            Some(ProjectedGfx950TransposeTileV1 {
                lane_root,
                source_allocation: None,
                ..
            }),
            // Stage consumes the row-major A-shaped K view; the verified
            // transpose mapping is what produces the role-B register fragment.
            Some(ProjectedCapabilityOriginV1::View(ProjectedMfmaViewV1 {
                role: SemanticMfmaOperandRoleV1::A,
                profile,
                storage_layout: SemanticMfmaStorageLayoutV1::RowMajor,
                allocation,
            })),
        ) if call.arguments().len() == 4
            && destination_type == output_tile_type
            && profile == gfx950_transpose_profile_v1(format) =>
        {
            ProjectedCapabilityValueV1::Known(ProjectedCapabilityOriginV1::Gfx950TransposeTile(
                ProjectedGfx950TransposeTileV1 {
                    state: ProjectedGfx950TransposeStateV1::Staged,
                    format,
                    lane_root,
                    token_root,
                    source_allocation: Some(allocation),
                },
            ))
        }
        _ => ProjectedCapabilityValueV1::Invalid,
    }
}

fn project_gfx950_transpose_publish_v1(
    call: &SemanticDirectCallV1,
    state: &(impl capability_state_access_v1::CapabilityStateAccessV1 + ?Sized),
    destination_type: SemanticTypeIdV1,
    input_tile_type: SemanticTypeIdV1,
    output_tile_type: SemanticTypeIdV1,
    format: SemanticGfx950LdsTransposeFormatV1,
    token_root: u64,
) -> ProjectedCapabilityValueV1 {
    let tile = call.arguments().first().and_then(|operand| {
        resolve_gfx950_transpose_tile_v1(
            operand,
            state,
            input_tile_type,
            ProjectedGfx950TransposeStateV1::Staged,
            format,
        )
    });
    match tile {
        Some(ProjectedGfx950TransposeTileV1 {
            lane_root,
            source_allocation: Some(source_allocation),
            ..
        }) if call.arguments().len() == 1 && destination_type == output_tile_type => {
            ProjectedCapabilityValueV1::Known(ProjectedCapabilityOriginV1::Gfx950TransposeTile(
                ProjectedGfx950TransposeTileV1 {
                    state: ProjectedGfx950TransposeStateV1::Published,
                    format,
                    lane_root,
                    token_root,
                    source_allocation: Some(source_allocation),
                },
            ))
        }
        _ => ProjectedCapabilityValueV1::Invalid,
    }
}

fn project_gfx950_transpose_read_v1(
    call: &SemanticDirectCallV1,
    state: &(impl capability_state_access_v1::CapabilityStateAccessV1 + ?Sized),
    destination_type: SemanticTypeIdV1,
    tile_type: SemanticTypeIdV1,
    fragment_type: SemanticTypeIdV1,
    contract: SemanticMfmaOperandContractV1,
    format: SemanticGfx950LdsTransposeFormatV1,
) -> ProjectedCapabilityValueV1 {
    let tile = call.arguments().first().and_then(|operand| {
        resolve_gfx950_transpose_tile_v1(
            operand,
            state,
            tile_type,
            ProjectedGfx950TransposeStateV1::Published,
            format,
        )
    });
    match tile {
        Some(ProjectedGfx950TransposeTileV1 {
            lane_root,
            source_allocation: Some(allocation),
            ..
        }) if call.arguments().len() == 1
            && destination_type == fragment_type
            && contract.role == SemanticMfmaOperandRoleV1::B
            && contract.profile == gfx950_transpose_profile_v1(format)
            && contract.register_distribution
                == SemanticMfmaRegisterDistributionV1::Gfx950M16N16K128
            && contract.wave_width == 64 =>
        {
            ProjectedCapabilityValueV1::Known(ProjectedCapabilityOriginV1::Operand(
                ProjectedMfmaOperandV1 {
                    contract,
                    storage_layout: SemanticMfmaStorageLayoutV1::RowMajor,
                    lane_root,
                    allocation,
                },
            ))
        }
        _ => ProjectedCapabilityValueV1::Invalid,
    }
}

fn transfer_capability_terminator_v1(
    callables: &[SemanticCallableDeclV1],
    function: &SemanticFunctionDeclV1,
    block_index: usize,
    state: &mut (impl capability_state_access_v1::CapabilityStateAccessV1 + ?Sized),
    local_allocations: &[Option<AllocationContractV1>],
    constants: &[Option<u64>],
    pipeline_owners: &[Option<usize>],
    pipeline_payloads: &HashMap<usize, ProjectedMfmaOperandV1>,
    require_authenticated_site: bool,
) -> Result<ProjectedCapabilityTerminatorEffectsV1, ProductionRankedProjectionErrorV1> {
    let terminator = function.blocks()[block_index].terminator().kind();
    let SemanticTerminatorKindV1::Call(call) = terminator else {
        match terminator {
            SemanticTerminatorKindV1::SwitchInt { discriminant, .. } => {
                consume_capability_operand_v1(state, discriminant);
            }
            SemanticTerminatorKindV1::TailCall(call) => {
                consume_capability_operands_v1(state, call.arguments());
            }
            SemanticTerminatorKindV1::Drop { place, .. } => {
                invalidate_capability_place_v1(state, place);
            }
            SemanticTerminatorKindV1::Assert { condition, .. } => {
                consume_capability_operand_v1(state, condition);
            }
            SemanticTerminatorKindV1::Goto(_)
            | SemanticTerminatorKindV1::FalseEdge { .. }
            | SemanticTerminatorKindV1::Return
            | SemanticTerminatorKindV1::UnwindResume
            | SemanticTerminatorKindV1::UnwindTerminate
            | SemanticTerminatorKindV1::Abort
            | SemanticTerminatorKindV1::Unreachable => {}
            SemanticTerminatorKindV1::Call(_) => unreachable!("matched call terminator"),
        }
        return Ok(ProjectedCapabilityTerminatorEffectsV1::default());
    };
    let intrinsic_operation = match callables.get(call.callee().index() as usize) {
        Some(SemanticCallableDeclV1::CompilerIntrinsic { operation, .. }) => Some(operation),
        _ => None,
    };
    if matches!(
        intrinsic_operation,
        Some(SemanticCompilerIntrinsicOperationV1::Bf16MatrixLoad { .. })
    ) {
        return Err(ProductionRankedProjectionErrorV1::Unsupported(
            "the retired Option-returning BF16 matrix load; use Bf16MatrixLoadZeroFilledV2",
        ));
    }
    let is_global_fragment_load = matches!(
        intrinsic_operation,
        Some(
            SemanticCompilerIntrinsicOperationV1::Bf16MatrixLoadZeroFilledV2 { .. }
                | SemanticCompilerIntrinsicOperationV1::Gfx950Fp4MatrixLoadM16K128 { .. }
                | SemanticCompilerIntrinsicOperationV1::Gfx950Fp8MatrixLoadM16K128 { .. }
        )
    );
    let is_gfx950_transpose = matches!(
        intrinsic_operation,
        Some(
            SemanticCompilerIntrinsicOperationV1::Gfx950LdsTransposeCurrent { .. }
                | SemanticCompilerIntrinsicOperationV1::Gfx950LdsTransposeStage { .. }
                | SemanticCompilerIntrinsicOperationV1::Gfx950LdsTransposePublish { .. }
                | SemanticCompilerIntrinsicOperationV1::Gfx950LdsTransposeRead { .. }
        )
    );
    let is_gfx950_transpose_stage = matches!(
        intrinsic_operation,
        Some(SemanticCompilerIntrinsicOperationV1::Gfx950LdsTransposeStage { .. })
    );
    if let Some(SemanticCompilerIntrinsicOperationV1::StridedReadView2DLoadOr { element, .. }) =
        intrinsic_operation
    {
        let read_view = authenticate_strided_read_v1(call, state, *element, constants);
        consume_capability_operands_v1(state, call.arguments());
        if let Some(destination) = call.destination() {
            invalidate_capability_place_v1(state, destination.place());
            if destination.place().projections().is_empty() {
                state.remove(&(destination.place().local().index() as usize));
            }
        }
        if read_view.is_none() && require_authenticated_site {
            return Err(ProductionRankedProjectionErrorV1::Incomplete(
                "a strided read without one dominating checked view payload and exact scalar operands",
            ));
        }
        return Ok(ProjectedCapabilityTerminatorEffectsV1 {
            read_view,
            ..ProjectedCapabilityTerminatorEffectsV1::default()
        });
    }
    let Some(destination) = call.destination() else {
        consume_capability_operands_v1(state, call.arguments());
        if is_gfx950_transpose {
            return Err(ProductionRankedProjectionErrorV1::Incomplete(
                "a gfx950 LDS transpose operation without one direct state result",
            ));
        }
        if is_global_fragment_load {
            return Err(ProductionRankedProjectionErrorV1::Incomplete(
                "a typed global fragment load without one direct local result",
            ));
        }
        return Ok(ProjectedCapabilityTerminatorEffectsV1::default());
    };
    if !destination.place().projections().is_empty() {
        consume_capability_operands_v1(state, call.arguments());
        invalidate_capability_place_v1(state, destination.place());
        if is_gfx950_transpose {
            return Err(ProductionRankedProjectionErrorV1::Incomplete(
                "a gfx950 LDS transpose operation into a projected destination",
            ));
        }
        if is_global_fragment_load {
            return Err(ProductionRankedProjectionErrorV1::Incomplete(
                "a typed global fragment load into a projected destination",
            ));
        }
        return Ok(ProjectedCapabilityTerminatorEffectsV1::default());
    }
    let destination_local = destination.place().local().index() as usize;
    let Some(operation) = intrinsic_operation else {
        consume_capability_operands_v1(state, call.arguments());
        state.remove(&destination_local);
        return Ok(ProjectedCapabilityTerminatorEffectsV1::default());
    };
    if matches!(call.unwind(), SemanticUnwindActionV1::Cleanup(_)) {
        return Err(ProductionRankedProjectionErrorV1::Incomplete(
            "a typed capability with cleanup control flow",
        ));
    }
    let root = ((block_index as u64) << 32) | destination_local as u64;
    let (origin, layout) = match operation {
        SemanticCompilerIntrinsicOperationV1::StridedReadView2DFromSharedSlice {
            result,
            element,
            ..
        } => {
            let allocation = call
                .arguments()
                .first()
                .and_then(transparent_operand_place)
                .and_then(|place| local_allocations.get(place.local().index() as usize))
                .copied()
                .flatten();
            let rows = call
                .arguments()
                .get(2)
                .and_then(|operand| projected_read_value_v1(operand, constants));
            let columns = call
                .arguments()
                .get(3)
                .and_then(|operand| projected_read_value_v1(operand, constants));
            let origin = match (allocation, rows, columns) {
                (Some(allocation), Some(rows), Some(columns))
                    if call.arguments().len() == 5
                        && destination.place().ty() == *result
                        && allocation.noalias_class == 1 =>
                {
                    ProjectedCapabilityValueV1::Known(ProjectedCapabilityOriginV1::ReadViewResult(
                        ProjectedReadViewV1 {
                            root,
                            element: *element,
                            allocation: AllocationContractV1 {
                                writable: false,
                                ..allocation
                            },
                            rows,
                            columns,
                        },
                    ))
                }
                _ => ProjectedCapabilityValueV1::Invalid,
            };
            (origin, None)
        }
        SemanticCompilerIntrinsicOperationV1::MatrixContextCurrent { context } => {
            if !call.arguments().is_empty() || destination.place().ty() != *context {
                (ProjectedCapabilityValueV1::Invalid, None)
            } else {
                (
                    ProjectedCapabilityValueV1::Known(ProjectedCapabilityOriginV1::MatrixContext {
                        root,
                    }),
                    None,
                )
            }
        }
        SemanticCompilerIntrinsicOperationV1::WaveLaneCurrent { lane, wave_width } => {
            if !call.arguments().is_empty() || destination.place().ty() != *lane {
                (ProjectedCapabilityValueV1::Invalid, None)
            } else {
                (
                    ProjectedCapabilityValueV1::Known(ProjectedCapabilityOriginV1::Lane {
                        root,
                        wave_width: *wave_width,
                    }),
                    None,
                )
            }
        }
        SemanticCompilerIntrinsicOperationV1::Gfx950LdsTransposeCurrent {
            tile, format, ..
        } => (
            project_gfx950_transpose_current_v1(
                call,
                state,
                destination.place().ty(),
                *tile,
                *format,
                root,
            ),
            None,
        ),
        SemanticCompilerIntrinsicOperationV1::Gfx950LdsTransposeStage {
            input_tile,
            output_tile,
            format,
            ..
        } => (
            project_gfx950_transpose_stage_v1(
                call,
                state,
                destination.place().ty(),
                *input_tile,
                *output_tile,
                *format,
                root,
            ),
            None,
        ),
        SemanticCompilerIntrinsicOperationV1::Gfx950LdsTransposePublish {
            input_tile,
            output_tile,
            format,
            ..
        } => (
            project_gfx950_transpose_publish_v1(
                call,
                state,
                destination.place().ty(),
                *input_tile,
                *output_tile,
                *format,
                root,
            ),
            None,
        ),
        SemanticCompilerIntrinsicOperationV1::Gfx950LdsTransposeRead {
            tile,
            fragment,
            contract,
            format,
            ..
        } => (
            project_gfx950_transpose_read_v1(
                call,
                state,
                destination.place().ty(),
                *tile,
                *fragment,
                *contract,
                *format,
            ),
            None,
        ),
        SemanticCompilerIntrinsicOperationV1::Bf16MatrixViewRowMajor {
            result,
            role,
            storage_layout,
            ..
        } => {
            let allocation = call
                .arguments()
                .first()
                .and_then(transparent_operand_place)
                .and_then(|place| local_allocations.get(place.local().index() as usize))
                .copied()
                .flatten();
            let origin = match allocation {
                Some(allocation)
                    if call.arguments().len() == 5 && destination.place().ty() == *result =>
                {
                    ProjectedCapabilityValueV1::Known(ProjectedCapabilityOriginV1::ViewResult(
                        ProjectedMfmaViewV1 {
                            role: *role,
                            profile: SemanticMfmaProfileV1::Bf16F32M16N16K16,
                            storage_layout: *storage_layout,
                            allocation,
                        },
                    ))
                }
                _ => ProjectedCapabilityValueV1::Invalid,
            };
            (origin, None)
        }
        SemanticCompilerIntrinsicOperationV1::Bf16MatrixViewColumnMajor { result, .. } => {
            let allocation = call
                .arguments()
                .first()
                .and_then(transparent_operand_place)
                .and_then(|place| local_allocations.get(place.local().index() as usize))
                .copied()
                .flatten();
            let origin = match allocation {
                Some(allocation)
                    if call.arguments().len() == 5 && destination.place().ty() == *result =>
                {
                    ProjectedCapabilityValueV1::Known(ProjectedCapabilityOriginV1::ViewResult(
                        ProjectedMfmaViewV1 {
                            role: SemanticMfmaOperandRoleV1::B,
                            profile: SemanticMfmaProfileV1::Bf16F32M16N16K16,
                            storage_layout: SemanticMfmaStorageLayoutV1::ColumnMajor,
                            allocation,
                        },
                    ))
                }
                _ => ProjectedCapabilityValueV1::Invalid,
            };
            (origin, None)
        }
        SemanticCompilerIntrinsicOperationV1::Gfx950Fp8MatrixViewRowMajor {
            result,
            role,
            storage_layout,
            ..
        } => {
            let allocation = call
                .arguments()
                .first()
                .and_then(transparent_operand_place)
                .and_then(|place| local_allocations.get(place.local().index() as usize))
                .copied()
                .flatten();
            let origin = match allocation {
                Some(allocation)
                    if call.arguments().len() == 5 && destination.place().ty() == *result =>
                {
                    ProjectedCapabilityValueV1::Known(ProjectedCapabilityOriginV1::ViewResult(
                        ProjectedMfmaViewV1 {
                            role: *role,
                            profile: SemanticMfmaProfileV1::Fp8E4M3F32M16N16K128,
                            storage_layout: *storage_layout,
                            allocation,
                        },
                    ))
                }
                _ => ProjectedCapabilityValueV1::Invalid,
            };
            (origin, None)
        }
        SemanticCompilerIntrinsicOperationV1::Gfx950Fp4MatrixViewRowMajor {
            result,
            role,
            storage_layout,
            ..
        } => {
            let allocation = call
                .arguments()
                .first()
                .and_then(transparent_operand_place)
                .and_then(|place| local_allocations.get(place.local().index() as usize))
                .copied()
                .flatten();
            let origin = match allocation {
                Some(allocation)
                    if call.arguments().len() == 5 && destination.place().ty() == *result =>
                {
                    ProjectedCapabilityValueV1::Known(ProjectedCapabilityOriginV1::ViewResult(
                        ProjectedMfmaViewV1 {
                            role: *role,
                            profile: SemanticMfmaProfileV1::Fp4E2M1F32M16N16K128,
                            storage_layout: *storage_layout,
                            allocation,
                        },
                    ))
                }
                _ => ProjectedCapabilityValueV1::Invalid,
            };
            (origin, None)
        }
        SemanticCompilerIntrinsicOperationV1::Bf16MatrixLoadZeroFilledV2 {
            fragment,
            contract,
            storage_layout,
            ..
        }
        | SemanticCompilerIntrinsicOperationV1::Gfx950Fp8MatrixLoadM16K128 {
            fragment,
            contract,
            storage_layout,
            ..
        }
        | SemanticCompilerIntrinsicOperationV1::Gfx950Fp4MatrixLoadM16K128 {
            fragment,
            contract,
            storage_layout,
            ..
        } => (
            project_tensor_load_origin_v1(
                call,
                state,
                destination.place().ty(),
                *fragment,
                *contract,
                *storage_layout,
            ),
            None,
        ),
        SemanticCompilerIntrinsicOperationV1::F32MatrixAccumulatorZero {
            fragment,
            contract,
            ..
        } => {
            let lane = call
                .arguments()
                .first()
                .and_then(|operand| capability_known_origin_v1(state, operand));
            let origin = match lane {
                Some(ProjectedCapabilityOriginV1::Lane {
                    root: lane_root,
                    wave_width,
                }) if call.arguments().len() == 1
                    && destination.place().ty() == *fragment
                    && wave_width == contract.wave_width =>
                {
                    ProjectedCapabilityValueV1::Known(ProjectedCapabilityOriginV1::Accumulator(
                        ProjectedMfmaAccumulatorV1 {
                            contract: *contract,
                            lane_root,
                            value_root: root,
                            flow_root: root,
                        },
                    ))
                }
                _ => ProjectedCapabilityValueV1::Invalid,
            };
            (origin, None)
        }
        SemanticCompilerIntrinsicOperationV1::WorkgroupPipelineRead { element, .. } => {
            let origin = call
                .arguments()
                .first()
                .and_then(raw_operand_place)
                .and_then(|place| pipeline_owners.get(place.local().index() as usize))
                .copied()
                .flatten()
                .and_then(|owner| pipeline_payloads.get(&owner).copied())
                .filter(|_| call.arguments().len() == 3 && destination.place().ty() == *element)
                .map(ProjectedCapabilityOriginV1::Operand)
                .map(ProjectedCapabilityValueV1::Known)
                .unwrap_or(ProjectedCapabilityValueV1::Invalid);
            (origin, None)
        }
        SemanticCompilerIntrinsicOperationV1::MatrixMultiplyAccumulate {
            accumulator_fragment,
            lhs,
            rhs,
            accumulator,
            ..
        } => match authenticate_tensor_instruction_read_v1(call, state, *lhs, *rhs, *accumulator) {
            Ok(authenticated) if destination.place().ty() == *accumulator_fragment => {
                // The semantic value root remains stable for loop refinement,
                // while the flow root identifies this exact tensor result for
                // layout propagation into a later instruction.
                let result = ProjectedMfmaAccumulatorV1 {
                    flow_root: root,
                    ..authenticated.accumulator
                };
                let binding = tensor_site_binding_v1(
                    authenticated,
                    root,
                    u16::try_from(call.arguments().len()).unwrap_or(u16::MAX),
                )
                .ok_or(ProductionRankedProjectionErrorV1::Incomplete(
                    "an MFMA call whose typed capability binding is invalid",
                ))?;
                (
                    ProjectedCapabilityValueV1::Known(ProjectedCapabilityOriginV1::Accumulator(
                        result,
                    )),
                    Some(ProductionRankedOperationV1::TensorLayout {
                        contract: authenticated.contract,
                        convergence: TensorConvergenceAttr::UniformSubgroup,
                        active_lanes: u32::from(authenticated.contract.subgroup_width),
                        binding: Some(binding),
                    }),
                )
            }
            Ok(_) => (ProjectedCapabilityValueV1::Invalid, None),
            Err(detail) if require_authenticated_site => {
                return Err(ProductionRankedProjectionErrorV1::Incomplete(detail));
            }
            Err(_) => (ProjectedCapabilityValueV1::Invalid, None),
        },
        _ => {
            consume_capability_operands_v1(state, call.arguments());
            state.remove(&destination_local);
            return Ok(ProjectedCapabilityTerminatorEffectsV1::default());
        }
    };
    consume_capability_operands_v1(state, call.arguments());
    state.insert(destination_local, origin);
    if require_authenticated_site
        && is_gfx950_transpose
        && origin == ProjectedCapabilityValueV1::Invalid
    {
        return Err(ProductionRankedProjectionErrorV1::Incomplete(
            "a gfx950 LDS transpose operation without its exact dominating Current-Stage-Publish state, format, view, and Wave64 lane",
        ));
    }
    if require_authenticated_site
        && matches!(
            operation,
            SemanticCompilerIntrinsicOperationV1::MatrixMultiplyAccumulate { .. }
        )
        && layout.is_none()
    {
        return Err(ProductionRankedProjectionErrorV1::Incomplete(
            "an MFMA call whose result type does not match its authenticated accumulator contract",
        ));
    }
    let global_read = match (is_global_fragment_load, is_gfx950_transpose_stage, origin) {
        (
            true,
            false,
            ProjectedCapabilityValueV1::Known(ProjectedCapabilityOriginV1::Operand(fragment)),
        ) => Some(fragment.allocation),
        (
            false,
            true,
            ProjectedCapabilityValueV1::Known(ProjectedCapabilityOriginV1::Gfx950TransposeTile(
                ProjectedGfx950TransposeTileV1 {
                    state: ProjectedGfx950TransposeStateV1::Staged,
                    source_allocation: Some(allocation),
                    ..
                },
            )),
        ) => Some(allocation),
        (true, false, _) => {
            return Err(ProductionRankedProjectionErrorV1::Incomplete(
                "a typed global fragment load without exact authenticated view, lane, allocation, and result provenance",
            ));
        }
        (false, true, _) => {
            return Err(ProductionRankedProjectionErrorV1::Incomplete(
                "a gfx950 LDS transpose stage without exact authenticated view, state token, lane, allocation, and result provenance",
            ));
        }
        (false, false, _) => None,
        (true, true, _) => unreachable!("transpose stage is not a direct fragment load"),
    };
    let transpose_workgroup = match operation {
        SemanticCompilerIntrinsicOperationV1::Gfx950LdsTransposeStage { format, .. } => {
            Some(ProjectedTransposeWorkgroupEffectV1 {
                access: AccessKindAttr::Write,
                format: *format,
            })
        }
        SemanticCompilerIntrinsicOperationV1::Gfx950LdsTransposeRead { format, .. } => {
            Some(ProjectedTransposeWorkgroupEffectV1 {
                access: AccessKindAttr::Read,
                format: *format,
            })
        }
        _ => None,
    };
    Ok(ProjectedCapabilityTerminatorEffectsV1 {
        layout,
        global_read,
        transpose_workgroup,
        read_view: None,
    })
}

fn authenticate_tensor_load_v1(
    call: &SemanticDirectCallV1,
    state: &(impl capability_state_access_v1::CapabilityStateAccessV1 + ?Sized),
    contract: SemanticMfmaOperandContractV1,
    storage_layout: SemanticMfmaStorageLayoutV1,
) -> Option<ProjectedMfmaOperandV1> {
    if call.arguments().len() != 4
        || (storage_layout == SemanticMfmaStorageLayoutV1::ColumnMajor
            && (contract.role != SemanticMfmaOperandRoleV1::B
                || contract.profile != SemanticMfmaProfileV1::Bf16F32M16N16K16))
    {
        return None;
    }
    let view = capability_known_origin_v1(state, &call.arguments()[0])?;
    let lane = capability_known_origin_v1(state, &call.arguments()[1])?;
    let ProjectedCapabilityOriginV1::View(view) = view else {
        return None;
    };
    let ProjectedCapabilityOriginV1::Lane {
        root: lane_root,
        wave_width,
    } = lane
    else {
        return None;
    };
    (view.role == contract.role
        && view.profile == contract.profile
        && view.storage_layout == storage_layout
        && wave_width == contract.wave_width)
        .then_some(ProjectedMfmaOperandV1 {
            contract,
            storage_layout,
            lane_root,
            allocation: view.allocation,
        })
}

#[allow(clippy::too_many_arguments)]
fn project_tensor_load_origin_v1(
    call: &SemanticDirectCallV1,
    state: &(impl capability_state_access_v1::CapabilityStateAccessV1 + ?Sized),
    destination_type: SemanticTypeIdV1,
    expected_output_type: SemanticTypeIdV1,
    contract: SemanticMfmaOperandContractV1,
    storage_layout: SemanticMfmaStorageLayoutV1,
) -> ProjectedCapabilityValueV1 {
    if destination_type != expected_output_type {
        return ProjectedCapabilityValueV1::Invalid;
    }
    let Some(fragment) = authenticate_tensor_load_v1(call, state, contract, storage_layout) else {
        return ProjectedCapabilityValueV1::Invalid;
    };
    ProjectedCapabilityValueV1::Known(ProjectedCapabilityOriginV1::Operand(fragment))
}

fn authenticate_tensor_instruction_v1(
    call: &SemanticDirectCallV1,
    state: &ProjectedCapabilityStateV1,
    lhs_contract: SemanticMfmaOperandContractV1,
    rhs_contract: SemanticMfmaOperandContractV1,
    accumulator_contract: SemanticMfmaAccumulatorContractV1,
) -> Result<AuthenticatedTensorInstructionV1, &'static str> {
    authenticate_tensor_instruction_read_v1(
        call,
        state,
        lhs_contract,
        rhs_contract,
        accumulator_contract,
    )
}

fn authenticate_tensor_instruction_read_v1(
    call: &SemanticDirectCallV1,
    state: &(impl tensor_capability_read_v1::CapabilityStateReadV1 + ?Sized),
    lhs_contract: SemanticMfmaOperandContractV1,
    rhs_contract: SemanticMfmaOperandContractV1,
    accumulator_contract: SemanticMfmaAccumulatorContractV1,
) -> Result<AuthenticatedTensorInstructionV1, &'static str> {
    if call.arguments().len() != 4 {
        return Err("an MFMA call without its exact context and three typed operands");
    }
    let Some(ProjectedCapabilityOriginV1::MatrixContext { root: context_root }) =
        tensor_capability_read_v1::capability_known_origin_read_v1(state, &call.arguments()[0])
    else {
        return Err("an MFMA call without dominating compiler-issued matrix context");
    };
    let Some(ProjectedCapabilityOriginV1::Operand(lhs)) =
        tensor_capability_read_v1::capability_known_origin_read_v1(state, &call.arguments()[1])
    else {
        return Err("an MFMA lhs without one dominating checked typed-load payload");
    };
    let Some(ProjectedCapabilityOriginV1::Operand(rhs)) =
        tensor_capability_read_v1::capability_known_origin_read_v1(state, &call.arguments()[2])
    else {
        return Err("an MFMA rhs without one dominating checked typed-load payload");
    };
    let Some(ProjectedCapabilityOriginV1::Accumulator(accumulator)) =
        tensor_capability_read_v1::capability_known_origin_read_v1(state, &call.arguments()[3])
    else {
        return Err("an MFMA accumulator without dominating zero or compatible prior MFMA");
    };
    if lhs.contract != lhs_contract || rhs.contract != rhs_contract {
        return Err("an MFMA call whose operand metadata does not match its exact load producers");
    }
    if accumulator.contract != accumulator_contract {
        return Err("an MFMA call whose accumulator metadata changed from its producer");
    }
    if lhs_contract.role != SemanticMfmaOperandRoleV1::A
        || rhs_contract.role != SemanticMfmaOperandRoleV1::B
    {
        return Err("an MFMA call with swapped or incompatible operand roles");
    }
    let homogeneous = rhs_contract.profile == lhs_contract.profile
        && accumulator_contract.profile == lhs_contract.profile;
    let fp4_by_fp8 = lhs_contract.profile == SemanticMfmaProfileV1::Fp4E2M1F32M16N16K128
        && rhs_contract.profile == SemanticMfmaProfileV1::Fp8E4M3F32M16N16K128
        && accumulator_contract.profile == SemanticMfmaProfileV1::Fp4E2M1F32M16N16K128;
    if !homogeneous && !fp4_by_fp8 {
        return Err("an MFMA call with incompatible instruction profiles");
    }
    if accumulator_contract.distribution != SemanticMfmaAccumulatorDistributionV1::RowMajor {
        return Err("an MFMA call with incompatible register distributions");
    }
    if lhs_contract.wave_width != 64
        || rhs_contract.wave_width != 64
        || accumulator_contract.wave_width != 64
        || lhs.lane_root != rhs.lane_root
        || lhs.lane_root != accumulator.lane_root
    {
        return Err("an MFMA call whose operands do not share one authenticated wave64 lane");
    }
    let mut contract = match (lhs_contract.profile, rhs_contract.profile) {
        (
            SemanticMfmaProfileV1::Fp4E2M1F32M16N16K128,
            SemanticMfmaProfileV1::Fp8E4M3F32M16N16K128,
        ) if lhs_contract.register_distribution
            == SemanticMfmaRegisterDistributionV1::Gfx950M16N16K128
            && rhs_contract.register_distribution
                == SemanticMfmaRegisterDistributionV1::Gfx950M16N16K128
            && lhs.storage_layout == SemanticMfmaStorageLayoutV1::RowMajor
            && rhs.storage_layout == SemanticMfmaStorageLayoutV1::RowMajor =>
        {
            fe2o3_kernel_ir::TensorLayoutContractV1::gfx950_scaled_mfma_fp4_e2m1_fp8_e4m3_f32_m16n16k128_wave64()
        }
        (
            SemanticMfmaProfileV1::Bf16F32M16N16K16,
            SemanticMfmaProfileV1::Bf16F32M16N16K16,
        )
            if lhs_contract.register_distribution
                == SemanticMfmaRegisterDistributionV1::Tile16x16
                && rhs_contract.register_distribution
                    == SemanticMfmaRegisterDistributionV1::Tile16x16
                && matches!(lhs.storage_layout, SemanticMfmaStorageLayoutV1::RowMajor | SemanticMfmaStorageLayoutV1::LdsXor4)
                && matches!(rhs.storage_layout, SemanticMfmaStorageLayoutV1::RowMajor | SemanticMfmaStorageLayoutV1::LdsXor4 | SemanticMfmaStorageLayoutV1::ColumnMajor) =>
        {
            fe2o3_kernel_ir::TensorLayoutContractV1::gfx942_mfma_bf16_f32_m16n16k16_wave64()
                .with_zero_filled_predicate_inputs()
        }
        (
            SemanticMfmaProfileV1::Fp8E4M3F32M16N16K128,
            SemanticMfmaProfileV1::Fp8E4M3F32M16N16K128,
        )
            if lhs_contract.register_distribution
                == SemanticMfmaRegisterDistributionV1::Gfx950M16N16K128
                && rhs_contract.register_distribution
                    == SemanticMfmaRegisterDistributionV1::Gfx950M16N16K128
                && lhs.storage_layout == SemanticMfmaStorageLayoutV1::RowMajor
                && rhs.storage_layout == SemanticMfmaStorageLayoutV1::RowMajor =>
        {
            fe2o3_kernel_ir::TensorLayoutContractV1::gfx950_scaled_mfma_fp8_e4m3_f32_m16n16k128_wave64()
        }
        (
            SemanticMfmaProfileV1::Fp4E2M1F32M16N16K128,
            SemanticMfmaProfileV1::Fp4E2M1F32M16N16K128,
        )
            if lhs_contract.register_distribution
                == SemanticMfmaRegisterDistributionV1::Gfx950M16N16K128
                && rhs_contract.register_distribution
                    == SemanticMfmaRegisterDistributionV1::Gfx950M16N16K128
                && lhs.storage_layout == SemanticMfmaStorageLayoutV1::RowMajor
                && rhs.storage_layout == SemanticMfmaStorageLayoutV1::RowMajor =>
        {
            fe2o3_kernel_ir::TensorLayoutContractV1::gfx950_scaled_mfma_fp4_e2m1_f32_m16n16k128_wave64()
        }
        _ => return Err("an MFMA call with incompatible register distributions"),
    };
    if lhs_contract.profile == SemanticMfmaProfileV1::Bf16F32M16N16K16 {
        if lhs.storage_layout == SemanticMfmaStorageLayoutV1::LdsXor4 {
            contract = contract.with_a_lds_xor4();
        }
        if rhs.storage_layout == SemanticMfmaStorageLayoutV1::LdsXor4 {
            contract = contract.with_b_lds_xor4();
        }
    }
    Ok(AuthenticatedTensorInstructionV1 {
        context_root,
        lhs,
        rhs,
        accumulator,
        contract,
    })
}

fn tensor_operand_root_v1(operand: ProjectedMfmaOperandV1) -> DigestV1 {
    tensor_capability_root_v1(
        match operand.contract.role {
            SemanticMfmaOperandRoleV1::A => 3,
            SemanticMfmaOperandRoleV1::B => 4,
        },
        &[
            operand.lane_root,
            operand.allocation.allocation_origin,
            operand.allocation.noalias_class,
            u64::from(operand.allocation.writable),
            match operand.storage_layout {
                SemanticMfmaStorageLayoutV1::RowMajor => 1,
                SemanticMfmaStorageLayoutV1::LdsXor4 => 2,
                SemanticMfmaStorageLayoutV1::ColumnMajor => 3,
            },
        ],
    )
}

fn tensor_site_binding_v1(
    authenticated: AuthenticatedTensorInstructionV1,
    result_root: u64,
    argument_count: u16,
) -> Option<ProductionCooperativeTensorBindingV1> {
    ProductionCooperativeTensorBindingV1::new(
        tensor_capability_root_v1(1, &[authenticated.context_root]),
        tensor_capability_root_v1(2, &[authenticated.accumulator.lane_root]),
        tensor_operand_root_v1(authenticated.lhs),
        tensor_operand_root_v1(authenticated.rhs),
        tensor_capability_root_v1(6, &[authenticated.accumulator.flow_root]),
        tensor_capability_root_v1(6, &[result_root]),
        argument_count,
    )
}

fn tensor_capability_root_v1(kind: u8, words: &[u64]) -> DigestV1 {
    let mut digest = Sha256::new();
    digest.update((TENSOR_CAPABILITY_ROOT_DOMAIN_V1.len() as u64).to_le_bytes());
    digest.update(TENSOR_CAPABILITY_ROOT_DOMAIN_V1);
    digest.update([kind]);
    digest.update((words.len() as u64).to_le_bytes());
    for word in words {
        digest.update(word.to_le_bytes());
    }
    DigestV1::from_untrusted_bytes(digest.finalize().into())
}

fn capability_known_origin_v1(
    state: &(impl tensor_capability_read_v1::CapabilityStateReadV1 + ?Sized),
    operand: &SemanticOperandV1,
) -> Option<ProjectedCapabilityOriginV1> {
    tensor_capability_read_v1::capability_known_origin_read_v1(state, operand)
}

fn merge_capability_states_v1(
    current: &mut ProjectedCapabilityStateV1,
    incoming: &ProjectedCapabilityStateV1,
) -> Result<bool, ProductionRankedProjectionErrorV1> {
    let additional = incoming
        .keys()
        .filter(|key| !current.contains_key(key))
        .count();
    checked_capability_stored_entries_v1(current.len(), additional)?;
    current.try_reserve(additional).map_err(|_| {
        ProductionRankedProjectionErrorV1::Unsupported(
            "capability state merge storage cannot be reserved",
        )
    })?;
    let mut changed = false;
    for (&key, existing) in current.iter_mut() {
        let merged = match incoming.get(&key).copied() {
            Some(candidate) => merge_capability_values_v1(*existing, candidate),
            None => ProjectedCapabilityValueV1::Invalid,
        };
        if *existing != merged {
            *existing = merged;
            changed = true;
        }
    }
    for (&key, &candidate) in incoming {
        if let std::collections::hash_map::Entry::Vacant(entry) = current.entry(key) {
            entry.insert(match candidate {
                ProjectedCapabilityValueV1::Known(_)
                | ProjectedCapabilityValueV1::ConstructedEnum(_)
                | ProjectedCapabilityValueV1::Invalid => ProjectedCapabilityValueV1::Invalid,
            });
            changed = true;
        }
    }
    Ok(changed)
}

fn merge_capability_values_v1(
    current: ProjectedCapabilityValueV1,
    incoming: ProjectedCapabilityValueV1,
) -> ProjectedCapabilityValueV1 {
    if current == incoming {
        return current;
    }
    let (
        ProjectedCapabilityValueV1::Known(ProjectedCapabilityOriginV1::Accumulator(current)),
        ProjectedCapabilityValueV1::Known(ProjectedCapabilityOriginV1::Accumulator(incoming)),
    ) = (current, incoming)
    else {
        return ProjectedCapabilityValueV1::Invalid;
    };
    if current.contract != incoming.contract
        || current.lane_root != incoming.lane_root
        || current.value_root != incoming.value_root
    {
        return ProjectedCapabilityValueV1::Invalid;
    }

    // A loop-carried accumulator joins its authenticated zero initializer with
    // the static MFMA site that feeds the backedge. Retain that site as the
    // layout producer while the stable value root continues to identify the
    // initialized semantic value. Two distinct non-initial producers remain an
    // ambiguous join and fail closed.
    let flow_root = if current.flow_root == current.value_root {
        incoming.flow_root
    } else if incoming.flow_root == incoming.value_root {
        current.flow_root
    } else {
        return ProjectedCapabilityValueV1::Invalid;
    };
    ProjectedCapabilityValueV1::Known(ProjectedCapabilityOriginV1::Accumulator(
        ProjectedMfmaAccumulatorV1 {
            flow_root,
            ..current
        },
    ))
}

fn try_clone_capability_state_v1(
    state: &ProjectedCapabilityStateV1,
) -> Result<ProjectedCapabilityStateV1, ProductionRankedProjectionErrorV1> {
    checked_capability_stored_entries_v1(0, state.len())?;
    let mut cloned = HashMap::new();
    cloned.try_reserve(state.len()).map_err(|_| {
        ProductionRankedProjectionErrorV1::Unsupported(
            "capability state clone storage cannot be reserved",
        )
    })?;
    cloned.extend(state.iter().map(|(&local, &value)| (local, value)));
    Ok(cloned)
}

fn checked_capability_stored_entries_v1(
    current: usize,
    additional: usize,
) -> Result<usize, ProductionRankedProjectionErrorV1> {
    let total =
        current
            .checked_add(additional)
            .ok_or(ProductionRankedProjectionErrorV1::Unsupported(
                "capability stored-state accounting overflow",
            ))?;
    if total > MAX_PROJECTED_CAPABILITY_STATE_ENTRIES_V1 {
        return Err(ProductionRankedProjectionErrorV1::Unsupported(
            "capability states exceed the charged storage limit",
        ));
    }
    Ok(total)
}

fn blocked_mapping_fits_launch_v1(
    linear_launch_upper_bound: Option<u64>,
    lanes_per_block: u64,
    elements_per_lane: u64,
) -> bool {
    if lanes_per_block == 0 || elements_per_lane == 0 {
        return false;
    }
    let Some(block_elements) = lanes_per_block.checked_mul(elements_per_lane) else {
        return false;
    };
    let Some(upper_bound) = linear_launch_upper_bound else {
        return false;
    };
    let Some(maximum_raw) = upper_bound.checked_sub(1) else {
        return true;
    };
    let block = maximum_raw / lanes_per_block;
    let lane = maximum_raw % lanes_per_block;
    block
        .checked_mul(block_elements)
        .and_then(|base| {
            (elements_per_lane - 1)
                .checked_mul(lanes_per_block)
                .and_then(|component| base.checked_add(component))
        })
        .and_then(|base| base.checked_add(lane))
        .is_some()
}

const NEUTRAL_WORKGROUP_ALLOCATION_IDENTITY_DOMAIN_V1: &[u8] =
    b"FE2O3/NEUTRAL-WORKGROUP-ALLOCATION/V1\0";
const NEUTRAL_WORKGROUP_SCAN_ALLOCATION_IDENTITY_DOMAIN_V1: &[u8] =
    b"FE2O3/NEUTRAL-WORKGROUP-SCAN-ALLOCATION/V1\0";

#[derive(Clone, Copy, Eq, PartialEq)]
enum NeutralWorkgroupRecipeKindV1 {
    Reduction,
    InclusiveScan,
    ExclusiveScan,
}

impl NeutralWorkgroupRecipeKindV1 {
    const fn from_scan(kind: SemanticWorkgroupScanKindV1) -> Self {
        match kind {
            SemanticWorkgroupScanKindV1::Inclusive => Self::InclusiveScan,
            SemanticWorkgroupScanKindV1::Exclusive => Self::ExclusiveScan,
        }
    }

    const fn identity_tag(self) -> u8 {
        match self {
            Self::Reduction => 0,
            Self::InclusiveScan => 1,
            Self::ExclusiveScan => 2,
        }
    }
}

#[derive(Clone, Copy)]
struct NeutralWorkgroupRecipeIdentityInputV1 {
    producer_block: usize,
    consumer_block: usize,
    dynamic_lds: SemanticTypeIdV1,
    element_storage: SemanticTypeIdV1,
    element: SemanticTypeIdV1,
    elements: u32,
    scalar_tag: u8,
    kind: NeutralWorkgroupRecipeKindV1,
}

fn neutral_workgroup_recipe_identity_v1(
    function: &SemanticFunctionDeclV1,
    input: NeutralWorkgroupRecipeIdentityInputV1,
) -> [u8; 32] {
    let mut hasher = Sha256::new();
    match input.kind {
        NeutralWorkgroupRecipeKindV1::Reduction => {
            hasher.update(NEUTRAL_WORKGROUP_ALLOCATION_IDENTITY_DOMAIN_V1);
            hasher.update(b"recipe-v1\0");
        }
        NeutralWorkgroupRecipeKindV1::InclusiveScan
        | NeutralWorkgroupRecipeKindV1::ExclusiveScan => {
            hasher.update(NEUTRAL_WORKGROUP_SCAN_ALLOCATION_IDENTITY_DOMAIN_V1);
            hasher.update(b"scan-recipe-v1\0");
            hasher.update([input.kind.identity_tag()]);
        }
    }
    hasher.update(function.identity().as_bytes());
    for value in [
        input.producer_block as u64,
        input.consumer_block as u64,
        u64::from(input.dynamic_lds.index()),
        u64::from(input.element_storage.index()),
        u64::from(input.element.index()),
        u64::from(input.elements),
        u64::from(input.scalar_tag),
    ] {
        hasher.update(value.to_le_bytes());
    }
    hasher.finalize().into()
}

fn is_exact_shared_reference_to_v1(
    types: &[SemanticTypeDeclV1],
    reference: SemanticTypeIdV1,
    pointee: SemanticTypeIdV1,
) -> bool {
    matches!(
        types.get(reference.index() as usize).map(SemanticTypeDeclV1::shape),
        Some(SemanticTypeShapeV1::Pointer(pointer))
            if pointer.pointee() == pointee
                && pointer.kind() == SemanticPointerKindV1::Reference
                && pointer.mutability() == SemanticMutabilityV1::Immutable
                && pointer.address_space() == 0
                && pointer.pointer_width_bits() == 64
                && pointer.metadata() == SemanticPointerMetadataV1::None
    )
}

fn project_generated_terminator_effects_v1(
    types: &[SemanticTypeDeclV1],
    function: &SemanticFunctionDeclV1,
    callables: &[SemanticCallableDeclV1],
) -> Result<Vec<Option<Vec<ProjectedGeneratedExecutableEffectV1>>>, ProductionRankedProjectionErrorV1>
{
    let mut projected = vec![None; function.blocks().len()];
    let mut dominance = SemanticAssertProofsV1::new(types, function)?;
    for (consumer_block, block) in function.blocks().iter().enumerate() {
        let SemanticTerminatorKindV1::Call(call) = block.terminator().kind() else {
            continue;
        };
        let Some(SemanticCallableDeclV1::CompilerIntrinsic { operation, .. }) =
            callables.get(call.callee().index() as usize)
        else {
            continue;
        };
        let (context, dynamic_lds, element_storage, element, kind) = match operation {
            SemanticCompilerIntrinsicOperationV1::NeutralWorkgroupReduceSum {
                context,
                dynamic_lds,
                element_storage,
                element,
            } => (
                context,
                dynamic_lds,
                element_storage,
                element,
                NeutralWorkgroupRecipeKindV1::Reduction,
            ),
            SemanticCompilerIntrinsicOperationV1::NeutralWorkgroupScanSum {
                context,
                dynamic_lds,
                element_storage,
                element,
                kind,
            } => (
                context,
                dynamic_lds,
                element_storage,
                element,
                NeutralWorkgroupRecipeKindV1::from_scan(*kind),
            ),
            _ => continue,
        };
        let [context_argument, dynamic_argument, value_argument] = call.arguments() else {
            return Err(ProductionRankedProjectionErrorV1::Unsupported(
                "target-neutral reduction argument arity changed",
            ));
        };
        // The semantic linearity pass has already authenticated exactly one
        // path-local transfer into this terminal consumer. Post-borrow-check
        // rustc MIR may encode that transfer as `Copy` for a non-Copy,
        // no-drop value when move semantics are no longer observable.
        let (SemanticOperandV1::Copy(dynamic_place) | SemanticOperandV1::Move(dynamic_place)) =
            dynamic_argument
        else {
            return Err(ProductionRankedProjectionErrorV1::Unsupported(
                "target-neutral reduction must transfer its affine DynamicLds authority",
            ));
        };
        if !is_exact_shared_reference_to_v1(types, context_argument.ty(), *context)
            || dynamic_place.ty() != *dynamic_lds
            || !dynamic_place.projections().is_empty()
            || value_argument.ty() != *element
            || call
                .destination()
                .is_none_or(|destination| destination.place().ty() != *element)
        {
            return Err(ProductionRankedProjectionErrorV1::Unsupported(
                "target-neutral reduction operand or result contract changed",
            ));
        }
        let dynamic_local = dynamic_place.local();
        let producers = function
            .blocks()
            .iter()
            .enumerate()
            .filter_map(|(producer_block, producer)| {
                let SemanticTerminatorKindV1::Call(producer_call) = producer.terminator().kind()
                else {
                    return None;
                };
                let destination = producer_call.destination()?.place();
                if !destination.projections().is_empty() || destination.local() != dynamic_local {
                    return None;
                }
                let SemanticCallableDeclV1::CompilerIntrinsic { operation, .. } =
                    callables.get(producer_call.callee().index() as usize)?
                else {
                    return None;
                };
                Some((producer_block, producer_call, operation))
            })
            .collect::<Vec<_>>();
        let [(producer_block, producer_call, producer_operation)] = producers.as_slice() else {
            return Err(ProductionRankedProjectionErrorV1::Incomplete(
                "target-neutral reduction lacks one exact DynamicLds producer",
            ));
        };
        let SemanticCompilerIntrinsicOperationV1::DynamicLdsExactCurrent {
            dynamic_lds: producer_dynamic_lds,
            element_storage: producer_element_storage,
            elements,
            ..
        } = producer_operation
        else {
            return Err(ProductionRankedProjectionErrorV1::Unsupported(
                "target-neutral reduction DynamicLds local has a substituted producer",
            ));
        };
        let elements = u32::try_from(*elements).map_err(|_| {
            ProductionRankedProjectionErrorV1::Unsupported(
                "target-neutral reduction extent exceeds the ranked domain",
            )
        })?;
        let scalar_tag = match types
            .get(element.index() as usize)
            .map(SemanticTypeDeclV1::shape)
        {
            Some(SemanticTypeShapeV1::Scalar(SemanticScalarTypeV1::Integer {
                signed: false,
                bits: 32,
            })) => 1,
            Some(SemanticTypeShapeV1::Scalar(SemanticScalarTypeV1::Integer {
                signed: true,
                bits: 32,
            })) => 2,
            Some(SemanticTypeShapeV1::Scalar(SemanticScalarTypeV1::Float { bits: 32 })) => 3,
            _ => 0,
        };
        let extent_is_supported = elements != 0
            && elements <= 256
            && (kind != NeutralWorkgroupRecipeKindV1::Reduction || elements.is_power_of_two());
        if *producer_dynamic_lds != *dynamic_lds
            || *producer_element_storage != *element_storage
            || !matches!(
                producer_call.arguments(),
                [SemanticOperandV1::Copy(place) | SemanticOperandV1::Move(place)]
                    if place.projections().is_empty()
            )
            || *producer_block == consumer_block
            || !dominance.block_dominates(*producer_block, consumer_block)?
            || !extent_is_supported
            || type_width(types, *element_storage)? != 32
            || type_width(types, *element)? != 32
            || scalar_tag == 0
        {
            return Err(ProductionRankedProjectionErrorV1::Unsupported(
                "target-neutral reduction producer, scalar, extent, or dominance contract changed",
            ));
        }
        let recipe_identity = neutral_workgroup_recipe_identity_v1(
            function,
            NeutralWorkgroupRecipeIdentityInputV1 {
                producer_block: *producer_block,
                consumer_block,
                dynamic_lds: *dynamic_lds,
                element_storage: *element_storage,
                element: *element,
                elements,
                scalar_tag,
                kind,
            },
        );
        let (allocation_origin, noalias_class) =
            dialect_kernel::neutral_workgroup_allocation_contract_v1(recipe_identity);
        let parent = block.terminator().source();
        let mut effects = Vec::new();
        let mut push = |operation| {
            let semantic_effect_ordinal = u32::try_from(effects.len()).map_err(|_| {
                ProductionRankedProjectionErrorV1::Unsupported(
                    "generated terminator effect ordinal exceeds u32",
                )
            })?;
            if effects.len() == MAX_PROJECTED_OPERATIONS_V1 {
                return Err(ProductionRankedProjectionErrorV1::Unsupported(
                    "generated terminator effects exceed the ranked operation limit",
                ));
            }
            effects.try_reserve(1).map_err(|_| {
                ProductionRankedProjectionErrorV1::Unsupported(
                    "generated terminator effect storage cannot be reserved",
                )
            })?;
            effects.push(ProjectedGeneratedExecutableEffectV1 {
                operation,
                semantic_effect_ordinal,
                origin: ProjectedExecutableEffectOriginV1::GeneratedFromSemanticTerminator {
                    parent,
                },
                recipe_identity,
            });
            Ok(())
        };
        let memory = |kind| ProductionRankedOperationV1::AllocationEffect {
            kind,
            memory_space: MemorySpaceAttr::Workgroup,
            allocation_origin,
            noalias_class,
        };
        let barrier = || ProductionRankedOperationV1::Barrier {
            execution_scope: HierarchyAttr::Workgroup,
            memory_scope: MemoryScopeAttr::Workgroup,
            address_space: AddressSpaceAttr::Workgroup,
            order: MemoryOrderAttr::AcquireRelease,
        };
        push(memory(AccessKindAttr::Write))?;
        push(barrier())?;
        let mut offset = match kind {
            NeutralWorkgroupRecipeKindV1::Reduction => elements >> 1,
            NeutralWorkgroupRecipeKindV1::InclusiveScan
            | NeutralWorkgroupRecipeKindV1::ExclusiveScan => 1,
        };
        while match kind {
            NeutralWorkgroupRecipeKindV1::Reduction => offset != 0,
            NeutralWorkgroupRecipeKindV1::InclusiveScan
            | NeutralWorkgroupRecipeKindV1::ExclusiveScan => offset < elements,
        } {
            for access in [AccessKindAttr::Read, AccessKindAttr::Read] {
                push(memory(access))?;
            }
            push(barrier())?;
            push(memory(AccessKindAttr::Write))?;
            push(barrier())?;
            match kind {
                NeutralWorkgroupRecipeKindV1::Reduction => offset >>= 1,
                NeutralWorkgroupRecipeKindV1::InclusiveScan
                | NeutralWorkgroupRecipeKindV1::ExclusiveScan => offset <<= 1,
            }
        }
        push(memory(AccessKindAttr::Read))?;
        push(barrier())?;
        projected[consumer_block] = Some(effects);
    }
    Ok(projected)
}

#[cfg(test)]
include!("production_ranked_projection_v1/multi_entry_legacy_wrappers_v1_tests.rs");

#[allow(clippy::too_many_arguments)]
fn project_intrinsic_contracts_with_multi_entry_v1(
    callables: &[SemanticCallableDeclV1],
    callable_effects: &DefinedCallableEmptyEffectSummariesV1,
    types: &[SemanticTypeDeclV1],
    function: &SemanticFunctionDeclV1,
    linear_launch_upper_bound: Option<u64>,
    constants: &[Option<u64>],
    operations: &mut Vec<ProductionRankedOperationV1>,
    next_value: &mut u32,
    ranked_ir: &mut String,
    mut multi: Option<&mut multi_entry_induction_v1::Context<'_, '_>>,
) -> Result<IntrinsicProjectionV1, ProductionRankedProjectionErrorV1> {
    reject_retired_production_intrinsics_v1(callables)?;
    let local_count = function.locals().len();
    let mut index_values = vec![None; local_count];
    let mut grid_leaders = vec![None; local_count];
    let mut option_predicates = vec![None; local_count];
    let mut edges_by_source = vec![Vec::new(); local_count];
    let mut enum_payload_stores = Vec::new();
    let mut enum_payload_loads = Vec::new();
    let option_producers = semantic_option_producers_v1(function, callables)
        .map_err(|error| ProductionRankedProjectionErrorV1::Unsupported(error.detail()))?;
    let option_dominance = SemanticOptionDominanceV1::analyze(function, &option_producers)
        .map_err(|error| ProductionRankedProjectionErrorV1::Unsupported(error.detail()))?;
    let enum_payload_dominance = SemanticEnumPayloadDominanceV1::analyze(function, types)
        .map_err(|error| ProductionRankedProjectionErrorV1::Unsupported(error.detail()))?;
    let scalar_inventory = assertion_definition_inventory(function)?;
    let LocalProvenanceV1 {
        stable_argument_origins,
        allocation_origins,
        allocation_provenance,
    } = local_provenance_with_scalar_inventory_v1(
        callables,
        types,
        function,
        &scalar_inventory.counts,
        &scalar_inventory.address_escaped,
    )?;
    let local_allocations = local_allocation_contracts(types, function, &allocation_origins)?;
    let capability_effects = project_authenticated_capabilities_v1(
        callables,
        function,
        &enum_payload_dominance,
        &local_allocations,
        constants,
    )?;
    let capability_read_effects =
        bind_capability_read_effects_to_call_blocks_v1(function, &capability_effects.global_reads)?;
    let tensor_layouts = capability_effects.layouts;
    let transpose_workgroup_effects = capability_effects.transpose_workgroups;
    let read_view_sources = capability_effects.read_views;
    let mut edge_count = 0_usize;
    let mut borrowed_locals = Vec::new();
    let mut runtime_index_arguments = vec![None; local_count];
    let mut runtime_slice_extent_arguments = vec![None; local_count];
    let mut next_runtime_argument = 1_usize;
    let read_view_effects = project_strided_read_effects_v1(
        types,
        function,
        &read_view_sources,
        &stable_argument_origins,
        &mut runtime_index_arguments,
        &mut next_runtime_argument,
        operations,
        next_value,
    )?;
    // Workgroup geometry and the runtime grid domain are independent. The
    // source launch contract authenticates the former; the latter remains
    // dynamic until host launch evidence is joined.
    let launch_extent = 0;
    let local_definitions = scalar_inventory.counts.clone();

    root_initial_capability_graph_v1::populate_initial_graph_v1(
        callables,
        function,
        linear_launch_upper_bound,
        &local_definitions,
        &option_dominance,
        &enum_payload_dominance,
        &mut edges_by_source,
        &mut edge_count,
        &mut enum_payload_stores,
        &mut enum_payload_loads,
        &mut borrowed_locals,
        &mut bf16_nominal_preparation_resources_v1::PreparationResourcesV1::unmetered(),
    )?;

    let mut index_worklist = VecDeque::new();
    let mut grid_worklist = VecDeque::new();
    root_invocation_index_preparation_v1::seed_invocation_values_legacy_v1(
        callables,
        function,
        &local_definitions,
        &scalar_inventory.address_escaped,
        &option_dominance,
        &mut index_values,
        &mut grid_leaders,
        &mut option_predicates,
        &mut index_worklist,
        &mut grid_worklist,
        launch_extent,
        operations,
        next_value,
        ranked_ir,
    )?;

    // rustc may erase the move that binds an unforgeable zero-sized payload
    // from `Option::Some`. Recover that edge only when one exact authenticated
    // producer controls the borrow's block and its payload type matches.
    for (borrowed_local, use_block) in borrowed_locals {
        if grid_leaders[borrowed_local].is_some() {
            continue;
        }
        let borrowed_type = function.locals()[borrowed_local].ty();
        let use_block_id = SemanticBlockIdV1::from_index(use_block as u32);
        let mut producer = None;
        for (candidate_local, candidate) in grid_leaders.iter().copied().enumerate() {
            let Some(candidate) = candidate else {
                continue;
            };
            if candidate.grid_leader != borrowed_type
                || !capability_availability_allows(
                    &option_dominance,
                    &enum_payload_dominance,
                    candidate.availability,
                    use_block_id,
                )
            {
                continue;
            }
            if producer.replace(candidate_local).is_some() {
                return Err(ProductionRankedProjectionErrorV1::Unsupported(
                    "a borrowed zero-sized capability has multiple active Option producers",
                ));
            }
        }
        if let Some(producer) = producer {
            push_capability_edge(
                &mut edges_by_source,
                &mut edge_count,
                producer,
                CapabilityEdgeV1 {
                    destination: borrowed_local,
                    use_block,
                    kind: CapabilityEdgeKindV1::AuthenticatedOptionPayload,
                },
            )?;
        }
    }

    let mut processed_edges = 0_usize;
    root_invocation_index_preparation_v1::propagate_index_values_legacy_v1(
        &local_definitions,
        &scalar_inventory.address_escaped,
        &option_dominance,
        &enum_payload_dominance,
        &edges_by_source,
        &mut index_values,
        &grid_leaders,
        &mut option_predicates,
        &mut index_worklist,
        &mut processed_edges,
        operations,
        next_value,
        ranked_ir,
    )?;

    while let Some(source) = grid_worklist.pop_front() {
        let input = grid_leaders[source].ok_or(ProductionRankedProjectionErrorV1::Unsupported(
            "the capability worklist lost grid-leader authority",
        ))?;
        for edge in &edges_by_source[source] {
            if !matches!(
                edge.kind,
                CapabilityEdgeKindV1::Alias
                    | CapabilityEdgeKindV1::AuthenticatedOptionPayload
                    | CapabilityEdgeKindV1::AuthenticatedEnumPayload { .. }
            ) {
                continue;
            }
            let authorization_block = match edge.kind {
                CapabilityEdgeKindV1::AuthenticatedEnumPayload {
                    construction_block, ..
                } => construction_block,
                _ => edge.use_block,
            };
            if !capability_availability_allows(
                &option_dominance,
                &enum_payload_dominance,
                input.availability,
                SemanticBlockIdV1::from_index(authorization_block as u32),
            ) {
                return Err(ProductionRankedProjectionErrorV1::Unsupported(
                    "grid-leader authority is aliased outside its authenticated Some edge",
                ));
            }
            processed_edges = processed_edges.checked_add(1).ok_or(
                ProductionRankedProjectionErrorV1::Unsupported(
                    "capability work accounting overflowed",
                ),
            )?;
            let destination = edge.destination;
            if destination >= grid_leaders.len() || index_values[destination].is_some() {
                return Err(ProductionRankedProjectionErrorV1::Unsupported(
                    "a grid-leader alias escaped the semantic local table or changed capability kind",
                ));
            }
            let projected = match edge.kind {
                CapabilityEdgeKindV1::AuthenticatedEnumPayload { availability, .. } => {
                    ProjectedGridLeaderV1 {
                        availability: CapabilityAvailabilityV1::EnumPayload(availability),
                        ..input
                    }
                }
                _ => input,
            };
            match grid_leaders[destination] {
                None => {
                    grid_leaders[destination] = Some(projected);
                    grid_worklist.push_back(destination);
                }
                Some(existing) if existing == projected => {}
                Some(_) => {
                    return Err(ProductionRankedProjectionErrorV1::Unsupported(
                        "multiple grid-leader capabilities reach one semantic local",
                    ));
                }
            }
        }
    }
    if processed_edges > edge_count {
        return Err(ProductionRankedProjectionErrorV1::Unsupported(
            "capability worklist exceeded its charged def-use edges",
        ));
    }

    let ordinary_index_values = project_disjoint_block_component_indices_v1(
        callables,
        function,
        linear_launch_upper_bound,
        constants,
        &index_values,
        &local_definitions,
        &scalar_inventory.address_escaped,
        &enum_payload_loads,
        &option_dominance,
        &enum_payload_dominance,
        &mut option_predicates,
        operations,
        next_value,
        ranked_ir,
    )?;

    let mut views_by_origin: Vec<Option<ProjectedViewV1>> = vec![None; function.locals().len()];
    let mut guarded_accesses = Vec::new();
    let mut direct_read_effects = vec![None; function.blocks().len()];
    let mut direct_write_effects = vec![None; function.blocks().len()];
    for (block_index, block) in function.blocks().iter().enumerate() {
        let SemanticTerminatorKindV1::Call(call) = block.terminator().kind() else {
            continue;
        };
        let Some(SemanticCallableDeclV1::CompilerIntrinsic { operation, .. }) =
            callables.get(call.callee().index() as usize)
        else {
            continue;
        };
        let write_only_effect = matches!(
            operation,
            SemanticCompilerIntrinsicOperationV1::WriteOnlyDisjointSliceWrite { .. }
        );
        if let SemanticCompilerIntrinsicOperationV1::MemoryVolatileLoad { element } = operation {
            if call.arguments().len() != 2 || call.destination().is_none() {
                return Err(ProductionRankedProjectionErrorV1::Unsupported(
                    "volatile load argument or result arity changed",
                ));
            }
            let receiver = call
                .arguments()
                .first()
                .and_then(simple_operand_local)
                .ok_or(ProductionRankedProjectionErrorV1::Incomplete(
                    "a volatile load receiver without one exact slice local",
                ))?
                .index() as usize;
            let allocation_contract = local_allocations.get(receiver).copied().flatten().ok_or(
                ProductionRankedProjectionErrorV1::Incomplete(
                    "a volatile load receiver without one authenticated kernel-argument origin",
                ),
            )?;
            if !volatile_load_frozen_shared_scalar_source_v1(
                types,
                function,
                &stable_argument_origins,
                receiver,
                *element,
            ) {
                return Err(ProductionRankedProjectionErrorV1::Unsupported(
                    "a volatile load is not rooted in a frozen shared Rust allocation",
                ));
            }
            let extent = project_runtime_slice_extent_argument_v1(
                receiver,
                &stable_argument_origins,
                &mut runtime_slice_extent_arguments,
                &mut next_runtime_argument,
            )?;
            let index = project_runtime_index_operand_v1(
                call.arguments().get(1),
                constants,
                &stable_argument_origins,
                &mut runtime_index_arguments,
                &mut next_runtime_argument,
                operations,
                next_value,
            )?;
            let origin_index = allocation_contract.allocation_origin as usize;
            let element_width = type_width(types, *element)?;
            let view = match views_by_origin
                .get(origin_index)
                .and_then(|view| view.as_ref())
            {
                Some(view)
                    if view.element_width == element_width
                        && !view.writable
                        && view.shape == [DYNAMIC_EXTENT]
                        && view.dynamic_extents == [extent]
                        && view.memory_space == MemorySpaceAttr::Global
                        && view.allocation_origin == allocation_contract.allocation_origin
                        && view.noalias_class == allocation_contract.noalias_class =>
                {
                    view.result
                }
                Some(_) => {
                    return Err(ProductionRankedProjectionErrorV1::Unsupported(
                        "one volatile allocation origin was projected with conflicting type or extent",
                    ));
                }
                None => {
                    reserve_operation(operations)?;
                    let view = next_value_id(next_value)?;
                    operations.push(ProductionRankedOperationV1::ViewInSpace {
                        result: view,
                        element_width,
                        writable: false,
                        shape: vec![DYNAMIC_EXTENT],
                        dynamic_extents: vec![extent],
                        memory_space: MemorySpaceAttr::Global,
                        allocation_origin: allocation_contract.allocation_origin,
                        noalias_class: allocation_contract.noalias_class,
                    });
                    push_ranked_ir(
                        ranked_ir,
                        &format!(
                            "  %{} = kernel.ranked_view <{}, false, [dynamic], Global>({})\n",
                            view.get(),
                            element_width,
                            ranked_value_text_v1(extent),
                        ),
                    )?;
                    let slot = views_by_origin.get_mut(origin_index).ok_or(
                        ProductionRankedProjectionErrorV1::Unsupported(
                            "a volatile allocation origin outside the semantic local table",
                        ),
                    )?;
                    *slot = Some(ProjectedViewV1 {
                        result: view,
                        element_width,
                        writable: false,
                        shape: vec![DYNAMIC_EXTENT],
                        dynamic_extents: vec![extent],
                        memory_space: MemorySpaceAttr::Global,
                        allocation_origin: allocation_contract.allocation_origin,
                        noalias_class: allocation_contract.noalias_class,
                    });
                    view
                }
            };
            let access = GuardedRankedAccessV1 {
                view,
                indices: vec![index],
                checked_success: None,
                comparisons: vec![(index, extent)],
                access: AccessKindAttr::Read,
                memory_space: MemorySpaceAttr::Global,
                source: block.terminator().source(),
                output_extent: None,
                semantic_site: None,
            };
            let slot = direct_read_effects.get_mut(block_index).ok_or(
                ProductionRankedProjectionErrorV1::Unsupported(
                    "a volatile read block outside the semantic CFG",
                ),
            )?;
            if slot.replace(access).is_some() {
                return Err(ProductionRankedProjectionErrorV1::Unsupported(
                    "multiple volatile reads occupy one semantic block",
                ));
            }
            continue;
        }
        let (element, index, precondition, checked_success, direct_write) = match operation {
            SemanticCompilerIntrinsicOperationV1::DisjointSliceGetMut { element, .. } => {
                let projected = root_guarded_access_preparation_v1::identity_operand_v1(
                    call,
                    &index_values,
                    &option_dominance,
                    &enum_payload_dominance,
                    block_index,
                )?;
                (
                    *element,
                    projected.value,
                    projected.precondition,
                    None,
                    false,
                )
            }
            SemanticCompilerIntrinsicOperationV1::DisjointSliceGetDisjointMut {
                element,
                index_space,
                ..
            } => {
                let projected = projected_disjoint_operand_v1(
                    call,
                    1,
                    &index_values,
                    &option_dominance,
                    &enum_payload_dominance,
                    block_index,
                )?;
                if projected.mapping != *index_space {
                    return Err(ProductionRankedProjectionErrorV1::Unsupported(
                        "disjoint accessor mapping identity changed",
                    ));
                }
                (
                    *element,
                    projected.value,
                    projected.precondition,
                    None,
                    false,
                )
            }
            SemanticCompilerIntrinsicOperationV1::WriteOnlyDisjointSliceWrite {
                element,
                index_space,
                kind: SemanticWriteOnlyDisjointWriteKindV1::Thread { disjoint },
                ..
            } => {
                let projected = projected_disjoint_operand_v1(
                    call,
                    1,
                    &index_values,
                    &option_dominance,
                    &enum_payload_dominance,
                    block_index,
                )?;
                if projected.mapping != *index_space {
                    return Err(ProductionRankedProjectionErrorV1::Unsupported(
                        "write-only direct mapping identity changed",
                    ));
                }
                if *disjoint && projected.mapping == SemanticDisjointIndexSpaceV1::GridExclusive {
                    return Err(ProductionRankedProjectionErrorV1::Unsupported(
                        "write-only direct disjoint mapping is grid-exclusive",
                    ));
                }
                (
                    *element,
                    projected.value,
                    projected.precondition,
                    None,
                    write_only_effect,
                )
            }
            SemanticCompilerIntrinsicOperationV1::DisjointSliceGetMutExclusive {
                element,
                grid_leader,
                ..
            }
            | SemanticCompilerIntrinsicOperationV1::WriteOnlyDisjointSliceWrite {
                element,
                witness: grid_leader,
                kind: SemanticWriteOnlyDisjointWriteKindV1::GridExclusive,
                ..
            } => {
                let leader_local = call
                    .arguments()
                    .get(1)
                    .and_then(simple_operand_local)
                    .ok_or(ProductionRankedProjectionErrorV1::Incomplete(
                        "an exclusive access without one exact grid-leader local",
                    ))?
                    .index() as usize;
                let leader = grid_leaders.get(leader_local).copied().flatten().ok_or(
                    ProductionRankedProjectionErrorV1::Incomplete(
                        "an exclusive access without authenticated grid-leader authority",
                    ),
                )?;
                if leader.grid_leader != *grid_leader {
                    return Err(ProductionRankedProjectionErrorV1::Unsupported(
                        "grid-leader capability type identity changed",
                    ));
                }
                if !capability_availability_allows(
                    &option_dominance,
                    &enum_payload_dominance,
                    leader.availability,
                    SemanticBlockIdV1::from_index(block_index as u32),
                ) {
                    return Err(ProductionRankedProjectionErrorV1::Unsupported(
                        "grid-leader authority is used outside its authenticated Some edge",
                    ));
                }
                let index_operand = call.arguments().get(2).ok_or(
                    ProductionRankedProjectionErrorV1::Unsupported(
                        "a grid-exclusive access has no exact index operand",
                    ),
                )?;
                if unsigned_index_bits_v1(types, index_operand.ty()) != Some(64) {
                    return Err(ProductionRankedProjectionErrorV1::Unsupported(
                        "a grid-exclusive index is not an exact unsigned 64-bit device index",
                    ));
                }
                let constant_index_value = constant_operand_value(index_operand, constants);
                // The opaque ranked value overapproximates every loop execution.
                // Each access uses that same value in its dominating bounds guard;
                // race freedom is discharged separately from the singleton
                // invocation domain, not from index injectivity.
                let projected_index = project_runtime_index_operand_v1(
                    Some(index_operand),
                    constants,
                    &stable_argument_origins,
                    &mut runtime_index_arguments,
                    &mut next_runtime_argument,
                    operations,
                    next_value,
                )?;
                if let Some(value) = constant_index_value {
                    let ProductionRankedValueV1::Local(result) = projected_index else {
                        return Err(ProductionRankedProjectionErrorV1::Unsupported(
                            "a constant grid-exclusive index did not remain a ranked local",
                        ));
                    };
                    push_ranked_ir(
                        ranked_ir,
                        &format!("  %{} = kernel.index_constant {}\n", result.get(), value),
                    )?;
                }
                reserve_operation(operations)?;
                let index = next_value_id(next_value)?;
                operations.push(ProductionRankedOperationV1::IndexBinary {
                    result: index,
                    kind: IndexBinaryKindAttr::Add,
                    lhs: leader.precondition.0,
                    rhs: projected_index,
                });
                push_ranked_ir(
                    ranked_ir,
                    &format!(
                        "  %{} = kernel.index_binary Add {}, {}\n",
                        index.get(),
                        ranked_value_text_v1(leader.precondition.0),
                        ranked_value_text_v1(projected_index),
                    ),
                )?;
                (
                    *element,
                    ProductionRankedValueV1::Local(index),
                    Some(leader.precondition),
                    None,
                    write_only_effect,
                )
            }
            SemanticCompilerIntrinsicOperationV1::DisjointSliceGetBlockMut {
                element,
                index_space,
                lanes_per_block,
                elements_per_lane,
                ..
            }
            | SemanticCompilerIntrinsicOperationV1::WriteOnlyDisjointSliceWrite {
                element,
                index_space,
                kind:
                    SemanticWriteOnlyDisjointWriteKindV1::Block {
                        lanes_per_block,
                        elements_per_lane,
                    },
                ..
            } => {
                let projected = projected_disjoint_operand_v1(
                    call,
                    1,
                    &index_values,
                    &option_dominance,
                    &enum_payload_dominance,
                    block_index,
                )?;
                let expected = SemanticDisjointIndexSpaceV1::BlockedIndex1d {
                    lanes_per_block: *lanes_per_block,
                    elements_per_lane: *elements_per_lane,
                };
                if projected.mapping != expected || *index_space != expected {
                    return Err(ProductionRankedProjectionErrorV1::Unsupported(
                        "blocked accessor mapping identity changed",
                    ));
                }
                if *lanes_per_block == 0 || *elements_per_lane == 0 {
                    return Err(ProductionRankedProjectionErrorV1::Unsupported(
                        "a malformed blocked mapping reached ranked projection",
                    ));
                }
                if !blocked_mapping_fits_launch_v1(
                    linear_launch_upper_bound,
                    *lanes_per_block,
                    *elements_per_lane,
                ) {
                    return Err(ProductionRankedProjectionErrorV1::Incomplete(
                        "a multi-lane blocked accessor requires an authenticated finite rank-1 launch extent whose full blocked index range fits u64",
                    ));
                }
                let component = call
                    .arguments()
                    .get(2)
                    .and_then(|operand| constant_operand_value(operand, constants))
                    .ok_or(ProductionRankedProjectionErrorV1::Incomplete(
                        "a dynamic blocked component before ranked-value projection is available",
                    ))?;
                if component >= *elements_per_lane {
                    return Err(ProductionRankedProjectionErrorV1::Unsupported(
                        "a blocked component is outside the authenticated elements-per-lane bound",
                    ));
                }
                let (base, offset) = if *lanes_per_block == 1 {
                    reserve_operation(operations)?;
                    let elements = next_value_id(next_value)?;
                    operations.push(ProductionRankedOperationV1::IndexConstant {
                        result: elements,
                        value: *elements_per_lane,
                    });
                    reserve_operation(operations)?;
                    let block_base = next_value_id(next_value)?;
                    operations.push(ProductionRankedOperationV1::IndexBinary {
                        result: block_base,
                        kind: IndexBinaryKindAttr::Multiply,
                        lhs: projected.value,
                        rhs: ProductionRankedValueV1::Local(elements),
                    });
                    push_ranked_ir(
                        ranked_ir,
                        &format!(
                            "  %{} = kernel.index_constant {}\n  %{} = kernel.index_binary Multiply {}, %{}\n",
                            elements.get(),
                            elements_per_lane,
                            block_base.get(),
                            ranked_value_text_v1(projected.value),
                            elements.get(),
                        ),
                    )?;
                    (ProductionRankedValueV1::Local(block_base), component)
                } else {
                    let block_elements = lanes_per_block.checked_mul(*elements_per_lane).ok_or(
                        ProductionRankedProjectionErrorV1::Unsupported(
                            "blocked dimensions overflow u64",
                        ),
                    )?;
                    let component_offset = component.checked_mul(*lanes_per_block).ok_or(
                        ProductionRankedProjectionErrorV1::Unsupported(
                            "a blocked component offset overflows u64",
                        ),
                    )?;
                    reserve_operation(operations)?;
                    let lanes = next_value_id(next_value)?;
                    operations.push(ProductionRankedOperationV1::IndexConstant {
                        result: lanes,
                        value: *lanes_per_block,
                    });
                    reserve_operation(operations)?;
                    let elements = next_value_id(next_value)?;
                    operations.push(ProductionRankedOperationV1::IndexConstant {
                        result: elements,
                        value: block_elements,
                    });
                    reserve_operation(operations)?;
                    let block = next_value_id(next_value)?;
                    operations.push(ProductionRankedOperationV1::IndexBinary {
                        result: block,
                        kind: IndexBinaryKindAttr::Divide,
                        lhs: projected.value,
                        rhs: ProductionRankedValueV1::Local(lanes),
                    });
                    reserve_operation(operations)?;
                    let lane = next_value_id(next_value)?;
                    operations.push(ProductionRankedOperationV1::IndexBinary {
                        result: lane,
                        kind: IndexBinaryKindAttr::Remainder,
                        lhs: projected.value,
                        rhs: ProductionRankedValueV1::Local(lanes),
                    });
                    reserve_operation(operations)?;
                    let block_base = next_value_id(next_value)?;
                    operations.push(ProductionRankedOperationV1::IndexBinary {
                        result: block_base,
                        kind: IndexBinaryKindAttr::Multiply,
                        lhs: ProductionRankedValueV1::Local(block),
                        rhs: ProductionRankedValueV1::Local(elements),
                    });
                    reserve_operation(operations)?;
                    let lane_base = next_value_id(next_value)?;
                    operations.push(ProductionRankedOperationV1::IndexBinary {
                        result: lane_base,
                        kind: IndexBinaryKindAttr::Add,
                        lhs: ProductionRankedValueV1::Local(block_base),
                        rhs: ProductionRankedValueV1::Local(lane),
                    });
                    push_ranked_ir(
                        ranked_ir,
                        &format!(
                            "  %{} = kernel.index_constant {}\n  %{} = kernel.index_constant {}\n  %{} = kernel.index_binary Divide {}, %{}\n  %{} = kernel.index_binary Remainder {}, %{}\n  %{} = kernel.index_binary Multiply %{}, %{}\n  %{} = kernel.index_binary Add %{}, %{}\n",
                            lanes.get(),
                            lanes_per_block,
                            elements.get(),
                            block_elements,
                            block.get(),
                            ranked_value_text_v1(projected.value),
                            lanes.get(),
                            lane.get(),
                            ranked_value_text_v1(projected.value),
                            lanes.get(),
                            block_base.get(),
                            block.get(),
                            elements.get(),
                            lane_base.get(),
                            block_base.get(),
                            lane.get(),
                        ),
                    )?;
                    (ProductionRankedValueV1::Local(lane_base), component_offset)
                };
                reserve_operation(operations)?;
                let component_value = next_value_id(next_value)?;
                operations.push(ProductionRankedOperationV1::IndexConstant {
                    result: component_value,
                    value: offset,
                });
                reserve_operation(operations)?;
                let index = next_value_id(next_value)?;
                operations.push(ProductionRankedOperationV1::IndexBinary {
                    result: index,
                    kind: IndexBinaryKindAttr::Add,
                    lhs: base,
                    rhs: ProductionRankedValueV1::Local(component_value),
                });
                push_ranked_ir(
                    ranked_ir,
                    &format!(
                        "  %{} = kernel.index_constant {}\n  %{} = kernel.index_binary Add {}, %{}\n",
                        component_value.get(),
                        offset,
                        index.get(),
                        ranked_value_text_v1(base),
                        component_value.get(),
                    ),
                )?;
                (
                    *element,
                    ProductionRankedValueV1::Local(index),
                    projected.precondition,
                    None,
                    write_only_effect,
                )
            }
            SemanticCompilerIntrinsicOperationV1::DisjointSliceGetTiled2dMut {
                element,
                index_space,
                lanes_per_tile,
                tile_rows,
                tile_columns,
                elements_per_lane,
                ..
            }
            | SemanticCompilerIntrinsicOperationV1::WriteOnlyDisjointSliceWrite {
                element,
                index_space,
                kind:
                    SemanticWriteOnlyDisjointWriteKindV1::Tiled2d {
                        lanes_per_tile,
                        tile_rows,
                        tile_columns,
                        elements_per_lane,
                    },
                ..
            } => {
                let projected = projected_disjoint_operand_v1(
                    call,
                    1,
                    &index_values,
                    &option_dominance,
                    &enum_payload_dominance,
                    block_index,
                )?;
                let expected = SemanticDisjointIndexSpaceV1::Tiled2dIndex1d {
                    lanes_per_tile: *lanes_per_tile,
                    tile_rows: *tile_rows,
                    tile_columns: *tile_columns,
                    elements_per_lane: *elements_per_lane,
                };
                if projected.mapping != expected
                    || *index_space != expected
                    || !tiled_2d_geometry_valid_v1(
                        *lanes_per_tile,
                        *tile_rows,
                        *tile_columns,
                        *elements_per_lane,
                    )
                {
                    return Err(ProductionRankedProjectionErrorV1::Unsupported(
                        "tiled-2d accessor mapping identity changed",
                    ));
                }
                let component = project_runtime_index_operand_v1(
                    call.arguments().get(2),
                    constants,
                    &stable_argument_origins,
                    &mut runtime_index_arguments,
                    &mut next_runtime_argument,
                    operations,
                    next_value,
                )?;
                let rows = project_runtime_index_operand_v1(
                    call.arguments().get(3),
                    constants,
                    &stable_argument_origins,
                    &mut runtime_index_arguments,
                    &mut next_runtime_argument,
                    operations,
                    next_value,
                )?;
                let columns = project_runtime_index_operand_v1(
                    call.arguments().get(4),
                    constants,
                    &stable_argument_origins,
                    &mut runtime_index_arguments,
                    &mut next_runtime_argument,
                    operations,
                    next_value,
                )?;
                let row_stride = project_runtime_index_operand_v1(
                    call.arguments().get(5),
                    constants,
                    &stable_argument_origins,
                    &mut runtime_index_arguments,
                    &mut next_runtime_argument,
                    operations,
                    next_value,
                )?;
                reserve_operation(operations)?;
                let index = next_value_id(next_value)?;
                let success = next_value_id(next_value)?;
                operations.push(ProductionRankedOperationV1::PredicatedCheckedTiledIndex2D {
                    result: index,
                    success,
                    invocation: projected.value,
                    component,
                    rows,
                    columns,
                    row_stride,
                    physical_extent: ProductionRankedValueV1::Argument(0),
                    lanes_per_tile: *lanes_per_tile,
                    tile_rows: *tile_rows,
                    tile_columns: *tile_columns,
                    elements_per_lane: *elements_per_lane,
                });
                (
                    *element,
                    ProductionRankedValueV1::Local(index),
                    projected.precondition,
                    Some(ProductionRankedValueV1::Local(success)),
                    write_only_effect,
                )
            }
            SemanticCompilerIntrinsicOperationV1::DisjointSliceGetRowStriped2dMut {
                element,
                index_space,
                lanes_per_row,
                elements_per_lane,
                ..
            }
            | SemanticCompilerIntrinsicOperationV1::WriteOnlyDisjointSliceWrite {
                element,
                index_space,
                kind:
                    SemanticWriteOnlyDisjointWriteKindV1::RowStriped2d {
                        lanes_per_row,
                        elements_per_lane,
                    },
                ..
            } => {
                let projected = projected_disjoint_operand_v1(
                    call,
                    1,
                    &index_values,
                    &option_dominance,
                    &enum_payload_dominance,
                    block_index,
                )?;
                let expected = SemanticDisjointIndexSpaceV1::RowStriped2dIndex1d {
                    lanes_per_row: *lanes_per_row,
                    elements_per_lane: *elements_per_lane,
                };
                if projected.mapping != expected
                    || *index_space != expected
                    || !row_striped_2d_geometry_valid_v1(*lanes_per_row, *elements_per_lane)
                {
                    return Err(ProductionRankedProjectionErrorV1::Unsupported(
                        "row-striped-2d accessor mapping identity changed",
                    ));
                }
                let component = project_runtime_index_operand_v1(
                    call.arguments().get(2),
                    constants,
                    &stable_argument_origins,
                    &mut runtime_index_arguments,
                    &mut next_runtime_argument,
                    operations,
                    next_value,
                )?;
                let rows = project_runtime_index_operand_v1(
                    call.arguments().get(3),
                    constants,
                    &stable_argument_origins,
                    &mut runtime_index_arguments,
                    &mut next_runtime_argument,
                    operations,
                    next_value,
                )?;
                let columns = project_runtime_index_operand_v1(
                    call.arguments().get(4),
                    constants,
                    &stable_argument_origins,
                    &mut runtime_index_arguments,
                    &mut next_runtime_argument,
                    operations,
                    next_value,
                )?;
                let row_stride = project_runtime_index_operand_v1(
                    call.arguments().get(5),
                    constants,
                    &stable_argument_origins,
                    &mut runtime_index_arguments,
                    &mut next_runtime_argument,
                    operations,
                    next_value,
                )?;
                reserve_operation(operations)?;
                let index = next_value_id(next_value)?;
                let success = next_value_id(next_value)?;
                operations.push(
                    ProductionRankedOperationV1::PredicatedCheckedRowStripedIndex2D {
                        result: index,
                        success,
                        invocation: projected.value,
                        component,
                        rows,
                        columns,
                        row_stride,
                        physical_extent: ProductionRankedValueV1::Argument(0),
                        lanes_per_row: *lanes_per_row,
                        elements_per_lane: *elements_per_lane,
                    },
                );
                (
                    *element,
                    ProductionRankedValueV1::Local(index),
                    projected.precondition,
                    Some(ProductionRankedValueV1::Local(success)),
                    write_only_effect,
                )
            }
            _ => continue,
        };

        root_guarded_access_preparation_v1::append_mutable_access_legacy_v1(
            types,
            call,
            block_index,
            block.terminator().source(),
            element,
            index,
            precondition,
            checked_success,
            direct_write,
            &local_allocations,
            &allocation_provenance,
            &mut views_by_origin,
            &mut guarded_accesses,
            &mut option_predicates,
            &mut direct_write_effects,
            operations,
            next_value,
            ranked_ir,
        )?;
    }

    let mut direct_switch_predicates = vec![None; local_count];
    for block in function.blocks() {
        for statement in block.statements() {
            let SemanticStatementKindV1::Assign(assignment) = statement.kind() else {
                continue;
            };
            if !assignment.destination().projections().is_empty() {
                continue;
            }
            let SemanticRvalueKindV1::Binary {
                operation: SemanticBinaryOpV1::LessThan,
                left,
                right,
            } = assignment.value().kind()
            else {
                continue;
            };
            let destination = assignment.destination().local().index() as usize;
            if local_definitions.get(destination).copied() != Some(1)
                || scalar_inventory.address_escaped.get(destination).copied() != Some(false)
            {
                continue;
            }
            let Some(lhs) = project_uniform_switch_operand_v1(
                left,
                constants,
                &stable_argument_origins,
                &mut runtime_index_arguments,
                &mut next_runtime_argument,
                operations,
                next_value,
            )?
            else {
                continue;
            };
            let Some(rhs) = project_uniform_switch_operand_v1(
                right,
                constants,
                &stable_argument_origins,
                &mut runtime_index_arguments,
                &mut next_runtime_argument,
                operations,
                next_value,
            )?
            else {
                continue;
            };
            retain_identical_direct_switch_predicate_v1(
                direct_switch_predicates.get_mut(destination).ok_or(
                    ProductionRankedProjectionErrorV1::Unsupported(
                        "a direct switch predicate outside the semantic local table",
                    ),
                )?,
                GuardPredicateV1 {
                    comparisons: vec![(lhs, rhs)],
                },
            )?;
        }
    }
    let mut uniform_inductions = project_uniform_inductions_with_multi_entry_v1(
        callables,
        types,
        function,
        constants,
        &stable_argument_origins,
        &local_definitions,
        &mut runtime_index_arguments,
        &mut next_runtime_argument,
        operations,
        next_value,
        multi.as_deref_mut(),
    )?;
    reconcile_source_progress_with_multi_entry_v1(
        types,
        function,
        constants,
        &stable_argument_origins,
        &local_definitions,
        &runtime_index_arguments,
        &mut uniform_inductions,
        operations,
        next_value,
        multi,
    )?;
    project_induction_body_predicates_v1(
        types,
        function,
        constants,
        &stable_argument_origins,
        &local_definitions,
        &mut uniform_inductions,
        &mut runtime_index_arguments,
        &mut next_runtime_argument,
        operations,
        next_value,
    )?;
    let projected_switch_predicates =
        switch_predicates(function, &option_predicates, &direct_switch_predicates)?;
    let deterministic_switches = project_deterministic_scalar_switches_v1(
        types,
        callables,
        callable_effects,
        function,
        constants,
        &local_definitions,
        &stable_argument_origins,
        &index_values,
        &local_allocations,
        &projected_switch_predicates,
        &mut runtime_index_arguments,
        &mut next_runtime_argument,
        operations,
        next_value,
    )?;
    bind_optional_induction_preheaders_v1(
        function,
        &projected_switch_predicates,
        &deterministic_switches,
        &uniform_inductions,
    )?;
    let pipeline_effects = project_workgroup_pipeline_effects_v1(
        callables,
        types,
        function,
        &index_values,
        &mut runtime_index_arguments,
        &mut next_runtime_argument,
        &uniform_inductions,
        operations,
        next_value,
    )?;

    let checked_reference_origins = checked_reference_origins(
        function,
        callables,
        guarded_accesses.len(),
        &edges_by_source,
        &option_dominance,
        &enum_payload_dominance,
    )?;
    let local_contracts = ProjectionLocalContractsV1 {
        immutable_locals: immutable_local_array_candidates_v1(function, &scalar_inventory),
        checked_references: CheckedReferencesV1 {
            origins: checked_reference_origins,
            option_dominance,
            enum_payload_dominance,
        },
        allocations: local_allocations,
        allocation_provenance,
    };
    let generated_terminator_effects =
        project_generated_terminator_effects_v1(types, function, callables)?;
    Ok(IntrinsicProjectionV1 {
        index_values,
        ordinary_index_values,
        local_contracts,
        extent_argument_count: if guarded_accesses.is_empty()
            && direct_read_effects.iter().all(Option::is_none)
            && direct_write_effects.iter().all(Option::is_none)
            && next_runtime_argument == 1
        {
            0
        } else {
            next_runtime_argument
        },
        guarded_accesses,
        option_predicates,
        direct_switch_predicates,
        deterministic_switches,
        uniform_inductions,
        tensor_layouts,
        capability_read_effects,
        transpose_workgroup_effects,
        read_view_effects,
        direct_read_effects,
        direct_write_effects,
        pipeline_effects,
        generated_terminator_effects,
        slice_extent_scratch: Some(slice_extent_projection_v1::Scratch {
            origins: stable_argument_origins,
            arguments: runtime_slice_extent_arguments,
            definitions: scalar_inventory.counts,
            escaped: scalar_inventory.address_escaped,
        }),
    })
}

#[derive(Clone, Debug)]
struct PendingWorkgroupPipelineV1 {
    create_block: usize,
    destination: usize,
    buffers: u32,
    elements: u64,
    prefetch_distance: u32,
    element_width: Option<u32>,
    view: Option<ProductionRankedValueIdV1>,
    pipeline: Option<ProductionRankedValueIdV1>,
    modulus: Option<ProductionRankedValueV1>,
}

#[allow(clippy::too_many_arguments)]
fn project_workgroup_pipeline_effects_v1(
    callables: &[SemanticCallableDeclV1],
    types: &[SemanticTypeDeclV1],
    function: &SemanticFunctionDeclV1,
    index_values: &[Option<ProjectedDisjointIndexV1>],
    runtime_index_arguments: &mut [Option<u32>],
    next_runtime_argument: &mut usize,
    uniform_inductions: &[ProjectedUniformInductionV1],
    entry_operations: &mut Vec<ProductionRankedOperationV1>,
    next_value: &mut u32,
) -> Result<Vec<Option<ProjectedPipelineEffectV1>>, ProductionRankedProjectionErrorV1> {
    let mut pending = Vec::<PendingWorkgroupPipelineV1>::new();
    let mut owners = vec![None; function.locals().len()];
    for (block_index, block) in function.blocks().iter().enumerate() {
        let SemanticTerminatorKindV1::Call(call) = block.terminator().kind() else {
            continue;
        };
        let Some(SemanticCallableDeclV1::CompilerIntrinsic {
            operation:
                SemanticCompilerIntrinsicOperationV1::WorkgroupPipelineCreate {
                    pipeline: _,
                    buffers,
                    elements,
                    prefetch_distance,
                    ..
                },
            ..
        }) = callables.get(call.callee().index() as usize)
        else {
            continue;
        };
        let destination = simple_call_destination(call)?.index() as usize;
        if pending.len() == dialect_kernel::MAX_PIPELINE_BUFFERS_V1 as usize * 64
            || owners.get(destination).is_none_or(Option::is_some)
        {
            return Err(ProductionRankedProjectionErrorV1::Unsupported(
                "workgroup pipeline creation count or destination is not uniquely bounded",
            ));
        }
        owners[destination] = Some(pending.len());
        pending.push(PendingWorkgroupPipelineV1 {
            create_block: block_index,
            destination,
            buffers: *buffers,
            elements: *elements,
            prefetch_distance: *prefetch_distance,
            element_width: None,
            view: None,
            pipeline: None,
            modulus: None,
        });
    }
    if pending.is_empty() {
        return Ok(vec![None; function.blocks().len()]);
    }
    let scalar_assertion_proofs = SemanticAssertProofsV1::new(types, function)?;
    propagate_workgroup_pipeline_aliases_v1(function, &mut owners)?;

    for block in function.blocks() {
        let SemanticTerminatorKindV1::Call(call) = block.terminator().kind() else {
            continue;
        };
        let Some(SemanticCallableDeclV1::CompilerIntrinsic { operation, .. }) =
            callables.get(call.callee().index() as usize)
        else {
            continue;
        };
        let element = match operation {
            SemanticCompilerIntrinsicOperationV1::WorkgroupPipelineWrite { element, .. }
            | SemanticCompilerIntrinsicOperationV1::WorkgroupPipelineRead { element, .. } => {
                Some(*element)
            }
            _ => None,
        };
        let Some(element) = element else {
            continue;
        };
        let owner = pipeline_call_owner_v1(call, &owners)?;
        let declaration = types.get(element.index() as usize).ok_or(
            ProductionRankedProjectionErrorV1::Unsupported(
                "a workgroup pipeline element type is missing",
            ),
        )?;
        let bits = declaration
            .layout()
            .size_bytes()
            .and_then(|bytes| bytes.checked_mul(8))
            .and_then(|bits| u32::try_from(bits).ok())
            .filter(|bits| SUPPORTED_ELEMENT_WIDTHS.contains(bits))
            .ok_or(ProductionRankedProjectionErrorV1::Unsupported(
                "a workgroup pipeline payload has an unsupported device width",
            ))?;
        match pending[owner].element_width {
            None => pending[owner].element_width = Some(bits),
            Some(existing) if existing == bits => {}
            Some(_) => {
                return Err(ProductionRankedProjectionErrorV1::Incomplete(
                    "one workgroup pipeline is used with inconsistent payload widths",
                ));
            }
        }
    }

    for (index, pipeline) in pending.iter_mut().enumerate() {
        let element_width =
            pipeline
                .element_width
                .ok_or(ProductionRankedProjectionErrorV1::Incomplete(
                    "a workgroup pipeline has no statically typed write or read",
                ))?;
        let view = next_value_id(next_value)?;
        let modulus_id = next_value_id(next_value)?;
        let pipeline_result = next_value_id(next_value)?;
        reserve_operation(entry_operations)?;
        entry_operations.push(ProductionRankedOperationV1::ViewInSpace {
            result: view,
            element_width,
            writable: true,
            shape: vec![u64::from(pipeline.buffers), pipeline.elements],
            dynamic_extents: Vec::new(),
            memory_space: MemorySpaceAttr::Workgroup,
            allocation_origin: 0x5049_5045_0000_0000_u64 | (index as u64 + 1),
            noalias_class: 0x5049_5045_8000_0000_u64 | (index as u64 + 1),
        });
        reserve_operation(entry_operations)?;
        entry_operations.push(ProductionRankedOperationV1::IndexConstant {
            result: modulus_id,
            value: u64::from(pipeline.buffers),
        });
        reserve_operation(entry_operations)?;
        entry_operations.push(ProductionRankedOperationV1::PipelineCreate {
            result: pipeline_result,
            view: ProductionRankedValueV1::Local(view),
            buffers: pipeline.buffers,
            prefetch_distance: pipeline.prefetch_distance,
        });
        pipeline.view = Some(view);
        pipeline.pipeline = Some(pipeline_result);
        pipeline.modulus = Some(ProductionRankedValueV1::Local(modulus_id));
    }

    let mut scalar_projector = PipelineScalarProjectorV1 {
        types,
        function,
        index_values,
        runtime_index_arguments,
        next_runtime_argument,
        uniform_inductions,
        entry_operations,
        next_value,
        assertion_proofs: scalar_assertion_proofs,
        work: 0,
    };
    let mut effects = vec![None; function.blocks().len()];
    for (block_index, block) in function.blocks().iter().enumerate() {
        let SemanticTerminatorKindV1::Call(call) = block.terminator().kind() else {
            continue;
        };
        let Some(SemanticCallableDeclV1::CompilerIntrinsic { operation, .. }) =
            callables.get(call.callee().index() as usize)
        else {
            continue;
        };
        let effect = match operation {
            SemanticCompilerIntrinsicOperationV1::WorkgroupPipelineCreate { .. } => {
                let owner = owners[simple_call_destination(call)?.index() as usize].ok_or(
                    ProductionRankedProjectionErrorV1::Incomplete(
                        "a pipeline creation lost its destination ownership",
                    ),
                )?;
                let contract = &pending[owner];
                debug_assert_eq!(contract.create_block, block_index);
                debug_assert_eq!(
                    contract.destination,
                    simple_call_destination(call)?.index() as usize
                );
                let result =
                    contract
                        .pipeline
                        .ok_or(ProductionRankedProjectionErrorV1::Incomplete(
                            "a workgroup pipeline creation result was not assigned",
                        ))?;
                let view = contract
                    .view
                    .ok_or(ProductionRankedProjectionErrorV1::Incomplete(
                        "a workgroup pipeline view was not assigned",
                    ))?;
                ProjectedPipelineEffectV1::Create {
                    owner,
                    result: Some(result),
                    view: ProductionRankedValueV1::Local(view),
                    buffers: contract.buffers,
                    prefetch_distance: contract.prefetch_distance,
                }
            }
            SemanticCompilerIntrinsicOperationV1::WorkgroupPipelineEvent { event, .. } => {
                let owner = pipeline_call_owner_v1(call, &owners)?;
                let contract = &pending[owner];
                let epoch = scalar_projector.project_root(block_index, &call.arguments()[1])?;
                let modulus =
                    contract
                        .modulus
                        .ok_or(ProductionRankedProjectionErrorV1::Incomplete(
                            "a workgroup pipeline modulus was not assigned",
                        ))?;
                ProjectedPipelineEffectV1::Event {
                    owner,
                    epoch,
                    slot_result: None,
                    modulus,
                    kind: pipeline_event_kind_v1(*event),
                }
            }
            SemanticCompilerIntrinsicOperationV1::WorkgroupPipelineWrite { .. }
            | SemanticCompilerIntrinsicOperationV1::WorkgroupPipelineRead { .. } => {
                let owner = pipeline_call_owner_v1(call, &owners)?;
                let contract = &pending[owner];
                let epoch = scalar_projector.project_root(block_index, &call.arguments()[1])?;
                let index = scalar_projector.project_root(block_index, &call.arguments()[2])?;
                let view = contract
                    .view
                    .ok_or(ProductionRankedProjectionErrorV1::Incomplete(
                        "a workgroup pipeline view was not assigned",
                    ))?;
                let modulus =
                    contract
                        .modulus
                        .ok_or(ProductionRankedProjectionErrorV1::Incomplete(
                            "a workgroup pipeline modulus was not assigned",
                        ))?;
                ProjectedPipelineEffectV1::Access {
                    view: ProductionRankedValueV1::Local(view),
                    epoch,
                    index,
                    slot_result: None,
                    modulus,
                    kind: if matches!(
                        operation,
                        SemanticCompilerIntrinsicOperationV1::WorkgroupPipelineWrite { .. }
                    ) {
                        AccessKindAttr::Write
                    } else {
                        AccessKindAttr::Read
                    },
                }
            }
            _ => continue,
        };
        if effects[block_index].replace(effect).is_some() {
            return Err(ProductionRankedProjectionErrorV1::Unsupported(
                "a semantic block contains multiple pipeline terminals",
            ));
        }
    }
    Ok(effects)
}

fn pipeline_call_owner_v1(
    call: &SemanticDirectCallV1,
    owners: &[Option<usize>],
) -> Result<usize, ProductionRankedProjectionErrorV1> {
    let local = call
        .arguments()
        .first()
        .and_then(raw_operand_place)
        .map(|place| place.local().index() as usize)
        .ok_or(ProductionRankedProjectionErrorV1::Incomplete(
            "a workgroup pipeline method has no exact receiver local",
        ))?;
    owners
        .get(local)
        .copied()
        .flatten()
        .ok_or(ProductionRankedProjectionErrorV1::Incomplete(
            "a workgroup pipeline method receiver lacks one compiler-owned origin",
        ))
}

const fn pipeline_event_kind_v1(event: SemanticWorkgroupPipelineEventV1) -> PipelineEventKindAttr {
    match event {
        SemanticWorkgroupPipelineEventV1::Stage => PipelineEventKindAttr::Stage,
        SemanticWorkgroupPipelineEventV1::Commit => PipelineEventKindAttr::Commit,
        SemanticWorkgroupPipelineEventV1::Wait => PipelineEventKindAttr::Wait,
        SemanticWorkgroupPipelineEventV1::Consume => PipelineEventKindAttr::Consume,
        SemanticWorkgroupPipelineEventV1::Discard => PipelineEventKindAttr::Discard,
        SemanticWorkgroupPipelineEventV1::Release => PipelineEventKindAttr::Release,
    }
}

fn write_pipeline_scalar_rejection_v1(
    enabled: bool,
    writer: &mut impl std::io::Write,
    local: usize,
    use_block: usize,
    use_statement: usize,
    definitions_capped: u8,
) {
    if !enabled {
        return;
    }
    // The existing inventory saturates at 255; no definitions are recounted here.
    let _ = writeln!(
        writer,
        "PIPELINE_SCALAR_REJECTION_V1 local={local} use_block={use_block} use_statement={use_statement} definitions_capped={definitions_capped}",
    );
}

fn trace_pipeline_scalar_rejection_v1(
    local: usize,
    use_block: usize,
    use_statement: usize,
    definitions_capped: u8,
) {
    if std::env::var_os("FE2O3_TRACE_RANKED_CUSTODY_V1").is_none() {
        return;
    }
    write_pipeline_scalar_rejection_v1(
        true,
        &mut std::io::stderr().lock(),
        local,
        use_block,
        use_statement,
        definitions_capped,
    );
}

fn pipeline_scalar_multiple_definitions_v1(
    local: usize,
    use_site: ScalarAssignmentSiteV1,
    definitions_capped: u8,
    observe: impl FnOnce(usize, usize, usize, u8),
) -> ProductionRankedProjectionErrorV1 {
    observe(
        local,
        use_site.block,
        use_site.statement,
        definitions_capped,
    );
    ProductionRankedProjectionErrorV1::Incomplete(
        "a pipeline scalar temporary has multiple definitions",
    )
}

struct PipelineScalarProjectorV1<'a> {
    types: &'a [SemanticTypeDeclV1],
    function: &'a SemanticFunctionDeclV1,
    index_values: &'a [Option<ProjectedDisjointIndexV1>],
    runtime_index_arguments: &'a mut [Option<u32>],
    next_runtime_argument: &'a mut usize,
    uniform_inductions: &'a [ProjectedUniformInductionV1],
    entry_operations: &'a mut Vec<ProductionRankedOperationV1>,
    next_value: &'a mut u32,
    assertion_proofs: SemanticAssertProofsV1<'a>,
    work: usize,
}

impl PipelineScalarProjectorV1<'_> {
    fn project_root(
        &mut self,
        block: usize,
        operand: &SemanticOperandV1,
    ) -> Result<ProjectedPipelineScalarV1, ProductionRankedProjectionErrorV1> {
        let Some(semantic_block) = self.function.blocks().get(block) else {
            return Err(ProductionRankedProjectionErrorV1::Unsupported(
                "a pipeline scalar use is outside the semantic CFG",
            ));
        };
        self.work = 0;
        self.project_operand(
            operand,
            ScalarAssignmentSiteV1 {
                block,
                statement: semantic_block.statements().len(),
            },
            &mut HashSet::new(),
        )
    }

    fn charge(&mut self) -> Result<(), ProductionRankedProjectionErrorV1> {
        self.work =
            self.work
                .checked_add(1)
                .ok_or(ProductionRankedProjectionErrorV1::Unsupported(
                    "pipeline scalar work accounting overflowed",
                ))?;
        if self.work > MAX_PIPELINE_SCALAR_NODES_V1 {
            return Err(ProductionRankedProjectionErrorV1::Unsupported(
                "pipeline scalar expression exceeds its node limit",
            ));
        }
        Ok(())
    }

    fn project_operand(
        &mut self,
        operand: &SemanticOperandV1,
        use_site: ScalarAssignmentSiteV1,
        visiting: &mut HashSet<usize>,
    ) -> Result<ProjectedPipelineScalarV1, ProductionRankedProjectionErrorV1> {
        self.charge()?;

        // Checked field zero is authority-bearing. Authenticate it before any
        // bound/constant shortcut can substitute a ranked value.
        if tuple_field_operand_local_v1(operand, 0).is_some() {
            return self.project_checked_result(operand, use_site, visiting);
        }
        let Some(bits) = unsigned_index_bits_v1(self.types, operand.ty()) else {
            return Err(ProductionRankedProjectionErrorV1::Incomplete(
                "a pipeline scalar is not an exact unsigned index expression",
            ));
        };
        if let SemanticOperandV1::Constant(constant) = operand {
            let SemanticConstantValueV1::Scalar(value) = constant.value() else {
                return Err(ProductionRankedProjectionErrorV1::Incomplete(
                    "a pipeline scalar constant is not a scalar integer",
                ));
            };
            let value = u64::try_from(value.bits()).map_err(|_| {
                ProductionRankedProjectionErrorV1::Incomplete(
                    "a pipeline scalar constant exceeds ranked index width",
                )
            })?;
            if bits < 64 && value >= (1_u64 << bits) {
                return Err(ProductionRankedProjectionErrorV1::Unsupported(
                    "a pipeline scalar constant exceeds its semantic type",
                ));
            }
            return self.constant(value);
        }
        if let Some(bound) = self
            .uniform_inductions
            .iter()
            .find(|induction| operand == &induction.source_progress.bound_operand)
            .map(|induction| induction.bound)
        {
            self.authenticate_cached_induction_bound_v1(operand, use_site)?;
            return Ok(ProjectedPipelineScalarV1::Value(bound));
        }
        for (induction_index, induction) in self.uniform_inductions.iter().enumerate() {
            if simple_operand_local(operand) == Some(induction.source_progress.induction)
                && (induction.contains_block(use_site.block) || induction.header == use_site.block)
            {
                let induction_local = induction.source_progress.induction.index() as usize;
                if self
                    .assertion_proofs
                    .address_escaped
                    .get(induction_local)
                    .copied()
                    != Some(false)
                {
                    return Err(ProductionRankedProjectionErrorV1::Incomplete(
                        "a cached pipeline induction has address-escaped value semantics",
                    ));
                }
                return Ok(ProjectedPipelineScalarV1::Induction {
                    induction: induction_index,
                });
            }
        }
        let place =
            raw_operand_place(operand).ok_or(ProductionRankedProjectionErrorV1::Incomplete(
                "a pipeline epoch or element index is not a retained scalar place",
            ))?;
        if !place.projections().is_empty() {
            return Err(ProductionRankedProjectionErrorV1::Incomplete(
                "a pipeline scalar uses an unsupported place projection",
            ));
        }
        let local = place.local().index() as usize;
        let declaration = self.function.locals().get(local).ok_or(
            ProductionRankedProjectionErrorV1::Unsupported(
                "a pipeline scalar local is outside the semantic local table",
            ),
        )?;
        if self.assertion_proofs.address_escaped.get(local).copied() != Some(false) {
            return Err(ProductionRankedProjectionErrorV1::Incomplete(
                "a pipeline scalar local has address-escaped value semantics",
            ));
        }
        if let Some(index) = self.index_values.get(local).copied().flatten() {
            return Ok(ProjectedPipelineScalarV1::Value(index.value));
        }
        match self.assertion_proofs.definition_counts.get(local).copied() {
            Some(0) => {
                let SemanticLocalRoleV1::Argument(origin) = declaration.role() else {
                    return Err(ProductionRankedProjectionErrorV1::Incomplete(
                        "a pipeline scalar temporary has no retained definition",
                    ));
                };
                return self.argument(origin as usize);
            }
            Some(1) => {}
            Some(definitions_capped) => {
                return Err(pipeline_scalar_multiple_definitions_v1(
                    local,
                    use_site,
                    definitions_capped,
                    trace_pipeline_scalar_rejection_v1,
                ));
            }
            None => {
                return Err(ProductionRankedProjectionErrorV1::Unsupported(
                    "a pipeline scalar definition is outside the semantic local table",
                ));
            }
        }
        let Some(definition) = self
            .assertion_proofs
            .assignments
            .get(local)
            .copied()
            .flatten()
        else {
            return Err(ProductionRankedProjectionErrorV1::Incomplete(
                "a pipeline scalar has no exact assignment definition",
            ));
        };
        if !self.assertion_proofs.assignment_dominates_use(
            definition,
            use_site.block,
            use_site.statement,
        )? {
            return Err(ProductionRankedProjectionErrorV1::Incomplete(
                "a pipeline scalar definition does not dominate its exact use",
            ));
        }
        if !visiting.insert(local) {
            return Err(ProductionRankedProjectionErrorV1::Incomplete(
                "a pipeline scalar expression is cyclic",
            ));
        }
        let statement = self.function.blocks()[definition.block].statements()[definition.statement]
            .kind()
            .clone();
        let SemanticStatementKindV1::Assign(assignment) = statement else {
            visiting.remove(&local);
            return Err(ProductionRankedProjectionErrorV1::Unsupported(
                "an indexed pipeline scalar assignment changed semantic kind",
            ));
        };
        let result = self.project_rvalue(assignment.value(), definition, visiting);
        visiting.remove(&local);
        result
    }

    fn authenticate_cached_induction_bound_v1(
        &mut self,
        operand: &SemanticOperandV1,
        use_site: ScalarAssignmentSiteV1,
    ) -> Result<(), ProductionRankedProjectionErrorV1> {
        let place =
            raw_operand_place(operand).ok_or(ProductionRankedProjectionErrorV1::Incomplete(
                "a cached pipeline induction bound is not an exact scalar place",
            ))?;
        if !place.projections().is_empty() {
            return Err(ProductionRankedProjectionErrorV1::Incomplete(
                "a cached pipeline induction bound has an unsupported place projection",
            ));
        }
        let local = place.local().index() as usize;
        let declaration = self.function.locals().get(local).ok_or(
            ProductionRankedProjectionErrorV1::Unsupported(
                "a cached pipeline induction bound is outside the semantic local table",
            ),
        )?;
        if self.assertion_proofs.address_escaped.get(local).copied() != Some(false) {
            return Err(ProductionRankedProjectionErrorV1::Incomplete(
                "a cached pipeline induction bound has address-escaped value semantics",
            ));
        }
        match self.assertion_proofs.definition_counts.get(local).copied() {
            Some(0) if matches!(declaration.role(), SemanticLocalRoleV1::Argument(_)) => Ok(()),
            Some(0) => Err(ProductionRankedProjectionErrorV1::Incomplete(
                "a cached pipeline induction bound has no exact definition",
            )),
            Some(1) => {
                let Some(definition) = self
                    .assertion_proofs
                    .assignments
                    .get(local)
                    .copied()
                    .flatten()
                else {
                    return Err(ProductionRankedProjectionErrorV1::Incomplete(
                        "a cached pipeline induction bound has no exact assignment definition",
                    ));
                };
                if !self.assertion_proofs.assignment_dominates_use(
                    definition,
                    use_site.block,
                    use_site.statement,
                )? {
                    return Err(ProductionRankedProjectionErrorV1::Incomplete(
                        "a cached pipeline induction bound definition does not dominate its exact use",
                    ));
                }
                Ok(())
            }
            Some(_) => Err(ProductionRankedProjectionErrorV1::Incomplete(
                "a cached pipeline induction bound has multiple definitions",
            )),
            None => Err(ProductionRankedProjectionErrorV1::Unsupported(
                "a cached pipeline induction bound definition is outside the semantic local table",
            )),
        }
    }

    fn project_checked_result(
        &mut self,
        operand: &SemanticOperandV1,
        use_site: ScalarAssignmentSiteV1,
        visiting: &mut HashSet<usize>,
    ) -> Result<ProjectedPipelineScalarV1, ProductionRankedProjectionErrorV1> {
        let Some(authenticated) = self
            .assertion_proofs
            .authenticated_checked_binary_value_v1(operand, use_site.block, use_site.statement)?
        else {
            return Err(ProductionRankedProjectionErrorV1::Incomplete(
                "a checked pipeline scalar lacks exact dominating overflow authority",
            ));
        };
        let kind = match authenticated.checked.operation() {
            SemanticCheckedBinaryOpV1::Add => IndexBinaryKindAttr::Add,
            SemanticCheckedBinaryOpV1::Multiply => IndexBinaryKindAttr::Multiply,
            SemanticCheckedBinaryOpV1::Subtract => {
                return Err(ProductionRankedProjectionErrorV1::Incomplete(
                    "a checked pipeline scalar uses an unsupported integer operation",
                ));
            }
        };
        if !visiting.insert(authenticated.local) {
            return Err(ProductionRankedProjectionErrorV1::Incomplete(
                "a checked pipeline scalar expression is cyclic",
            ));
        }
        let definition = authenticated.definition;
        let left = self.project_operand(authenticated.checked.left(), definition, visiting);
        let right = match left {
            Ok(left) => self
                .project_operand(authenticated.checked.right(), definition, visiting)
                .map(|right| (left, right)),
            Err(error) => Err(error),
        };
        visiting.remove(&authenticated.local);
        let (left, right) = right?;
        if !self
            .assertion_proofs
            .proves_authenticated_checked_binary_total_for_pipeline_v1(
                &authenticated,
                &left,
                &right,
                self.uniform_inductions,
            )?
        {
            return Err(ProductionRankedProjectionErrorV1::Incomplete(
                "a checked pipeline scalar is not an exact total unsigned index expression",
            ));
        }
        Ok(ProjectedPipelineScalarV1::Binary {
            result: None,
            kind,
            left: Box::new(left),
            right: Box::new(right),
        })
    }

    fn project_rvalue(
        &mut self,
        value: &fe2o3_mir_model::semantic_mir_v1::SemanticRvalueV1,
        definition: ScalarAssignmentSiteV1,
        visiting: &mut HashSet<usize>,
    ) -> Result<ProjectedPipelineScalarV1, ProductionRankedProjectionErrorV1> {
        match value.kind() {
            SemanticRvalueKindV1::Use(source) if source.ty() == value.result_type() => {
                self.project_operand(source, definition, visiting)
            }
            SemanticRvalueKindV1::Cast {
                kind: SemanticCastKindV1::Integer,
                operand: source,
            } if value_preserving_unsigned_index_cast_v1(
                self.types,
                source.ty(),
                value.result_type(),
            ) =>
            {
                self.project_operand(source, definition, visiting)
            }
            SemanticRvalueKindV1::Binary {
                operation,
                left,
                right,
            } => {
                let kind = match operation {
                    SemanticBinaryOpV1::Add => IndexBinaryKindAttr::Add,
                    SemanticBinaryOpV1::Multiply => IndexBinaryKindAttr::Multiply,
                    SemanticBinaryOpV1::Divide => IndexBinaryKindAttr::Divide,
                    SemanticBinaryOpV1::Remainder => IndexBinaryKindAttr::Remainder,
                    _ => {
                        return Err(ProductionRankedProjectionErrorV1::Incomplete(
                            "a pipeline scalar uses an unsupported integer operation",
                        ));
                    }
                };
                let left_range = self.assertion_proofs.range_at_operand(
                    left,
                    definition.block,
                    definition.statement,
                )?;
                let right_range = self.assertion_proofs.range_at_operand(
                    right,
                    definition.block,
                    definition.statement,
                )?;
                let maximum = self
                    .assertion_proofs
                    .scalar_unsigned_maximum(value.result_type());
                if SemanticAssertProofsV1::<'_>::range_of_binary(
                    *operation,
                    left_range,
                    right_range,
                    maximum,
                )?
                .is_none()
                {
                    return Err(ProductionRankedProjectionErrorV1::Incomplete(
                        "an ordinary pipeline scalar operation is not an exact total unsigned index expression",
                    ));
                }
                let left = self.project_operand(left, definition, visiting)?;
                let right = self.project_operand(right, definition, visiting)?;
                Ok(ProjectedPipelineScalarV1::Binary {
                    result: None,
                    kind,
                    left: Box::new(left),
                    right: Box::new(right),
                })
            }
            _ => Err(ProductionRankedProjectionErrorV1::Incomplete(
                "a pipeline scalar is not an exact unsigned index expression",
            )),
        }
    }

    fn constant(
        &mut self,
        value: u64,
    ) -> Result<ProjectedPipelineScalarV1, ProductionRankedProjectionErrorV1> {
        let result = next_value_id(self.next_value)?;
        reserve_operation(self.entry_operations)?;
        self.entry_operations
            .push(ProductionRankedOperationV1::IndexConstant { result, value });
        Ok(ProjectedPipelineScalarV1::Value(
            ProductionRankedValueV1::Local(result),
        ))
    }

    fn argument(
        &mut self,
        origin: usize,
    ) -> Result<ProjectedPipelineScalarV1, ProductionRankedProjectionErrorV1> {
        let slot = self.runtime_index_arguments.get_mut(origin).ok_or(
            ProductionRankedProjectionErrorV1::Unsupported(
                "a pipeline scalar argument is outside the semantic local table",
            ),
        )?;
        let argument = match *slot {
            Some(argument) => argument,
            None => {
                let argument = u32::try_from(*self.next_runtime_argument).map_err(|_| {
                    ProductionRankedProjectionErrorV1::Unsupported(
                        "too many pipeline scalar ranked arguments",
                    )
                })?;
                *self.next_runtime_argument = self.next_runtime_argument.checked_add(1).ok_or(
                    ProductionRankedProjectionErrorV1::Unsupported(
                        "pipeline scalar ranked argument count overflow",
                    ),
                )?;
                *slot = Some(argument);
                argument
            }
        };
        Ok(ProjectedPipelineScalarV1::Value(
            ProductionRankedValueV1::Argument(argument),
        ))
    }
}

fn value_preserving_unsigned_index_cast_v1(
    types: &[SemanticTypeDeclV1],
    source: SemanticTypeIdV1,
    destination: SemanticTypeIdV1,
) -> bool {
    unsigned_index_bits_v1(types, source)
        .zip(unsigned_index_bits_v1(types, destination))
        .is_some_and(|(source, destination)| source <= destination)
}

fn unsigned_index_bits_v1(types: &[SemanticTypeDeclV1], ty: SemanticTypeIdV1) -> Option<u16> {
    match types.get(ty.index() as usize)?.shape() {
        SemanticTypeShapeV1::Scalar(SemanticScalarTypeV1::Integer {
            signed: false,
            bits,
        }) if *bits <= 64 => Some(*bits),
        _ => None,
    }
}

fn reject_retired_production_intrinsics_v1(
    callables: &[SemanticCallableDeclV1],
) -> Result<(), ProductionRankedProjectionErrorV1> {
    if callables.iter().any(|callable| {
        matches!(
            callable,
            SemanticCallableDeclV1::CompilerIntrinsic {
                operation: SemanticCompilerIntrinsicOperationV1::Execution(_),
                ..
            }
        )
    }) {
        return Err(ProductionRankedProjectionErrorV1::Unsupported(
            "execution capabilities require checked canonical KIR materialization",
        ));
    }
    if callables.iter().any(|callable| {
        matches!(
            callable,
            SemanticCallableDeclV1::CompilerIntrinsic {
                operation: SemanticCompilerIntrinsicOperationV1::Bf16MatrixLoad { .. },
                ..
            }
        )
    }) {
        Err(ProductionRankedProjectionErrorV1::Unsupported(
            "the retired Option-returning BF16 matrix load; use Bf16MatrixLoadZeroFilledV2",
        ))
    } else {
        Ok(())
    }
}

fn retain_identical_direct_switch_predicate_v1(
    slot: &mut Option<GuardPredicateV1>,
    candidate: GuardPredicateV1,
) -> Result<(), ProductionRankedProjectionErrorV1> {
    match slot {
        None => *slot = Some(candidate),
        Some(existing) if *existing == candidate => {}
        Some(_) => {
            return Err(ProductionRankedProjectionErrorV1::Incomplete(
                "one comparison local has conflicting source definitions",
            ));
        }
    }
    Ok(())
}

struct DeterministicControlReachabilityV1 {
    block_count: usize,
    predecessors: Option<Vec<Vec<usize>>>,
    targets: HashMap<usize, Vec<u8>>,
    work: usize,
    storage_entries: usize,
}

impl DeterministicControlReachabilityV1 {
    fn new(block_count: usize) -> Result<Self, ProductionRankedProjectionErrorV1> {
        if block_count > MAX_PROJECTED_CAPABILITY_STATE_ENTRIES_V1 {
            return Err(ProductionRankedProjectionErrorV1::Unsupported(
                "deterministic scalar reachability state exceeded its explicit storage limit",
            ));
        }
        Ok(Self {
            block_count,
            predecessors: None,
            targets: HashMap::new(),
            work: 0,
            storage_entries: 0,
        })
    }

    #[cfg(test)]
    fn install_successors(
        &mut self,
        successors: &[Vec<usize>],
    ) -> Result<(), ProductionRankedProjectionErrorV1> {
        if successors.len() != self.block_count {
            return Err(ProductionRankedProjectionErrorV1::Unsupported(
                "deterministic scalar successor table does not match the semantic CFG",
            ));
        }
        self.install_predecessors(|block, retained_storage| {
            let temporary_entries = successors[block].len().checked_mul(2).ok_or(
                ProductionRankedProjectionErrorV1::Unsupported(
                    "deterministic scalar reachability storage accounting overflowed",
                ),
            )?;
            if retained_storage
                .checked_add(temporary_entries)
                .is_none_or(|peak| peak > MAX_PROJECTED_CAPABILITY_STATE_ENTRIES_V1)
            {
                return Err(ProductionRankedProjectionErrorV1::Unsupported(
                    "deterministic scalar reachability state exceeded its explicit storage limit",
                ));
            }
            let mut copied = Vec::new();
            copied
                .try_reserve_exact(successors[block].len())
                .map_err(|_| {
                    ProductionRankedProjectionErrorV1::Unsupported(
                        "deterministic scalar successor storage cannot be reserved",
                    )
                })?;
            copied.extend_from_slice(&successors[block]);
            Ok(copied)
        })
    }

    fn install_function_successors(
        &mut self,
        function: &SemanticFunctionDeclV1,
        switch_predicates: &[Option<GuardPredicateV1>],
    ) -> Result<(), ProductionRankedProjectionErrorV1> {
        if function.blocks().len() != self.block_count {
            return Err(ProductionRankedProjectionErrorV1::Unsupported(
                "deterministic scalar successor table does not match the semantic CFG",
            ));
        }
        self.install_predecessors(|block, retained_storage| {
            let terminator = function.blocks()[block].terminator().kind();
            let temporary_entries = terminator.edge_count().checked_mul(2).ok_or(
                ProductionRankedProjectionErrorV1::Unsupported(
                    "deterministic scalar reachability storage accounting overflowed",
                ),
            )?;
            if retained_storage
                .checked_add(temporary_entries)
                .is_none_or(|peak| peak > MAX_PROJECTED_CAPABILITY_STATE_ENTRIES_V1)
            {
                return Err(ProductionRankedProjectionErrorV1::Unsupported(
                    "deterministic scalar reachability state exceeded its explicit storage limit",
                ));
            }
            deterministic_control_successors_v1(function, switch_predicates, terminator)
        })
    }

    fn install_predecessors(
        &mut self,
        mut successors_for: impl FnMut(
            usize,
            usize,
        ) -> Result<Vec<usize>, ProductionRankedProjectionErrorV1>,
    ) -> Result<(), ProductionRankedProjectionErrorV1> {
        if self.predecessors.is_some() {
            return Ok(());
        }

        let mut next_work = self.work;
        let mut next_storage = self.storage_entries.checked_add(self.block_count).ok_or(
            ProductionRankedProjectionErrorV1::Unsupported(
                "deterministic scalar reachability storage accounting overflowed",
            ),
        )?;
        if next_storage > MAX_PROJECTED_CAPABILITY_STATE_ENTRIES_V1 {
            return Err(ProductionRankedProjectionErrorV1::Unsupported(
                "deterministic scalar reachability state exceeded its explicit storage limit",
            ));
        }
        let mut predecessors = Vec::new();
        predecessors
            .try_reserve_exact(self.block_count)
            .map_err(|_| {
                ProductionRankedProjectionErrorV1::Unsupported(
                    "deterministic scalar predecessor table cannot be reserved",
                )
            })?;
        predecessors.resize_with(self.block_count, Vec::new);
        for block in 0..self.block_count {
            let block_successors = successors_for(block, next_storage)?;
            let temporary_entries = block_successors.len().checked_mul(2).ok_or(
                ProductionRankedProjectionErrorV1::Unsupported(
                    "deterministic scalar reachability storage accounting overflowed",
                ),
            )?;
            for successor in block_successors.iter().copied() {
                if successor >= self.block_count {
                    return Err(ProductionRankedProjectionErrorV1::Unsupported(
                        "a deterministic scalar reachability edge is outside the semantic CFG",
                    ));
                }
                next_work = next_work.checked_add(1).ok_or(
                    ProductionRankedProjectionErrorV1::Unsupported(
                        "deterministic scalar reachability work accounting overflowed",
                    ),
                )?;
                if next_work > MAX_PROJECTED_CAPABILITY_DATAFLOW_WORK_V1 {
                    return Err(ProductionRankedProjectionErrorV1::Unsupported(
                        "deterministic scalar reachability exceeded its explicit work limit",
                    ));
                }
                next_storage = next_storage.checked_add(1).ok_or(
                    ProductionRankedProjectionErrorV1::Unsupported(
                        "deterministic scalar reachability storage accounting overflowed",
                    ),
                )?;
                if next_storage
                    .checked_add(temporary_entries)
                    .is_none_or(|peak| peak > MAX_PROJECTED_CAPABILITY_STATE_ENTRIES_V1)
                {
                    return Err(ProductionRankedProjectionErrorV1::Unsupported(
                        "deterministic scalar reachability state exceeded its explicit storage limit",
                    ));
                }
                predecessors[successor].try_reserve(1).map_err(|_| {
                    ProductionRankedProjectionErrorV1::Unsupported(
                        "deterministic scalar predecessor storage cannot be reserved",
                    )
                })?;
                predecessors[successor].push(block);
            }
        }
        self.predecessors = Some(predecessors);
        self.work = next_work;
        self.storage_entries = next_storage;
        Ok(())
    }

    fn block_can_reach(
        &mut self,
        start: usize,
        target: usize,
    ) -> Result<bool, ProductionRankedProjectionErrorV1> {
        if start >= self.block_count || target >= self.block_count {
            return Err(ProductionRankedProjectionErrorV1::Unsupported(
                "a deterministic scalar reachability query is outside the semantic CFG",
            ));
        }
        if start == target {
            return Ok(true);
        }
        if let Some(reaches) = self.targets.get(&target) {
            return Ok(reaches[start] != 0);
        }
        let next_storage = self
            .storage_entries
            .checked_add(self.block_count)
            .and_then(|entries| entries.checked_add(1))
            .ok_or(ProductionRankedProjectionErrorV1::Unsupported(
                "deterministic scalar reachability storage accounting overflowed",
            ))?;
        if next_storage
            .checked_add(self.block_count)
            .is_none_or(|peak| peak > MAX_PROJECTED_CAPABILITY_STATE_ENTRIES_V1)
        {
            return Err(ProductionRankedProjectionErrorV1::Unsupported(
                "deterministic scalar reachability state exceeded its explicit storage limit",
            ));
        }
        self.targets.try_reserve(1).map_err(|_| {
            ProductionRankedProjectionErrorV1::Unsupported(
                "deterministic scalar reachability cache cannot be reserved",
            )
        })?;
        let Some(predecessors) = self.predecessors.as_ref() else {
            return Err(ProductionRankedProjectionErrorV1::Unsupported(
                "deterministic scalar predecessor state was not initialized",
            ));
        };

        let mut reaches = Vec::new();
        reaches.try_reserve_exact(self.block_count).map_err(|_| {
            ProductionRankedProjectionErrorV1::Unsupported(
                "deterministic scalar reachability bitmap cannot be reserved",
            )
        })?;
        reaches.resize(self.block_count, 0_u8);
        let mut worklist = Vec::new();
        worklist.try_reserve_exact(self.block_count).map_err(|_| {
            ProductionRankedProjectionErrorV1::Unsupported(
                "deterministic scalar reachability worklist cannot be reserved",
            )
        })?;
        reaches[target] = 1;
        worklist.push(target);
        let mut next_work = self.work;
        while let Some(block) = worklist.pop() {
            for predecessor in predecessors[block].iter().copied() {
                next_work = next_work.checked_add(1).ok_or(
                    ProductionRankedProjectionErrorV1::Unsupported(
                        "deterministic scalar reachability work accounting overflowed",
                    ),
                )?;
                if next_work > MAX_PROJECTED_CAPABILITY_DATAFLOW_WORK_V1 {
                    return Err(ProductionRankedProjectionErrorV1::Unsupported(
                        "deterministic scalar reachability exceeded its explicit work limit",
                    ));
                }
                if reaches[predecessor] == 0 {
                    reaches[predecessor] = 1;
                    worklist.push(predecessor);
                }
            }
        }

        let result = reaches[start] != 0;
        self.targets.insert(target, reaches);
        self.work = next_work;
        self.storage_entries = next_storage;
        Ok(result)
    }
}

fn deterministic_control_successors_v1(
    function: &SemanticFunctionDeclV1,
    switch_predicates: &[Option<GuardPredicateV1>],
    terminator: &SemanticTerminatorKindV1,
) -> Result<Vec<usize>, ProductionRankedProjectionErrorV1> {
    let proven_true = match terminator {
        SemanticTerminatorKindV1::SwitchInt {
            discriminant,
            targets,
        } => simple_operand_local(discriminant)
            .and_then(|local| switch_predicates.get(local.index() as usize))
            .and_then(Option::as_ref)
            .filter(|predicate| predicate.comparisons.is_empty())
            .map(|_| {
                let target = if targets.values().len() == 1 {
                    match targets.values()[0].value() {
                        0 => targets.otherwise().target(),
                        1 => targets.values()[0].edge().target(),
                        _ => {
                            return Err(ProductionRankedProjectionErrorV1::Incomplete(
                                "an authenticated empty predicate did not select a boolean switch",
                            ));
                        }
                    }
                } else {
                    let Some(target) = targets.values().iter().find(|target| target.value() == 1)
                    else {
                        return Err(ProductionRankedProjectionErrorV1::Incomplete(
                            "an authenticated empty predicate had no true switch variant",
                        ));
                    };
                    target.edge().target()
                };
                Ok(target.index() as usize)
            })
            .transpose()?,
        _ => None,
    };
    if let Some(successor) = proven_true {
        if successor >= function.blocks().len() {
            return Err(ProductionRankedProjectionErrorV1::Unsupported(
                "a deterministic scalar proven control edge is outside the semantic CFG",
            ));
        }
        return Ok(vec![successor]);
    }

    let mut successors = Vec::new();
    successors
        .try_reserve(terminator.edge_count())
        .map_err(|_| {
            ProductionRankedProjectionErrorV1::Unsupported(
                "deterministic scalar successor storage cannot be reserved",
            )
        })?;
    let mut successor_set = HashSet::new();
    successor_set
        .try_reserve(terminator.edge_count())
        .map_err(|_| {
            ProductionRankedProjectionErrorV1::Unsupported(
                "deterministic scalar successor set cannot be reserved",
            )
        })?;
    terminator.try_for_each_edge::<ProductionRankedProjectionErrorV1>(|edge| {
        let successor = edge.target().index() as usize;
        if successor >= function.blocks().len() {
            return Err(ProductionRankedProjectionErrorV1::Unsupported(
                "a deterministic scalar control edge is outside the semantic CFG",
            ));
        }
        if successor_set.insert(successor) {
            successors.push(successor);
        }
        Ok(())
    })?;
    Ok(successors)
}

struct DeterministicScalarProjectorV1<'a> {
    types: &'a [SemanticTypeDeclV1],
    callables: &'a [SemanticCallableDeclV1],
    callable_effects: &'a DefinedCallableEmptyEffectSummariesV1,
    function: &'a SemanticFunctionDeclV1,
    constants: &'a [Option<u64>],
    local_definitions: &'a [u8],
    index_values: &'a [Option<ProjectedDisjointIndexV1>],
    local_allocations: &'a [Option<AllocationContractV1>],
    switch_predicates: &'a [Option<GuardPredicateV1>],
    argument_slots: &'a mut [Option<u32>],
    next_argument: &'a mut usize,
    operations: &'a mut Vec<ProductionRankedOperationV1>,
    next_value: &'a mut u32,
    definitions: Vec<Vec<DeterministicScalarDefinitionV1>>,
    states: Vec<u8>,
    summaries: Vec<Option<DeterministicScalarSummaryV1>>,
    ranked_constants: HashMap<u64, ProductionRankedValueV1>,
    launch_context_arguments: [Option<u32>; 6],
    reachability: DeterministicControlReachabilityV1,
    guarded_divisor_proofs: Option<SemanticAssertProofsV1<'a>>,
}

impl<'a> DeterministicScalarProjectorV1<'a> {
    #[allow(clippy::too_many_arguments)]
    fn new(
        types: &'a [SemanticTypeDeclV1],
        callables: &'a [SemanticCallableDeclV1],
        callable_effects: &'a DefinedCallableEmptyEffectSummariesV1,
        function: &'a SemanticFunctionDeclV1,
        constants: &'a [Option<u64>],
        local_definitions: &'a [u8],
        index_values: &'a [Option<ProjectedDisjointIndexV1>],
        local_allocations: &'a [Option<AllocationContractV1>],
        switch_predicates: &'a [Option<GuardPredicateV1>],
        argument_slots: &'a mut [Option<u32>],
        next_argument: &'a mut usize,
        operations: &'a mut Vec<ProductionRankedOperationV1>,
        next_value: &'a mut u32,
    ) -> Result<Self, ProductionRankedProjectionErrorV1> {
        let local_count = function.locals().len();
        if constants.len() != local_count
            || local_definitions.len() != local_count
            || index_values.len() != local_count
            || local_allocations.len() != local_count
            || switch_predicates.len() != local_count
            || argument_slots.len() != local_count
        {
            return Err(ProductionRankedProjectionErrorV1::Unsupported(
                "deterministic scalar projection tables do not match the semantic local table",
            ));
        }
        let mut definitions = vec![Vec::new(); local_count];
        for (block_index, block) in function.blocks().iter().enumerate() {
            for (statement_index, statement) in block.statements().iter().enumerate() {
                let SemanticStatementKindV1::Assign(assignment) = statement.kind() else {
                    continue;
                };
                if !assignment.destination().projections().is_empty() {
                    continue;
                }
                let local = assignment.destination().local().index() as usize;
                let Some(slot) = definitions.get_mut(local) else {
                    return Err(ProductionRankedProjectionErrorV1::Unsupported(
                        "a deterministic scalar assignment is outside the semantic local table",
                    ));
                };
                slot.try_reserve(1).map_err(|_| {
                    ProductionRankedProjectionErrorV1::Unsupported(
                        "deterministic scalar definition storage cannot be reserved",
                    )
                })?;
                slot.push(DeterministicScalarDefinitionV1::Assignment {
                    block: block_index,
                    statement: statement_index,
                });
            }
            if let SemanticTerminatorKindV1::Call(call) = block.terminator().kind()
                && let Some(destination) = call.destination()
                && destination.place().projections().is_empty()
            {
                let local = destination.place().local().index() as usize;
                let Some(slot) = definitions.get_mut(local) else {
                    return Err(ProductionRankedProjectionErrorV1::Unsupported(
                        "a deterministic scalar call destination is outside the semantic local table",
                    ));
                };
                slot.try_reserve(1).map_err(|_| {
                    ProductionRankedProjectionErrorV1::Unsupported(
                        "deterministic scalar definition storage cannot be reserved",
                    )
                })?;
                slot.push(DeterministicScalarDefinitionV1::Call { block: block_index });
            }
        }
        Ok(Self {
            types,
            callables,
            callable_effects,
            function,
            constants,
            local_definitions,
            index_values,
            local_allocations,
            switch_predicates,
            argument_slots,
            next_argument,
            operations,
            next_value,
            definitions,
            states: vec![0; local_count],
            summaries: vec![None; local_count],
            ranked_constants: HashMap::new(),
            launch_context_arguments: [None; 6],
            reachability: DeterministicControlReachabilityV1::new(function.blocks().len())?,
            guarded_divisor_proofs: None,
        })
    }

    fn resolve_operand(
        &mut self,
        operand: &SemanticOperandV1,
    ) -> Result<Option<DeterministicScalarSummaryV1>, ProductionRankedProjectionErrorV1> {
        match operand {
            SemanticOperandV1::Constant(constant) => match constant.value() {
                SemanticConstantValueV1::Scalar(value) => Ok(u64::try_from(value.bits())
                    .ok()
                    .map(DeterministicScalarSummaryV1::Constant)),
                _ => Ok(None),
            },
            SemanticOperandV1::Copy(place) | SemanticOperandV1::Move(place) => {
                self.resolve_place(place, place.projections().is_empty())
            }
        }
    }

    fn resolve_place(
        &mut self,
        place: &SemanticPlaceV1,
        preserve_exact: bool,
    ) -> Result<Option<DeterministicScalarSummaryV1>, ProductionRankedProjectionErrorV1> {
        if transparent_place(place).is_none() {
            return Ok(None);
        }
        let summary = self.resolve_local(place.local().index() as usize)?;
        if preserve_exact {
            Ok(summary)
        } else {
            self.derive([summary])
        }
    }

    fn resolve_local(
        &mut self,
        local: usize,
    ) -> Result<Option<DeterministicScalarSummaryV1>, ProductionRankedProjectionErrorV1> {
        let Some(state) = self.states.get(local).copied() else {
            return Err(ProductionRankedProjectionErrorV1::Unsupported(
                "a deterministic scalar dependency is outside the semantic local table",
            ));
        };
        if state == 2 {
            return Ok(self.summaries[local].clone());
        }
        if state == 1 {
            return Ok(None);
        }
        self.states[local] = 1;
        let summary = if let Some(index) = self.index_values[local] {
            Some(DeterministicScalarSummaryV1::Exact(index.value))
        } else if let Some(value) = self.constants[local] {
            Some(DeterministicScalarSummaryV1::Constant(value))
        } else if self.local_definitions[local] == 0 {
            match self.function.locals()[local].role() {
                SemanticLocalRoleV1::Argument(argument) => Some(
                    DeterministicScalarSummaryV1::Exact(self.ranked_argument(argument as usize)?),
                ),
                SemanticLocalRoleV1::Return
                | SemanticLocalRoleV1::Temporary
                | SemanticLocalRoleV1::RustCallTupleField { .. } => None,
            }
        } else if self.definitions[local].len() != usize::from(self.local_definitions[local]) {
            None
        } else {
            let mut candidates = Vec::new();
            candidates
                .try_reserve(self.definitions[local].len())
                .map_err(|_| {
                    ProductionRankedProjectionErrorV1::Unsupported(
                        "deterministic scalar definition meet storage cannot be reserved",
                    )
                })?;
            for definition_index in 0..self.definitions[local].len() {
                let definition = self.definitions[local][definition_index];
                let Some(candidate) = self.resolve_definition(definition)? else {
                    candidates.clear();
                    break;
                };
                candidates.push(candidate);
            }
            if candidates.is_empty() {
                None
            } else if candidates.windows(2).all(|pair| pair[0] == pair[1])
                || self.definitions[local]
                    .windows(2)
                    .all(|pair| self.definition_semantics_equal(pair[0], pair[1]))
            {
                candidates.into_iter().next()
            } else {
                self.merge_control_selected_definitions(local, candidates)?
            }
        };
        self.states[local] = 2;
        self.summaries[local] = summary.clone();
        Ok(summary)
    }

    fn resolve_definition(
        &mut self,
        definition: DeterministicScalarDefinitionV1,
    ) -> Result<Option<DeterministicScalarSummaryV1>, ProductionRankedProjectionErrorV1> {
        match definition {
            DeterministicScalarDefinitionV1::Assignment { block, statement } => {
                let source = self.function.blocks()[block].statements()[statement].source();
                let value = self.function.blocks()[block].statements()[statement]
                    .kind()
                    .clone();
                let SemanticStatementKindV1::Assign(assignment) = value else {
                    unreachable!("indexed deterministic assignment changed kind")
                };
                self.resolve_rvalue(
                    assignment.value().kind().clone(),
                    assignment.value().result_type(),
                    ScalarAssignmentSiteV1 { block, statement },
                )
                .map_err(|error| {
                    error.with_deterministic_assignment_context(
                        block,
                        statement,
                        assignment.destination().local().index(),
                        source,
                    )
                })
            }
            DeterministicScalarDefinitionV1::Call { block } => {
                let terminator = self.function.blocks()[block].terminator().kind().clone();
                let SemanticTerminatorKindV1::Call(call) = terminator else {
                    unreachable!("indexed deterministic call changed kind")
                };
                self.resolve_call(&call)
            }
        }
    }

    fn merge_control_selected_definitions(
        &mut self,
        local: usize,
        candidates: Vec<DeterministicScalarSummaryV1>,
    ) -> Result<Option<DeterministicScalarSummaryV1>, ProductionRankedProjectionErrorV1> {
        if self.definitions[local]
            .windows(2)
            .any(|pair| Self::definition_block(pair[0]) == Self::definition_block(pair[1]))
        {
            return Ok(None);
        }
        let mut inputs = Vec::new();
        inputs.try_reserve(candidates.len()).map_err(|_| {
            ProductionRankedProjectionErrorV1::Unsupported(
                "deterministic scalar control meet storage cannot be reserved",
            )
        })?;
        inputs.extend(candidates.into_iter().map(Some));
        let mut observed_selector = false;
        for definition_index in 0..self.definitions[local].len() {
            let definition_block =
                Self::definition_block(self.definitions[local][definition_index]);
            let Some(controls) = self.definition_control_summaries(definition_block)? else {
                return Ok(None);
            };
            observed_selector |= !controls.is_empty();
            inputs.try_reserve(controls.len()).map_err(|_| {
                ProductionRankedProjectionErrorV1::Unsupported(
                    "deterministic scalar control meet storage cannot be reserved",
                )
            })?;
            inputs.extend(controls.into_iter().map(Some));
        }
        if !observed_selector {
            return Ok(None);
        }
        self.derive(inputs)
    }

    const fn definition_block(definition: DeterministicScalarDefinitionV1) -> usize {
        match definition {
            DeterministicScalarDefinitionV1::Assignment { block, .. }
            | DeterministicScalarDefinitionV1::Call { block } => block,
        }
    }

    fn definition_semantics_equal(
        &self,
        left: DeterministicScalarDefinitionV1,
        right: DeterministicScalarDefinitionV1,
    ) -> bool {
        match (left, right) {
            (
                DeterministicScalarDefinitionV1::Assignment {
                    block: left_block,
                    statement: left_statement,
                },
                DeterministicScalarDefinitionV1::Assignment {
                    block: right_block,
                    statement: right_statement,
                },
            ) => {
                let left = self.function.blocks()[left_block].statements()[left_statement].kind();
                let right =
                    self.function.blocks()[right_block].statements()[right_statement].kind();
                let (SemanticStatementKindV1::Assign(left), SemanticStatementKindV1::Assign(right)) =
                    (left, right)
                else {
                    unreachable!("indexed deterministic assignments changed kind")
                };
                left.value() == right.value()
            }
            (
                DeterministicScalarDefinitionV1::Call { block: left },
                DeterministicScalarDefinitionV1::Call { block: right },
            ) => {
                let left = self.function.blocks()[left].terminator().kind();
                let right = self.function.blocks()[right].terminator().kind();
                let (SemanticTerminatorKindV1::Call(left), SemanticTerminatorKindV1::Call(right)) =
                    (left, right)
                else {
                    unreachable!("indexed deterministic calls changed kind")
                };
                left.callee() == right.callee()
                    && left.arguments() == right.arguments()
                    && left.variadic_argument_abis() == right.variadic_argument_abis()
                    && left.unwind() == right.unwind()
            }
            _ => false,
        }
    }

    fn definition_control_summaries(
        &mut self,
        definition_block: usize,
    ) -> Result<Option<Vec<DeterministicScalarSummaryV1>>, ProductionRankedProjectionErrorV1> {
        let mut controls = Vec::new();
        for block_index in 0..self.function.blocks().len() {
            let terminator = self.function.blocks()[block_index]
                .terminator()
                .kind()
                .clone();
            let successors = self.control_successors(&terminator)?;
            if successors.len() < 2 {
                continue;
            }
            let mut reaches = 0_usize;
            for successor in successors.iter().copied() {
                reaches += usize::from(self.block_can_reach(successor, definition_block)?);
            }
            if reaches == 0 || reaches == successors.len() {
                continue;
            }
            let SemanticTerminatorKindV1::SwitchInt { discriminant, .. } = &terminator else {
                return Ok(None);
            };
            let Some(control) = self.resolve_operand(discriminant)? else {
                return Ok(None);
            };
            controls.try_reserve(1).map_err(|_| {
                ProductionRankedProjectionErrorV1::Unsupported(
                    "deterministic scalar selector storage cannot be reserved",
                )
            })?;
            controls.push(control);
        }
        Ok(Some(controls))
    }

    fn control_successors(
        &self,
        terminator: &SemanticTerminatorKindV1,
    ) -> Result<Vec<usize>, ProductionRankedProjectionErrorV1> {
        deterministic_control_successors_v1(self.function, self.switch_predicates, terminator)
    }

    fn block_can_reach(
        &mut self,
        start: usize,
        target: usize,
    ) -> Result<bool, ProductionRankedProjectionErrorV1> {
        let block_count = self.function.blocks().len();
        if start >= block_count || target >= block_count {
            return Err(ProductionRankedProjectionErrorV1::Unsupported(
                "a deterministic scalar reachability query is outside the semantic CFG",
            ));
        }
        if self.reachability.predecessors.is_none() {
            self.reachability
                .install_function_successors(self.function, self.switch_predicates)?;
        }
        self.reachability.block_can_reach(start, target)
    }

    fn resolve_rvalue(
        &mut self,
        rvalue: SemanticRvalueKindV1,
        result_type: SemanticTypeIdV1,
        site: ScalarAssignmentSiteV1,
    ) -> Result<Option<DeterministicScalarSummaryV1>, ProductionRankedProjectionErrorV1> {
        match rvalue {
            SemanticRvalueKindV1::Use(operand) => self.resolve_operand(&operand),
            SemanticRvalueKindV1::Unary { operand, .. }
            | SemanticRvalueKindV1::Cast { operand, .. } => {
                let summary = self.resolve_operand(&operand)?;
                self.derive([summary])
            }
            SemanticRvalueKindV1::Binary {
                operation,
                left,
                right,
            } => self.resolve_binary(operation, &left, &right, result_type, site),
            SemanticRvalueKindV1::CheckedBinary(checked) => {
                let left = self.resolve_operand(checked.left())?;
                let right = self.resolve_operand(checked.right())?;
                self.derive([left, right])
            }
            // Unlike ordinary MIR arithmetic guarded by explicit control, this
            // operation carries a precondition not represented in the rvalue.
            SemanticRvalueKindV1::UncheckedBinary(_) => Ok(None),
            SemanticRvalueKindV1::Aggregate(aggregate) => {
                if let SemanticAggregateKindV1::EnumVariant(variant) = aggregate.kind() {
                    return Ok(Some(DeterministicScalarSummaryV1::Constant(u64::from(
                        *variant,
                    ))));
                }
                let mut inputs = Vec::new();
                inputs
                    .try_reserve(aggregate.operands().len())
                    .map_err(|_| {
                        ProductionRankedProjectionErrorV1::Unsupported(
                            "deterministic scalar aggregate dependency storage cannot be reserved",
                        )
                    })?;
                for operand in aggregate.operands() {
                    inputs.push(self.resolve_operand(operand)?);
                }
                self.derive(inputs)
            }
            SemanticRvalueKindV1::Length(place) => self.resolve_place(&place, false),
            // Private addresses may differ per invocation even when the
            // referenced value is uniform. Address-space provenance must be
            // established before either rvalue can become a control summary.
            SemanticRvalueKindV1::Borrow { place, .. }
            | SemanticRvalueKindV1::AddressOf { place, .. } => {
                let local = place.local().index() as usize;
                if self
                    .local_allocations
                    .get(local)
                    .copied()
                    .flatten()
                    .is_none()
                {
                    return Ok(None);
                }
                let summary = self.resolve_place(&place, true)?;
                self.derive([summary])
            }
            SemanticRvalueKindV1::Discriminant(place) => {
                let summary = self.resolve_place(&place, true)?;
                match summary {
                    Some(DeterministicScalarSummaryV1::Constant(value)) => {
                        Ok(Some(DeterministicScalarSummaryV1::Constant(value)))
                    }
                    summary => self.derive([summary]),
                }
            }
            // A load may depend on mutable memory that is not represented by
            // its address. It can never be summarized as deterministic control.
            SemanticRvalueKindV1::Load(_) => Ok(None),
        }
    }

    fn resolve_call(
        &mut self,
        call: &SemanticDirectCallV1,
    ) -> Result<Option<DeterministicScalarSummaryV1>, ProductionRankedProjectionErrorV1> {
        if matches!(call.unwind(), SemanticUnwindActionV1::Cleanup(_)) {
            return Ok(None);
        }
        let Some(callable) = self.callables.get(call.callee().index() as usize) else {
            return Ok(None);
        };
        if let SemanticCallableDeclV1::Defined { function } = callable {
            if !self
                .callable_effects
                .is_exact_empty_deterministic_scalar(*function)
            {
                return Ok(None);
            }
            return self.resolve_explicit_call_dependencies_v1(call);
        }
        let SemanticCallableDeclV1::CompilerIntrinsic {
            binding, operation, ..
        } = callable
        else {
            return Ok(None);
        };
        let geometry_slot = match operation {
            SemanticCompilerIntrinsicOperationV1::WorkgroupDimension(axis) => Some((0, axis)),
            SemanticCompilerIntrinsicOperationV1::GridDimension(axis) => Some((3, axis)),
            _ => None,
        };
        if let Some((kind, axis)) = geometry_slot {
            let Some(destination) = call.destination() else {
                return Ok(None);
            };
            let abi = binding.abi();
            let result = abi.return_value();
            let ty = result.source_ty();
            if !call.arguments().is_empty()
                || abi.c_variadic()
                || !abi.arguments().is_empty()
                || !abi.hidden_arguments().is_empty()
                || !abi.source_input_types().is_empty()
                || !abi.source_argument_ownership().is_empty()
                || abi.source_output_type() != ty
                || result.adjusted().is_some()
                || result.pointee_override().is_some()
                || !matches!(result.mode(), SemanticAbiPassModeV1::Direct(_))
                || destination.place().ty() != ty
                || !destination.place().projections().is_empty()
                || self
                    .function
                    .locals()
                    .get(destination.place().local().index() as usize)
                    .is_none_or(|local| local.ty() != ty)
                || !matches!(
                    self.types
                        .get(ty.index() as usize)
                        .map(SemanticTypeDeclV1::shape),
                    Some(SemanticTypeShapeV1::Scalar(SemanticScalarTypeV1::Integer {
                        signed: false,
                        bits: 32,
                    }))
                )
            {
                return Ok(None);
            }
            let axis = match axis {
                SemanticAxisV1::X => 0,
                SemanticAxisV1::Y => 1,
                SemanticAxisV1::Z => 2,
            };
            let value = self.launch_context_argument(kind + axis)?;
            return Ok(Some(DeterministicScalarSummaryV1::Exact(value)));
        }
        if matches!(
            operation,
            SemanticCompilerIntrinsicOperationV1::ThreadIndexGet { .. }
                | SemanticCompilerIntrinsicOperationV1::DisjointIndexGet { .. }
        ) {
            let [argument] = call.arguments() else {
                return Ok(None);
            };
            return Ok(match self.resolve_operand(argument)? {
                Some(DeterministicScalarSummaryV1::Derived(values)) if values.len() == 1 => {
                    Some(DeterministicScalarSummaryV1::Exact(values[0]))
                }
                summary @ Some(
                    DeterministicScalarSummaryV1::Constant(_)
                    | DeterministicScalarSummaryV1::Exact(_),
                ) => summary,
                Some(DeterministicScalarSummaryV1::Derived(_)) | None => None,
            });
        }
        if !compiler_intrinsic_is_pure_total_scalar_dependency_v1(operation) {
            return Ok(None);
        }
        self.resolve_explicit_call_dependencies_v1(call)
    }

    fn resolve_explicit_call_dependencies_v1(
        &mut self,
        call: &SemanticDirectCallV1,
    ) -> Result<Option<DeterministicScalarSummaryV1>, ProductionRankedProjectionErrorV1> {
        let mut inputs = Vec::new();
        inputs.try_reserve(call.arguments().len()).map_err(|_| {
            ProductionRankedProjectionErrorV1::Unsupported(
                "deterministic scalar call dependency storage cannot be reserved",
            )
        })?;
        for argument in call.arguments() {
            inputs.push(self.resolve_operand(argument)?);
        }
        self.derive(inputs)
    }

    fn resolve_binary(
        &mut self,
        operation: SemanticBinaryOpV1,
        left_operand: &SemanticOperandV1,
        right_operand: &SemanticOperandV1,
        result_type: SemanticTypeIdV1,
        site: ScalarAssignmentSiteV1,
    ) -> Result<Option<DeterministicScalarSummaryV1>, ProductionRankedProjectionErrorV1> {
        let left = self.resolve_operand(left_operand)?;
        let right = self.resolve_operand(right_operand)?;
        let Some(kind) = deterministic_index_binary_kind_v1(operation) else {
            return self.derive([left, right]);
        };
        let (Some(left), Some(right)) = (left, right) else {
            return Ok(None);
        };
        if matches!(
            kind,
            IndexBinaryKindAttr::Divide | IndexBinaryKindAttr::Remainder
        ) && !matches!(right, DeterministicScalarSummaryV1::Constant(value) if value != 0)
        {
            if self.guarded_divisor_is_total_v1(
                site,
                result_type,
                operation,
                left_operand,
                right_operand,
            )? {
                // A total extension outside the guarded source path preserves
                // dependence, not a numeric value or an entry-level division.
                return self.derive([Some(left), Some(right)]);
            }
            // Diagnostic allocation is fixed-size and only occurs on the
            // existing rejection path; it carries no proof or authority.
            return Err(
                ProductionRankedProjectionErrorV1::UnprovenDeterministicDivisor(Box::new(
                    DeterministicDivisorDiagnosticV1 {
                        root: None,
                        site: None,
                        operation,
                        left: DeterministicProjectionOperandDiagnosticV1::new(left_operand),
                        right: DeterministicProjectionOperandDiagnosticV1::new(right_operand),
                        summary: match right {
                            DeterministicScalarSummaryV1::Constant(_) => {
                                DeterministicDivisorSummaryDiagnosticV1::ConstantZero
                            }
                            DeterministicScalarSummaryV1::Exact(_) => {
                                DeterministicDivisorSummaryDiagnosticV1::Exact
                            }
                            DeterministicScalarSummaryV1::Derived(_) => {
                                DeterministicDivisorSummaryDiagnosticV1::Derived
                            }
                        },
                    },
                )),
            );
        }
        let lhs = self.materialize(left)?;
        let rhs = self.materialize(right)?;
        reserve_operation(self.operations)?;
        let result = next_value_id(self.next_value)?;
        self.operations
            .push(ProductionRankedOperationV1::IndexBinary {
                result,
                kind,
                lhs,
                rhs,
            });
        Ok(Some(DeterministicScalarSummaryV1::Exact(
            ProductionRankedValueV1::Local(result),
        )))
    }

    fn derive(
        &mut self,
        inputs: impl IntoIterator<Item = Option<DeterministicScalarSummaryV1>>,
    ) -> Result<Option<DeterministicScalarSummaryV1>, ProductionRankedProjectionErrorV1> {
        let mut dependencies = Vec::new();
        for input in inputs {
            let Some(input) = input else {
                return Ok(None);
            };
            let values = match input {
                DeterministicScalarSummaryV1::Constant(value) => {
                    let value = self.ranked_constant(value)?;
                    Self::retain_dependency(&mut dependencies, value)?;
                    continue;
                }
                DeterministicScalarSummaryV1::Exact(value) => {
                    Self::retain_dependency(&mut dependencies, value)?;
                    continue;
                }
                DeterministicScalarSummaryV1::Derived(values) => values,
            };
            for value in values {
                Self::retain_dependency(&mut dependencies, value)?;
            }
        }
        Ok((!dependencies.is_empty())
            .then_some(DeterministicScalarSummaryV1::Derived(dependencies)))
    }

    fn retain_dependency(
        dependencies: &mut Vec<ProductionRankedValueV1>,
        value: ProductionRankedValueV1,
    ) -> Result<(), ProductionRankedProjectionErrorV1> {
        if let Err(index) = dependencies.binary_search(&value) {
            dependencies.try_reserve(1).map_err(|_| {
                ProductionRankedProjectionErrorV1::Unsupported(
                    "deterministic scalar dependency storage cannot be reserved",
                )
            })?;
            dependencies.insert(index, value);
            if dependencies.len() > MAX_DETERMINISTIC_JOIN_INPUTS_V1 {
                return Err(ProductionRankedProjectionErrorV1::Unsupported(
                    "a deterministic scalar expression exceeds the explicit dependency limit",
                ));
            }
        }
        Ok(())
    }

    fn materialize(
        &mut self,
        summary: DeterministicScalarSummaryV1,
    ) -> Result<ProductionRankedValueV1, ProductionRankedProjectionErrorV1> {
        match summary {
            DeterministicScalarSummaryV1::Constant(value) => self.ranked_constant(value),
            DeterministicScalarSummaryV1::Exact(value) => Ok(value),
            DeterministicScalarSummaryV1::Derived(dependencies) => {
                if !(1..=MAX_DETERMINISTIC_JOIN_INPUTS_V1).contains(&dependencies.len()) {
                    return Err(ProductionRankedProjectionErrorV1::Unsupported(
                        "a deterministic scalar summary has missing or excessive dependencies",
                    ));
                }
                reserve_operation(self.operations)?;
                let result = next_value_id(self.next_value)?;
                self.operations
                    .push(ProductionRankedOperationV1::DeterministicJoin {
                        result,
                        dependencies,
                    });
                Ok(ProductionRankedValueV1::Local(result))
            }
        }
    }

    fn ranked_constant(
        &mut self,
        value: u64,
    ) -> Result<ProductionRankedValueV1, ProductionRankedProjectionErrorV1> {
        if let Some(value) = self.ranked_constants.get(&value).copied() {
            return Ok(value);
        }
        self.ranked_constants.try_reserve(1).map_err(|_| {
            ProductionRankedProjectionErrorV1::Unsupported(
                "deterministic scalar constant cache cannot be reserved",
            )
        })?;
        reserve_operation(self.operations)?;
        let result = next_value_id(self.next_value)?;
        let ranked = ProductionRankedValueV1::Local(result);
        self.operations
            .push(ProductionRankedOperationV1::IndexConstant { result, value });
        self.ranked_constants.insert(value, ranked);
        Ok(ranked)
    }

    fn launch_context_argument(
        &mut self,
        slot: usize,
    ) -> Result<ProductionRankedValueV1, ProductionRankedProjectionErrorV1> {
        if let Some(argument) = self.launch_context_arguments[slot] {
            return Ok(ProductionRankedValueV1::Argument(argument));
        }
        if *self.next_argument >= HARD_MAX_PRODUCTION_RANKED_ARGUMENTS {
            return Err(ProductionRankedProjectionErrorV1::Unsupported(
                "launch-context ranked argument count exceeds the ranked kernel limit",
            ));
        }
        let argument = u32::try_from(*self.next_argument).map_err(|_| {
            ProductionRankedProjectionErrorV1::Unsupported(
                "too many launch-context ranked arguments",
            )
        })?;
        // At most six cache misses scan this already admitted local table.
        if self
            .argument_slots
            .iter()
            .chain(self.launch_context_arguments.iter())
            .flatten()
            .any(|existing| *existing >= argument)
        {
            return Err(ProductionRankedProjectionErrorV1::Unsupported(
                "launch-context ranked argument collides with an existing argument",
            ));
        }
        let next = self.next_argument.checked_add(1).ok_or(
            ProductionRankedProjectionErrorV1::Unsupported(
                "launch-context ranked argument count overflow",
            ),
        )?;
        // These unconstrained analysis parameters describe implicit launch context,
        // not new kernel ABI inputs or pure functions of explicit call arguments.
        self.launch_context_arguments[slot] = Some(argument);
        *self.next_argument = next;
        Ok(ProductionRankedValueV1::Argument(argument))
    }

    fn ranked_argument(
        &mut self,
        origin: usize,
    ) -> Result<ProductionRankedValueV1, ProductionRankedProjectionErrorV1> {
        let slot = self.argument_slots.get_mut(origin).ok_or(
            ProductionRankedProjectionErrorV1::Unsupported(
                "a deterministic scalar argument origin is outside the semantic local table",
            ),
        )?;
        let argument = match *slot {
            Some(argument) => argument,
            None => {
                let argument = u32::try_from(*self.next_argument).map_err(|_| {
                    ProductionRankedProjectionErrorV1::Unsupported(
                        "too many deterministic scalar ranked arguments",
                    )
                })?;
                *self.next_argument = self.next_argument.checked_add(1).ok_or(
                    ProductionRankedProjectionErrorV1::Unsupported(
                        "deterministic scalar ranked argument count overflow",
                    ),
                )?;
                *slot = Some(argument);
                argument
            }
        };
        Ok(ProductionRankedValueV1::Argument(argument))
    }
}

fn compiler_intrinsic_is_pure_total_scalar_dependency_v1(
    operation: &SemanticCompilerIntrinsicOperationV1,
) -> bool {
    matches!(
        operation,
        SemanticCompilerIntrinsicOperationV1::FabsF32
            | SemanticCompilerIntrinsicOperationV1::SaturatingInteger(_)
            | SemanticCompilerIntrinsicOperationV1::MathF32 { .. }
            | SemanticCompilerIntrinsicOperationV1::Bf16Conversion { .. }
            | SemanticCompilerIntrinsicOperationV1::Bf16MatrixViewRowMajor { .. }
            | SemanticCompilerIntrinsicOperationV1::Bf16MatrixViewColumnMajor { .. }
            | SemanticCompilerIntrinsicOperationV1::Gfx950Fp4MatrixViewRowMajor { .. }
            | SemanticCompilerIntrinsicOperationV1::Gfx950Fp8MatrixViewRowMajor { .. }
            | SemanticCompilerIntrinsicOperationV1::StridedReadView2DFromSharedSlice { .. }
            | SemanticCompilerIntrinsicOperationV1::ThreadIndexIntoDisjoint { .. }
            | SemanticCompilerIntrinsicOperationV1::ThreadIndexCheckedShift { .. }
            | SemanticCompilerIntrinsicOperationV1::ThreadIndexCheckedBlock { .. }
            | SemanticCompilerIntrinsicOperationV1::ThreadIndexCheckedTiled2d { .. }
            | SemanticCompilerIntrinsicOperationV1::ThreadIndexCheckedRowStriped2d { .. }
            | SemanticCompilerIntrinsicOperationV1::ThreadIndexGet { .. }
            | SemanticCompilerIntrinsicOperationV1::DisjointIndexGet { .. }
            | SemanticCompilerIntrinsicOperationV1::DisjointIndexCheckedShift { .. }
            | SemanticCompilerIntrinsicOperationV1::DisjointSliceLen { .. }
            | SemanticCompilerIntrinsicOperationV1::WriteOnlyDisjointSliceLen { .. }
    )
}

include!("production_ranked_projection_v1/guarded_opaque_divisor_v1.rs");

const fn deterministic_index_binary_kind_v1(
    operation: SemanticBinaryOpV1,
) -> Option<IndexBinaryKindAttr> {
    match operation {
        SemanticBinaryOpV1::Add => Some(IndexBinaryKindAttr::Add),
        SemanticBinaryOpV1::Multiply => Some(IndexBinaryKindAttr::Multiply),
        SemanticBinaryOpV1::Divide => Some(IndexBinaryKindAttr::Divide),
        SemanticBinaryOpV1::Remainder => Some(IndexBinaryKindAttr::Remainder),
        SemanticBinaryOpV1::Subtract
        | SemanticBinaryOpV1::Offset
        | SemanticBinaryOpV1::BitXor
        | SemanticBinaryOpV1::BitAnd
        | SemanticBinaryOpV1::BitOr
        | SemanticBinaryOpV1::ShiftLeft
        | SemanticBinaryOpV1::ShiftRight
        | SemanticBinaryOpV1::Equal
        | SemanticBinaryOpV1::LessThan
        | SemanticBinaryOpV1::LessOrEqual
        | SemanticBinaryOpV1::NotEqual
        | SemanticBinaryOpV1::GreaterOrEqual
        | SemanticBinaryOpV1::GreaterThan => None,
    }
}

fn authenticated_switch_targets_exhaust_domain_v1(
    types: &[SemanticTypeDeclV1],
    function: &SemanticFunctionDeclV1,
    discriminant: &SemanticOperandV1,
    targets: &SemanticSwitchTargetsV1,
    local_definitions: &[u8],
) -> bool {
    let explicit_values = targets
        .values()
        .iter()
        .map(|target| target.value())
        .collect::<Vec<_>>();
    let Some(discriminant_type) = types.get(discriminant.ty().index() as usize) else {
        return false;
    };
    if matches!(
        discriminant_type.shape(),
        SemanticTypeShapeV1::Scalar(SemanticScalarTypeV1::Bool)
    ) {
        return explicit_values.len() == 2
            && explicit_values.contains(&0)
            && explicit_values.contains(&1);
    }

    let Some(discriminant_local) = simple_operand_local(discriminant) else {
        return false;
    };
    if local_definitions
        .get(discriminant_local.index() as usize)
        .copied()
        != Some(1)
    {
        return false;
    }
    let mut source_type = None;
    for block in function.blocks() {
        for statement in block.statements() {
            let SemanticStatementKindV1::Assign(assignment) = statement.kind() else {
                continue;
            };
            if !assignment.destination().projections().is_empty()
                || assignment.destination().local() != discriminant_local
                || assignment.destination().ty() != discriminant.ty()
            {
                continue;
            }
            let SemanticRvalueKindV1::Discriminant(source) = assignment.value().kind() else {
                return false;
            };
            if !source.projections().is_empty() {
                return false;
            }
            source_type = Some(source.ty());
        }
    }
    let Some(source_type) = source_type.and_then(|source| types.get(source.index() as usize))
    else {
        return false;
    };
    let SemanticTypeShapeV1::Enum { variants, .. } = source_type.shape() else {
        return false;
    };
    let inhabited = variants
        .iter()
        .filter(|variant| !variant.is_uninhabited())
        .collect::<Vec<_>>();
    inhabited.len() == explicit_values.len()
        && !inhabited.is_empty()
        && inhabited.iter().all(|variant| {
            explicit_values
                .iter()
                .any(|value| *value == variant.discriminant())
        })
}

#[allow(clippy::too_many_arguments)]
fn project_deterministic_scalar_switches_v1(
    types: &[SemanticTypeDeclV1],
    callables: &[SemanticCallableDeclV1],
    callable_effects: &DefinedCallableEmptyEffectSummariesV1,
    function: &SemanticFunctionDeclV1,
    constants: &[Option<u64>],
    local_definitions: &[u8],
    stable_argument_origins: &[Option<u32>],
    index_values: &[Option<ProjectedDisjointIndexV1>],
    local_allocations: &[Option<AllocationContractV1>],
    predicates: &[Option<GuardPredicateV1>],
    argument_slots: &mut [Option<u32>],
    next_argument: &mut usize,
    operations: &mut Vec<ProductionRankedOperationV1>,
    next_value: &mut u32,
) -> Result<Vec<Option<ProjectedDeterministicSwitchV1>>, ProductionRankedProjectionErrorV1> {
    if predicates.len() != function.locals().len() {
        return Err(ProductionRankedProjectionErrorV1::Unsupported(
            "deterministic scalar predicates do not match the semantic local table",
        ));
    }
    if stable_argument_origins.len() != function.locals().len() {
        return Err(ProductionRankedProjectionErrorV1::Unsupported(
            "deterministic scalar uniformity does not match the semantic local table",
        ));
    }
    let mut projector = DeterministicScalarProjectorV1::new(
        types,
        callables,
        callable_effects,
        function,
        constants,
        local_definitions,
        index_values,
        local_allocations,
        predicates,
        argument_slots,
        next_argument,
        operations,
        next_value,
    )?;
    let mut switches = vec![None; function.blocks().len()];
    for (block_index, block) in function.blocks().iter().enumerate() {
        let SemanticTerminatorKindV1::SwitchInt {
            discriminant,
            targets,
        } = block.terminator().kind()
        else {
            continue;
        };
        if simple_operand_local(discriminant).is_some_and(|local| {
            predicates
                .get(local.index() as usize)
                .is_some_and(Option::is_some)
        }) {
            continue;
        }
        let source_discriminant = discriminant.clone();
        let lane_uniform = constant_operand_value(discriminant, constants).is_some()
            || simple_operand_local(discriminant).is_some_and(|local| {
                stable_argument_origins
                    .get(local.index() as usize)
                    .copied()
                    .flatten()
                    .is_some()
            });
        let Some(summary) = projector.resolve_operand(discriminant)? else {
            continue;
        };
        let exhausts_valid_domain = authenticated_switch_targets_exhaust_domain_v1(
            types,
            function,
            discriminant,
            targets,
            local_definitions,
        );
        let discriminant = projector.materialize(summary)?;
        let mut projected_targets = Vec::new();
        projected_targets
            .try_reserve(targets.values().len())
            .map_err(|_| {
                ProductionRankedProjectionErrorV1::Unsupported(
                    "deterministic scalar switch target storage cannot be reserved",
                )
            })?;
        for target in targets.values() {
            let value = u64::try_from(target.value()).map_err(|_| {
                ProductionRankedProjectionErrorV1::Incomplete(
                    "a deterministic scalar switch variant does not fit ranked index width",
                )
            })?;
            let target_block = target.edge().target().index() as usize;
            if target_block >= function.blocks().len() {
                return Err(ProductionRankedProjectionErrorV1::Unsupported(
                    "a deterministic scalar switch target is outside the semantic CFG",
                ));
            }
            projected_targets.push((
                target.value(),
                projector.ranked_constant(value)?,
                target_block,
            ));
        }
        let mut otherwise = targets.otherwise().target().index() as usize;
        if otherwise >= function.blocks().len() {
            return Err(ProductionRankedProjectionErrorV1::Unsupported(
                "a deterministic scalar switch fallback is outside the semantic CFG",
            ));
        }
        if switch_fallback_is_empty_unreachable_v1(function, otherwise) && exhausts_valid_domain {
            let (_, _, exhaustive_target) =
                projected_targets
                    .pop()
                    .ok_or(ProductionRankedProjectionErrorV1::Incomplete(
                        "an authenticated valid-value domain has no retained switch target",
                    ))?;
            otherwise = exhaustive_target;
        }
        switches[block_index] = Some(ProjectedDeterministicSwitchV1 {
            source_discriminant,
            discriminant,
            targets: projected_targets,
            otherwise,
            lane_uniform,
        });
    }
    Ok(switches)
}

fn bind_optional_induction_preheaders_v1(
    function: &SemanticFunctionDeclV1,
    predicates: &[Option<GuardPredicateV1>],
    deterministic_switches: &[Option<ProjectedDeterministicSwitchV1>],
    inductions: &[ProjectedUniformInductionV1],
) -> Result<(), ProductionRankedProjectionErrorV1> {
    let mut special_roles = HashSet::new();
    for induction in inductions {
        for block in [
            induction.initializer_block,
            induction.header,
            induction.latch,
        ] {
            if !special_roles.insert(block) {
                return Err(ProductionRankedProjectionErrorV1::Incomplete(
                    "uniform inductions have ambiguous preheader, header, or latch ownership",
                ));
            }
        }
        let ProjectedInductionPreheaderControlV1::Optional {
            discriminant,
            explicit_value,
            explicit_target,
            otherwise,
        } = &induction.preheader_control
        else {
            continue;
        };
        let raw = function.blocks().get(induction.initializer_block).ok_or(
            ProductionRankedProjectionErrorV1::Unsupported(
                "an optional uniform induction preheader is outside the semantic CFG",
            ),
        )?;
        let SemanticTerminatorKindV1::SwitchInt {
            discriminant: raw_discriminant,
            targets: raw_targets,
        } = raw.terminator().kind()
        else {
            return Err(ProductionRankedProjectionErrorV1::Incomplete(
                "an optional uniform induction preheader changed control kind",
            ));
        };
        let [raw_explicit] = raw_targets.values() else {
            return Err(ProductionRankedProjectionErrorV1::Incomplete(
                "an optional uniform induction preheader changed target cardinality",
            ));
        };
        if raw_discriminant != discriminant
            || raw_explicit.value() != *explicit_value
            || raw_explicit.edge().role() != SemanticEdgeRoleV1::SwitchValue
            || raw_explicit.edge().target().index() as usize != *explicit_target
            || raw_targets.otherwise().role() != SemanticEdgeRoleV1::SwitchOtherwise
            || raw_targets.otherwise().target().index() as usize != *otherwise
        {
            return Err(ProductionRankedProjectionErrorV1::Incomplete(
                "an optional uniform induction preheader changed discriminant or edge identity",
            ));
        }
        if simple_operand_local(discriminant).is_some_and(|local| {
            predicates
                .get(local.index() as usize)
                .is_some_and(Option::is_some)
        }) {
            return Err(ProductionRankedProjectionErrorV1::Incomplete(
                "an optional uniform induction preheader projected as a generic predicate",
            ));
        }
        let projected = deterministic_switches
            .get(induction.initializer_block)
            .and_then(Option::as_ref)
            .ok_or(ProductionRankedProjectionErrorV1::Incomplete(
                "an optional uniform induction preheader lacks one exact deterministic switch",
            ))?;
        let [(projected_value, _, projected_target)] = projected.targets.as_slice() else {
            return Err(ProductionRankedProjectionErrorV1::Incomplete(
                "an optional uniform induction preheader projected with non-canonical target cardinality",
            ));
        };
        if !projected.lane_uniform
            || projected.source_discriminant != *discriminant
            || projected_value != explicit_value
            || projected_target != explicit_target
            || projected.otherwise != *otherwise
        {
            return Err(ProductionRankedProjectionErrorV1::Incomplete(
                "an optional uniform induction preheader did not retain its exact lane-uniform control",
            ));
        }
    }
    Ok(())
}

fn tuple_field_operand_local_v1(
    operand: &SemanticOperandV1,
    field: u32,
) -> Option<SemanticLocalIdV1> {
    let (SemanticOperandV1::Copy(place) | SemanticOperandV1::Move(place)) = operand else {
        return None;
    };
    matches!(
        place.projections(),
        [projection] if projection.kind() == SemanticProjectionKindV1::Field(field)
    )
    .then_some(place.local())
}

fn same_semantic_operand_value_v1(left: &SemanticOperandV1, right: &SemanticOperandV1) -> bool {
    match (left, right) {
        (SemanticOperandV1::Constant(left), SemanticOperandV1::Constant(right)) => left == right,
        (
            SemanticOperandV1::Copy(left) | SemanticOperandV1::Move(left),
            SemanticOperandV1::Copy(right) | SemanticOperandV1::Move(right),
        ) => left == right,
        _ => false,
    }
}

fn source_induction_update_v1<'a>(
    function: &'a SemanticFunctionDeclV1,
    graph: &ProjectedLoopCfgV1,
    assertion_proofs: &mut SemanticAssertProofsV1<'_>,
    topology: &ProjectedNaturalLoopTopologyV1,
    induction: SemanticLocalIdV1,
    latch_statement: usize,
    local_definitions: &[u8],
    assignment_sites: &[Option<ScalarAssignmentSiteV1>],
    alias_work: &mut usize,
) -> Result<
    Option<(ProjectedSourceInductionUpdateV1, &'a SemanticOperandV1)>,
    ProductionRankedProjectionErrorV1,
> {
    source_induction_update_parts_v1(
        function,
        graph,
        assertion_proofs,
        topology.latch,
        &topology.loop_blocks,
        induction,
        latch_statement,
        local_definitions,
        assignment_sites,
        alias_work,
    )
}

#[allow(clippy::too_many_arguments)]
fn source_induction_update_parts_v1<'a>(
    function: &'a SemanticFunctionDeclV1,
    graph: &ProjectedLoopCfgV1,
    assertion_proofs: &mut SemanticAssertProofsV1<'_>,
    latch_block: usize,
    loop_blocks: &[usize],
    induction: SemanticLocalIdV1,
    latch_statement: usize,
    local_definitions: &[u8],
    assignment_sites: &[Option<ScalarAssignmentSiteV1>],
    alias_work: &mut usize,
) -> Result<
    Option<(ProjectedSourceInductionUpdateV1, &'a SemanticOperandV1)>,
    ProductionRankedProjectionErrorV1,
> {
    let Some(latch) = function
        .blocks()
        .get(latch_block)
        .and_then(|block| block.statements().get(latch_statement))
    else {
        return Ok(None);
    };
    let SemanticStatementKindV1::Assign(latch) = latch.kind() else {
        return Ok(None);
    };
    if !latch.destination().projections().is_empty()
        || latch.destination().local() != induction
        || latch.value().result_type() != latch.destination().ty()
    {
        return Ok(None);
    }

    let (update, producer_block, producer_statement, left, right) = match latch.value().kind() {
        SemanticRvalueKindV1::Binary {
            operation: SemanticBinaryOpV1::Add,
            left,
            right,
        } => (
            ProjectedSourceInductionUpdateV1::Ordinary,
            latch_block,
            latch_statement,
            left,
            right,
        ),
        SemanticRvalueKindV1::UncheckedBinary(unchecked)
            if unchecked.operation() == SemanticUncheckedBinaryOpV1::Add =>
        {
            (
                ProjectedSourceInductionUpdateV1::Unchecked,
                latch_block,
                latch_statement,
                unchecked.left(),
                unchecked.right(),
            )
        }
        SemanticRvalueKindV1::Use(result) => {
            let result_local = tuple_field_operand_local_v1(result, 0).ok_or(
                ProductionRankedProjectionErrorV1::Incomplete(
                    "a checked induction latch does not copy field zero of one checked result",
                ),
            )?;
            if result.ty() != latch.destination().ty()
                || local_definitions
                    .get(result_local.index() as usize)
                    .copied()
                    != Some(1)
            {
                return Err(ProductionRankedProjectionErrorV1::Incomplete(
                    "a checked induction result has the wrong value type or definition count",
                ));
            }
            let Some(authenticated) = assertion_proofs.authenticated_checked_binary_value_v1(
                result,
                latch_block,
                latch_statement,
            )?
            else {
                return Err(ProductionRankedProjectionErrorV1::Incomplete(
                    "a checked induction overflow assertion does not authenticate its exact Add result and success edge",
                ));
            };
            let producer_block = authenticated.definition.block;
            let producer_statement = authenticated.definition.statement;
            let SemanticStatementKindV1::Assign(definition) =
                function.blocks()[producer_block].statements()[producer_statement].kind()
            else {
                return Err(ProductionRankedProjectionErrorV1::Incomplete(
                    "a checked induction result has no assignment definition",
                ));
            };
            let SemanticRvalueKindV1::CheckedBinary(checked) = definition.value().kind() else {
                return Err(ProductionRankedProjectionErrorV1::Incomplete(
                    "a checked induction result is not defined by checked arithmetic",
                ));
            };
            if checked.operation() != SemanticCheckedBinaryOpV1::Add {
                return Err(ProductionRankedProjectionErrorV1::Incomplete(
                    "a checked induction result is not defined by checked Add",
                ));
            }
            if producer_statement + 1 != function.blocks()[producer_block].statements().len()
                || loop_blocks.binary_search(&producer_block).is_err()
            {
                return Err(ProductionRankedProjectionErrorV1::Incomplete(
                    "a checked induction producer is not the final statement inside its loop",
                ));
            }
            if graph.predecessors.get(latch_block).map(Vec::as_slice) != Some(&[producer_block]) {
                return Err(ProductionRankedProjectionErrorV1::Incomplete(
                    "a checked induction latch does not have one exact producer predecessor",
                ));
            }
            let SemanticTerminatorKindV1::Assert { target, .. } =
                function.blocks()[producer_block].terminator().kind()
            else {
                return Err(ProductionRankedProjectionErrorV1::Incomplete(
                    "a checked induction producer does not terminate with an assertion",
                ));
            };
            if authenticated.assertion_block != producer_block
                || target.target().index() as usize != latch_block
            {
                return Err(ProductionRankedProjectionErrorV1::Incomplete(
                    "a checked induction overflow assertion does not authenticate its exact Add result and success edge",
                ));
            }
            (
                ProjectedSourceInductionUpdateV1::Checked {
                    producer_block,
                    producer_statement,
                    result_local,
                },
                producer_block,
                producer_statement,
                checked.left(),
                checked.right(),
            )
        }
        _ => return Ok(None),
    };

    if left.ty() != latch.destination().ty() || right.ty() != latch.destination().ty() {
        return Ok(None);
    }
    let use_site = ScalarAssignmentSiteV1 {
        block: producer_block,
        statement: producer_statement,
    };
    let left_origin = resolve_block_copy_alias_before_v1(
        function,
        use_site,
        left,
        local_definitions,
        assignment_sites,
        &assertion_proofs.address_escaped,
        alias_work,
    )?;
    let right_origin = resolve_block_copy_alias_before_v1(
        function,
        use_site,
        right,
        local_definitions,
        assignment_sites,
        &assertion_proofs.address_escaped,
        alias_work,
    )?;
    let step = if left_origin == Some(induction) {
        right
    } else if right_origin == Some(induction) {
        left
    } else {
        return Ok(None);
    };
    Ok(Some((update, step)))
}

fn exact_optional_induction_selector_v1(
    types: &[SemanticTypeDeclV1],
    function: &SemanticFunctionDeclV1,
    discriminant: &SemanticOperandV1,
    explicit_value: u128,
    constants: &[Option<u64>],
    stable_argument_origins: &[Option<u32>],
    local_definitions: &[u8],
    address_escaped: &[bool],
) -> bool {
    let Some(shape) = types
        .get(discriminant.ty().index() as usize)
        .map(SemanticTypeDeclV1::shape)
    else {
        return false;
    };
    if matches!(
        shape,
        SemanticTypeShapeV1::Scalar(SemanticScalarTypeV1::Bool)
    ) {
        return matches!(explicit_value, 0 | 1)
            && (constant_operand_value(discriminant, constants).is_some()
                || simple_operand_local(discriminant).is_some_and(|local| {
                    stable_argument_origins
                        .get(local.index() as usize)
                        .copied()
                        .flatten()
                        .is_some()
                }));
    }
    if !matches!(
        shape,
        SemanticTypeShapeV1::Scalar(SemanticScalarTypeV1::Integer {
            signed: false,
            bits: 32,
        })
    ) || explicit_value != 0
    {
        return false;
    }
    if matches!(discriminant, SemanticOperandV1::Constant(_)) {
        return constant_operand_value(discriminant, constants).is_some();
    }
    let Some(local) = simple_operand_local(discriminant) else {
        return false;
    };
    let index = local.index() as usize;
    let Some(SemanticLocalRoleV1::Argument(argument)) =
        function.locals().get(index).map(|local| local.role())
    else {
        return false;
    };
    local_definitions.get(index).copied() == Some(0)
        && address_escaped.get(index).copied() == Some(false)
        && stable_argument_origins.get(index).copied().flatten() == Some(argument)
}

#[allow(clippy::too_many_arguments)]
fn project_uniform_inductions_with_multi_entry_v1(
    callables: &[SemanticCallableDeclV1],
    types: &[SemanticTypeDeclV1],
    function: &SemanticFunctionDeclV1,
    constants: &[Option<u64>],
    stable_argument_origins: &[Option<u32>],
    local_definitions: &[u8],
    arguments: &mut [Option<u32>],
    next_argument: &mut usize,
    operations: &mut Vec<ProductionRankedOperationV1>,
    next_value: &mut u32,
    mut multi: Option<&mut multi_entry_induction_v1::Context<'_, '_>>,
) -> Result<Vec<ProjectedUniformInductionV1>, ProductionRankedProjectionErrorV1> {
    let graph = projected_loop_cfg_graph_v1(function)?;
    let mut semantic_ranges = SemanticAssertProofsV1::new(types, function)?;
    let pure_uniform_definitions = semantic_ranges.assignments.clone();
    let pure_uniform_address_escaped = semantic_ranges.address_escaped.clone();
    let mut graph_work = 0_usize;
    let mut alias_work = 0_usize;
    let mut inductions = Vec::new();
    let mut has_multi_entry = false;
    for (header, block) in function.blocks().iter().enumerate() {
        let SemanticTerminatorKindV1::SwitchInt {
            discriminant,
            targets,
        } = block.terminator().kind()
        else {
            continue;
        };
        let Some(discriminant) = simple_operand_local(discriminant) else {
            continue;
        };
        if targets.values().len() != 1 || targets.values()[0].value() != 0 {
            continue;
        }
        let mut discriminant_definitions =
            block
                .statements()
                .iter()
                .enumerate()
                .filter_map(|(statement_index, statement)| {
                    let SemanticStatementKindV1::Assign(assignment) = statement.kind() else {
                        return None;
                    };
                    (assignment.destination().projections().is_empty()
                        && assignment.destination().local() == discriminant)
                        .then_some((statement_index, assignment))
                });
        let Some((comparison_index, comparison)) = discriminant_definitions.next() else {
            continue;
        };
        if discriminant_definitions.next().is_some() {
            return Err(ProductionRankedProjectionErrorV1::Incomplete(
                "a uniform induction comparison with multiple header definitions",
            ));
        }
        let SemanticRvalueKindV1::Binary {
            operation: SemanticBinaryOpV1::LessThan,
            left,
            right: bound_operand,
        } = comparison.value().kind()
        else {
            continue;
        };
        let Some(induction) = resolve_block_copy_alias_before_v1(
            function,
            ScalarAssignmentSiteV1 {
                block: header,
                statement: comparison_index,
            },
            left,
            local_definitions,
            &pure_uniform_definitions,
            &pure_uniform_address_escaped,
            &mut alias_work,
        )?
        else {
            continue;
        };
        let bound_bit_width = semantic_ranges
            .range_at_operand(bound_operand, header, comparison_index)?
            .and_then(|range| unsigned_bit_width_for_maximum_v1(range.maximum));
        let body_entry = targets.otherwise().target().index() as usize;
        let exit = targets.values()[0].edge().target().index() as usize;
        if body_entry >= function.blocks().len() || exit >= function.blocks().len() {
            return Err(ProductionRankedProjectionErrorV1::Unsupported(
                "a uniform induction successor outside the semantic CFG",
            ));
        }
        let Some(mut topology) = project_natural_loop_topology_v1(
            callables,
            function,
            &graph,
            header,
            body_entry,
            exit,
            &mut graph_work,
            multi.as_deref_mut().map(|context| (induction, context)),
        )?
        else {
            continue;
        };
        has_multi_entry |= matches!(
            topology.preheader_control,
            ProjectedInductionPreheaderControlV1::Multiple(_)
        );
        let induction_index = induction.index() as usize;
        if local_definitions.get(induction_index).copied() != Some(2) {
            return Err(ProductionRankedProjectionErrorV1::Incomplete(
                "a uniform induction does not have exactly its initializer and latch definitions",
            ));
        }
        if let ProjectedInductionPreheaderControlV1::Optional {
            discriminant,
            explicit_value,
            ..
        } = &topology.preheader_control
            && !exact_optional_induction_selector_v1(
                types,
                function,
                discriminant,
                *explicit_value,
                constants,
                stable_argument_origins,
                local_definitions,
                &semantic_ranges.address_escaped,
            )
        {
            return Err(ProductionRankedProjectionErrorV1::Incomplete(
                "an optional uniform induction preheader is not controlled by one exact lane-uniform selector",
            ));
        }
        let induction_type = function
            .locals()
            .get(induction_index)
            .ok_or(ProductionRankedProjectionErrorV1::Incomplete(
                "a uniform induction local is outside the authenticated type table",
            ))?
            .ty();
        let mut initial = None;
        for statement in function.blocks()[topology.initializer_block].statements() {
            let SemanticStatementKindV1::Assign(assignment) = statement.kind() else {
                continue;
            };
            if assignment.destination().projections().is_empty()
                && assignment.destination().local() == induction
            {
                let SemanticRvalueKindV1::Use(operand) = assignment.value().kind() else {
                    return Err(ProductionRankedProjectionErrorV1::Incomplete(
                        "a uniform induction has a non-canonical preheader definition",
                    ));
                };
                if assignment.destination().ty() != induction_type
                    || assignment.value().result_type() != induction_type
                    || operand.ty() != induction_type
                {
                    return Err(ProductionRankedProjectionErrorV1::Incomplete(
                        "a uniform induction initializer changed its exact scalar type",
                    ));
                }
                if initial.replace(operand).is_some() {
                    return Err(ProductionRankedProjectionErrorV1::Incomplete(
                        "a uniform induction has multiple preheader definitions",
                    ));
                }
            }
        }
        let mut step = None;
        for (statement_index, statement) in function.blocks()[topology.latch]
            .statements()
            .iter()
            .enumerate()
        {
            let SemanticStatementKindV1::Assign(assignment) = statement.kind() else {
                continue;
            };
            if assignment.destination().projections().is_empty()
                && assignment.destination().local() == induction
            {
                let (update, candidate) = source_induction_update_v1(
                    function,
                    &graph,
                    &mut semantic_ranges,
                    &topology,
                    induction,
                    statement_index,
                    local_definitions,
                    &pure_uniform_definitions,
                    &mut alias_work,
                )?
                .ok_or(ProductionRankedProjectionErrorV1::Incomplete(
                    "a uniform induction has a non-canonical latch definition",
                ))?;
                if step.replace((statement_index, update, candidate)).is_some() {
                    return Err(ProductionRankedProjectionErrorV1::Incomplete(
                        "a uniform induction has multiple latch definitions",
                    ));
                }
            }
        }
        for candidate in topology.loop_blocks.iter().copied() {
            if candidate == topology.latch {
                continue;
            }
            for statement in function.blocks()[candidate].statements() {
                let SemanticStatementKindV1::Assign(assignment) = statement.kind() else {
                    continue;
                };
                if !assignment.destination().projections().is_empty()
                    || assignment.destination().local() != induction
                {
                    continue;
                }
                return Err(ProductionRankedProjectionErrorV1::Incomplete(
                    "a uniform induction is modified outside its unique latch",
                ));
            }
        }
        if initial.is_none()
            && step.is_some()
            && matches!(
                topology.preheader_control,
                ProjectedInductionPreheaderControlV1::Direct
            )
            && let Some(context) = multi.as_deref_mut()
        {
            let proof = multi_entry_induction_v1::single::build(
                function,
                &graph,
                topology.initializer_block,
                header,
                topology.latch,
                induction,
                context,
            )?;
            context.facts.charge_private_array_work(8)?;
            let site = proof.initialization();
            let SemanticStatementKindV1::Assign(assignment) =
                function.blocks()[site.block].statements()[site.statement].kind()
            else {
                return Err(ProductionRankedProjectionErrorV1::Incomplete(
                    "a distant induction initializer is not an assignment",
                ));
            };
            let SemanticRvalueKindV1::Use(operand) = assignment.value().kind() else {
                return Err(ProductionRankedProjectionErrorV1::Incomplete(
                    "a distant induction initializer is not an exact scalar use",
                ));
            };
            if assignment.destination().ty() != induction_type
                || assignment.value().result_type() != induction_type
                || operand.ty() != induction_type
            {
                return Err(ProductionRankedProjectionErrorV1::Incomplete(
                    "a distant induction initializer changed its exact scalar type",
                ));
            }
            initial = Some(operand);
            topology.preheader_control = ProjectedInductionPreheaderControlV1::DistantDirect(proof);
        }
        let (Some(initial), Some((latch_statement, update, step))) = (initial, step) else {
            return Err(ProductionRankedProjectionErrorV1::Incomplete(
                "a uniform induction without exact initial and latch definitions",
            ));
        };
        if matches!(
            topology.preheader_control,
            ProjectedInductionPreheaderControlV1::Multiple(_)
        ) && !matches!(update, ProjectedSourceInductionUpdateV1::Ordinary)
        {
            return Err(ProductionRankedProjectionErrorV1::Incomplete(
                "multi-entry induction requires an ordinary range-proved Add recurrence",
            ));
        }
        let step_value = positive_unsigned_constant_operand_v1(step, constants, types).ok_or(
            ProductionRankedProjectionErrorV1::Incomplete(
                "a uniform induction whose positive step is not statically established",
            ),
        )?;
        let source_step_operand = step.clone();
        let Some(initial) = project_uniform_switch_operand_v1(
            initial,
            constants,
            stable_argument_origins,
            arguments,
            next_argument,
            operations,
            next_value,
        )?
        else {
            return Err(ProductionRankedProjectionErrorV1::Incomplete(
                "a uniform induction with a lane-varying initial value",
            ));
        };
        if let ProjectedInductionPreheaderControlV1::Multiple(entries) =
            &mut topology.preheader_control
        {
            let context =
                multi
                    .as_deref_mut()
                    .ok_or(ProductionRankedProjectionErrorV1::Incomplete(
                        "multi-entry initialization requires live canonical facts",
                    ))?;
            multi_entry_induction_v1::bind_initial(entries, initial, context)?;
        }
        if let ProjectedInductionPreheaderControlV1::DistantDirect(proof) =
            &mut topology.preheader_control
        {
            let context =
                multi
                    .as_deref_mut()
                    .ok_or(ProductionRankedProjectionErrorV1::Incomplete(
                        "distant induction initialization requires live canonical facts",
                    ))?;
            multi_entry_induction_v1::single::bind_initial(proof, initial, context)?;
        }
        let Some(bound) = project_pure_uniform_index_operand_v1(
            types,
            function,
            constants,
            local_definitions,
            &pure_uniform_address_escaped,
            &pure_uniform_definitions,
            &mut semantic_ranges,
            &graph,
            header,
            comparison_index,
            bound_operand,
            arguments,
            next_argument,
            operations,
            next_value,
        )?
        else {
            return Err(ProductionRankedProjectionErrorV1::Incomplete(
                "a uniform induction bound is not an exact total unsigned index expression",
            ));
        };
        let Some(step) = project_uniform_switch_operand_v1(
            step,
            constants,
            stable_argument_origins,
            arguments,
            next_argument,
            operations,
            next_value,
        )?
        else {
            return Err(ProductionRankedProjectionErrorV1::Incomplete(
                "a uniform induction with a lane-varying step",
            ));
        };
        let bound_cast = bound_bit_width.map(|bit_width| ProjectedUnsignedCastCandidateV1 {
            header,
            comparison_statement: comparison_index,
            source_operand: bound_operand.clone(),
            source_type: bound_operand.ty(),
            ranked_value: bound,
            bit_width,
        });
        let source_progress = ProjectedSourceInductionCandidateV1 {
            induction,
            induction_type,
            header_statement: comparison_index,
            bound_operand: bound_operand.clone(),
            latch_statement,
            update,
            step_operand: source_step_operand,
            step_value,
            ranked_bound: bound,
            ranked_step: step,
        };
        inductions.push(ProjectedUniformInductionV1 {
            initializer_block: topology.initializer_block,
            preheader_control: topology.preheader_control,
            header,
            body_entry,
            latch: topology.latch,
            exit,
            loop_blocks: topology.loop_blocks,
            initial,
            bound,
            step,
            source_progress,
            bound_cast,
            body_predicates: Vec::new(),
        });
    }
    inductions.sort_by(|left, right| {
        right
            .loop_blocks
            .len()
            .cmp(&left.loop_blocks.len())
            .then_with(|| left.header.cmp(&right.header))
    });
    for (index, left) in inductions.iter().enumerate() {
        for right in &inductions[index + 1..] {
            let overlaps = left
                .loop_blocks
                .iter()
                .any(|block| right.contains_block(*block));
            let right_is_nested = right
                .loop_blocks
                .iter()
                .all(|block| left.contains_block(*block));
            if overlaps && !right_is_nested {
                return Err(ProductionRankedProjectionErrorV1::Incomplete(
                    "partially overlapping uniform induction regions",
                ));
            }
        }
    }
    let mut special_roles = HashSet::new();
    for induction in &inductions {
        for block in [
            induction.initializer_block,
            induction.header,
            induction.latch,
        ] {
            if !special_roles.insert(block) {
                return Err(ProductionRankedProjectionErrorV1::Incomplete(
                    "uniform inductions have ambiguous preheader, header, or latch ownership",
                ));
            }
        }
    }
    if has_multi_entry {
        let context = multi.ok_or(ProductionRankedProjectionErrorV1::Incomplete(
            "multi-entry role replay requires live canonical facts",
        ))?;
        multi_entry_induction_v1::check_roles(&inductions, context)?;
    }
    Ok(inductions)
}

fn unsigned_bit_width_for_maximum_v1(maximum: u128) -> Option<u16> {
    match maximum {
        maximum if maximum == u128::from(u8::MAX) => Some(8),
        maximum if maximum == u128::from(u16::MAX) => Some(16),
        maximum if maximum == u128::from(u32::MAX) => Some(32),
        maximum if maximum == u128::from(u64::MAX) => Some(64),
        _ => None,
    }
}

#[allow(clippy::too_many_arguments)]
fn reconcile_source_progress_with_multi_entry_v1(
    types: &[SemanticTypeDeclV1],
    function: &SemanticFunctionDeclV1,
    constants: &[Option<u64>],
    stable_argument_origins: &[Option<u32>],
    local_definitions: &[u8],
    arguments: &[Option<u32>],
    inductions: &mut [ProjectedUniformInductionV1],
    operations: &mut Vec<ProductionRankedOperationV1>,
    next_value: &mut u32,
    mut multi: Option<&mut multi_entry_induction_v1::Context<'_, '_>>,
) -> Result<(), ProductionRankedProjectionErrorV1> {
    let mut reconciled = BTreeMap::new();
    let graph = projected_loop_cfg_graph_v1(function)?;
    let mut semantic_ranges = SemanticAssertProofsV1::new(types, function)?;
    let assignment_sites = semantic_ranges.assignments.clone();
    let address_escaped = semantic_ranges.address_escaped.clone();
    let mut alias_work = 0_usize;
    for induction in inductions.iter() {
        let source = &induction.source_progress;
        let induction_type = function
            .locals()
            .get(source.induction.index() as usize)
            .map(|local| local.ty())
            .ok_or(ProductionRankedProjectionErrorV1::Incomplete(
                "a compiler-derived source induction has a stale local",
            ))?;
        let comparison = function
            .blocks()
            .get(induction.header)
            .and_then(|block| block.statements().get(source.header_statement))
            .ok_or(ProductionRankedProjectionErrorV1::Incomplete(
                "a compiler-derived source induction has a stale comparison site",
            ))?;
        let SemanticStatementKindV1::Assign(comparison) = comparison.kind() else {
            return Err(ProductionRankedProjectionErrorV1::Incomplete(
                "a compiler-derived source induction comparison is no longer an assignment",
            ));
        };
        let SemanticRvalueKindV1::Binary {
            operation: SemanticBinaryOpV1::LessThan,
            left,
            right: bound_operand,
        } = comparison.value().kind()
        else {
            return Err(ProductionRankedProjectionErrorV1::Incomplete(
                "a compiler-derived source induction comparison is no longer an exact less-than",
            ));
        };
        let compared_induction = resolve_block_copy_alias_before_v1(
            function,
            ScalarAssignmentSiteV1 {
                block: induction.header,
                statement: source.header_statement,
            },
            left,
            local_definitions,
            &assignment_sites,
            &address_escaped,
            &mut alias_work,
        )?;
        if induction_type != source.induction_type
            || left.ty() != source.induction_type
            || compared_induction != Some(source.induction)
            || bound_operand != &source.bound_operand
            || induction.bound != source.ranked_bound
            || induction.step != source.ranked_step
        {
            return Err(ProductionRankedProjectionErrorV1::Incomplete(
                "a compiler-derived source induction comparison changed type or value",
            ));
        }
        let bound_range = semantic_ranges
            .range_at_operand(bound_operand, induction.header, source.header_statement)?
            .ok_or(ProductionRankedProjectionErrorV1::Incomplete(
                "a compiler-derived source induction has no finite unsigned bound",
            ))?;
        let latch = function
            .blocks()
            .get(induction.latch)
            .and_then(|block| block.statements().get(source.latch_statement))
            .ok_or(ProductionRankedProjectionErrorV1::Incomplete(
                "a compiler-derived source induction has a stale latch site",
            ))?;
        let SemanticStatementKindV1::Assign(latch) = latch.kind() else {
            return Err(ProductionRankedProjectionErrorV1::Incomplete(
                "a compiler-derived source induction latch is no longer an assignment",
            ));
        };
        let replayed = if let ProjectedInductionPreheaderControlV1::Multiple(entries) =
            &induction.preheader_control
        {
            let context =
                multi
                    .as_deref_mut()
                    .ok_or(ProductionRankedProjectionErrorV1::Incomplete(
                        "multi-entry source replay requires live canonical facts",
                    ))?;
            multi_entry_induction_v1::replay(
                entries,
                function,
                &graph,
                induction.header,
                induction.latch,
                source.induction,
                context,
            )?;
            if entries.initialization.block != induction.initializer_block
                || !matches!(source.update, ProjectedSourceInductionUpdateV1::Ordinary)
            {
                return Err(ProductionRankedProjectionErrorV1::Incomplete(
                    "multi-entry source initializer or recurrence family changed",
                ));
            }
            source_induction_update_parts_v1(
                function,
                &graph,
                &mut semantic_ranges,
                induction.latch,
                &induction.loop_blocks,
                source.induction,
                source.latch_statement,
                local_definitions,
                &assignment_sites,
                &mut alias_work,
            )?
        } else if let ProjectedInductionPreheaderControlV1::DistantDirect(proof) =
            &induction.preheader_control
        {
            let context =
                multi
                    .as_deref_mut()
                    .ok_or(ProductionRankedProjectionErrorV1::Incomplete(
                        "distant induction source replay requires live canonical facts",
                    ))?;
            multi_entry_induction_v1::single::replay(proof, function, &graph, induction, context)?;
            source_induction_update_parts_v1(
                function,
                &graph,
                &mut semantic_ranges,
                induction.latch,
                &induction.loop_blocks,
                source.induction,
                source.latch_statement,
                local_definitions,
                &assignment_sites,
                &mut alias_work,
            )?
        } else {
            let topology = ProjectedNaturalLoopTopologyV1 {
                initializer_block: induction.initializer_block,
                preheader_control: induction.preheader_control.clone_single_v1()?,
                latch: induction.latch,
                loop_blocks: induction.loop_blocks.clone(),
            };
            source_induction_update_v1(
                function,
                &graph,
                &mut semantic_ranges,
                &topology,
                source.induction,
                source.latch_statement,
                local_definitions,
                &assignment_sites,
                &mut alias_work,
            )?
        };
        let (replayed_update, replayed_step) = replayed
        .ok_or(ProductionRankedProjectionErrorV1::Incomplete(
            "a compiler-derived source induction latch is no longer an authenticated Add recurrence",
        ))?;
        if !latch.destination().projections().is_empty()
            || latch.destination().local() != source.induction
            || latch.destination().ty() != source.induction_type
            || latch.value().result_type() != source.induction_type
            || replayed_update != source.update
            || replayed_step != &source.step_operand
            || positive_unsigned_constant_operand_v1(replayed_step, constants, types)
                != Some(source.step_value)
        {
            return Err(ProductionRankedProjectionErrorV1::Incomplete(
                "a compiler-derived source induction latch changed type, step, or overflow semantics",
            ));
        }
        let induction_maximum = semantic_ranges
            .scalar_unsigned_maximum(source.induction_type)
            .ok_or(ProductionRankedProjectionErrorV1::Incomplete(
                "a compiler-derived source induction does not use a supported unsigned scalar type",
            ))?;
        if bound_range.maximum != 0
            && (bound_range.maximum - 1)
                .checked_add(u128::from(source.step_value))
                .is_none_or(|updated| updated > induction_maximum)
        {
            return Err(ProductionRankedProjectionErrorV1::Incomplete(
                "a compiler-derived source induction update may overflow its exact unsigned type",
            ));
        }
        let Some(range) = &induction.bound_cast else {
            continue;
        };
        if range.header != induction.header || range.comparison_statement != source.header_statement
        {
            return Err(ProductionRankedProjectionErrorV1::Incomplete(
                "a compiler-derived unsigned cast has a stale semantic statement site",
            ));
        }
        let statement = function
            .blocks()
            .get(range.header)
            .and_then(|block| block.statements().get(range.comparison_statement))
            .ok_or(ProductionRankedProjectionErrorV1::Incomplete(
                "a compiler-derived unsigned cast has a stale semantic statement site",
            ))?;
        let SemanticStatementKindV1::Assign(assignment) = statement.kind() else {
            return Err(ProductionRankedProjectionErrorV1::Incomplete(
                "a compiler-derived unsigned cast no longer names an assignment",
            ));
        };
        let SemanticRvalueKindV1::Binary {
            operation: SemanticBinaryOpV1::LessThan,
            right: source_operand,
            ..
        } = assignment.value().kind()
        else {
            return Err(ProductionRankedProjectionErrorV1::Incomplete(
                "a compiler-derived unsigned cast no longer names a loop comparison",
            ));
        };
        let reconciled_width = unsigned_bit_width_for_maximum_v1(bound_range.maximum);
        if source_operand != &range.source_operand
            || source_operand.ty() != range.source_type
            || reconciled_width != Some(range.bit_width)
            || range.ranked_value != induction.bound
        {
            return Err(ProductionRankedProjectionErrorV1::Incomplete(
                "a compiler-derived unsigned cast does not match its exact semantic range and ranked source",
            ));
        }
        if constant_operand_value(source_operand, constants).is_some() {
            continue;
        }
        match range.ranked_value {
            ProductionRankedValueV1::Argument(ranked_argument) => {
                let local = simple_operand_local(source_operand).ok_or(
                    ProductionRankedProjectionErrorV1::Incomplete(
                        "a compiler-derived argument cast has no exact scalar local",
                    ),
                )?;
                let local_index = local.index() as usize;
                let origin = stable_argument_origins
                    .get(local_index)
                    .copied()
                    .flatten()
                    .or_else(|| {
                        (local_definitions.get(local_index).copied() == Some(0)
                            && function.locals().get(local_index).is_some_and(|local| {
                                matches!(local.role(), SemanticLocalRoleV1::Argument(_))
                            }))
                        .then_some(local.index())
                    })
                    .ok_or(ProductionRankedProjectionErrorV1::Incomplete(
                        "a compiler-derived unsigned cast is not backed by one stable semantic argument",
                    ))? as usize;
                let argument = arguments.get(origin).copied().flatten().ok_or(
                    ProductionRankedProjectionErrorV1::Incomplete(
                        "a compiler-derived unsigned cast has no final ranked argument mapping",
                    ),
                )?;
                if ranked_argument != argument {
                    return Err(ProductionRankedProjectionErrorV1::Incomplete(
                        "a compiler-derived unsigned cast was substituted onto a different ranked source",
                    ));
                }
            }
            // A local source was emitted by the authenticated pure-uniform
            // projector and is already tied above to both the exact semantic
            // comparison operand and the retained source-progress value.
            ProductionRankedValueV1::Local(_) => {}
            ProductionRankedValueV1::BlockArgument { .. } => {
                return Err(ProductionRankedProjectionErrorV1::Incomplete(
                    "a compiler-derived unsigned cast cannot use a loop-carried ranked source",
                ));
            }
        }
        match reconciled.insert(range.ranked_value, range.bit_width) {
            Some(previous) if previous != range.bit_width => {
                return Err(ProductionRankedProjectionErrorV1::Incomplete(
                    "one ranked source has incompatible compiler-derived unsigned cast widths",
                ));
            }
            _ => {}
        }
    }
    let mut converted = BTreeMap::new();
    for (source, bit_width) in reconciled {
        reserve_operation(operations)?;
        let result = next_value_id(next_value)?;
        let value = ProductionRankedValueV1::Local(result);
        operations.push(ProductionRankedOperationV1::IndexUnsignedCast {
            result,
            source,
            bit_width,
        });
        converted.insert(source, value);
    }
    for induction in inductions {
        let Some(range) = &induction.bound_cast else {
            continue;
        };
        if constant_operand_value(&range.source_operand, constants).is_some() {
            continue;
        }
        induction.bound = converted.get(&range.ranked_value).copied().ok_or(
            ProductionRankedProjectionErrorV1::Incomplete(
                "a reconciled unsigned cast result is missing from the ranked recipe",
            ),
        )?;
    }
    Ok(())
}

fn resolve_block_copy_alias_before_v1(
    function: &SemanticFunctionDeclV1,
    use_site: ScalarAssignmentSiteV1,
    operand: &SemanticOperandV1,
    local_definitions: &[u8],
    assignment_sites: &[Option<ScalarAssignmentSiteV1>],
    address_escaped: &[bool],
    work: &mut usize,
) -> Result<Option<SemanticLocalIdV1>, ProductionRankedProjectionErrorV1> {
    resolve_block_copy_alias_before_with_limit_v1(
        function,
        use_site,
        operand,
        local_definitions,
        assignment_sites,
        address_escaped,
        work,
        MAX_PROJECTED_CAPABILITY_DATAFLOW_WORK_V1,
    )
}

#[allow(clippy::too_many_arguments)]
fn resolve_block_copy_alias_before_with_limit_v1(
    function: &SemanticFunctionDeclV1,
    mut use_site: ScalarAssignmentSiteV1,
    operand: &SemanticOperandV1,
    local_definitions: &[u8],
    assignment_sites: &[Option<ScalarAssignmentSiteV1>],
    address_escaped: &[bool],
    work: &mut usize,
    work_limit: usize,
) -> Result<Option<SemanticLocalIdV1>, ProductionRankedProjectionErrorV1> {
    let Some(block) = function.blocks().get(use_site.block) else {
        return Err(ProductionRankedProjectionErrorV1::Unsupported(
            "a uniform induction alias use is outside the semantic CFG",
        ));
    };
    if use_site.statement > block.statements().len()
        || local_definitions.len() != function.locals().len()
        || assignment_sites.len() != function.locals().len()
        || address_escaped.len() != function.locals().len()
    {
        return Err(ProductionRankedProjectionErrorV1::Unsupported(
            "uniform induction alias tables or use site are inconsistent",
        ));
    }
    let Some(mut current) = simple_operand_local(operand) else {
        return Ok(None);
    };
    loop {
        *work = work
            .checked_add(1)
            .ok_or(ProductionRankedProjectionErrorV1::Unsupported(
                "uniform induction alias work accounting overflowed",
            ))?;
        if *work > work_limit {
            return Err(ProductionRankedProjectionErrorV1::Unsupported(
                "uniform induction alias analysis exceeds its work limit",
            ));
        }
        let current_index = current.index() as usize;
        if address_escaped.get(current_index).copied() != Some(false) {
            return Err(ProductionRankedProjectionErrorV1::Incomplete(
                "a uniform induction alias has address-escaped value semantics",
            ));
        }
        if local_definitions.get(current_index).copied() != Some(1) {
            return Ok(Some(current));
        }
        let Some(definition) = assignment_sites.get(current_index).copied().flatten() else {
            return Ok(Some(current));
        };
        if definition.block != use_site.block {
            return Ok(Some(current));
        }
        if definition.statement >= use_site.statement {
            return Err(ProductionRankedProjectionErrorV1::Incomplete(
                "a uniform induction operand has a cyclic copy alias",
            ));
        }
        let Some(statement) = function
            .blocks()
            .get(definition.block)
            .and_then(|block| block.statements().get(definition.statement))
        else {
            return Err(ProductionRankedProjectionErrorV1::Unsupported(
                "a uniform induction alias definition is outside the semantic CFG",
            ));
        };
        let SemanticStatementKindV1::Assign(alias) = statement.kind() else {
            return Err(ProductionRankedProjectionErrorV1::Unsupported(
                "an indexed uniform induction alias changed semantic kind",
            ));
        };
        if !alias.destination().projections().is_empty() || alias.destination().local() != current {
            return Err(ProductionRankedProjectionErrorV1::Unsupported(
                "an indexed uniform induction alias changed destination",
            ));
        }
        let SemanticRvalueKindV1::Use(source) = alias.value().kind() else {
            return Ok(Some(current));
        };
        if alias.destination().ty() != source.ty() {
            return Ok(Some(current));
        }
        let Some(source) = simple_operand_local(source) else {
            return Ok(Some(current));
        };
        use_site = definition;
        current = source;
    }
}

#[derive(Debug)]
struct ProjectedLoopCfgV1 {
    successors: Vec<Vec<usize>>,
    predecessors: Vec<Vec<usize>>,
    reachable: Vec<bool>,
    entry: usize,
}

#[derive(Debug)]
struct ProjectedNaturalLoopTopologyV1 {
    initializer_block: usize,
    preheader_control: ProjectedInductionPreheaderControlV1,
    latch: usize,
    loop_blocks: Vec<usize>,
}

fn project_loop_graph_charge_v1(
    work: &mut usize,
    amount: usize,
) -> Result<(), ProductionRankedProjectionErrorV1> {
    *work = work
        .checked_add(amount)
        .ok_or(ProductionRankedProjectionErrorV1::Unsupported(
            "uniform induction CFG analysis work overflow",
        ))?;
    if *work > MAX_PROJECTED_LOOP_GRAPH_WORK_V1 {
        return Err(ProductionRankedProjectionErrorV1::Unsupported(
            "uniform induction CFG analysis exceeds its work limit",
        ));
    }
    Ok(())
}

