    #[test]
    fn relational_nested_flat_index_requires_matching_dimensions_and_custody() {
        let exact =
            relational_nested_flat_index_function(RelationalNestedFlatIndexHostilityV1::Exact);
        assert!(proves_nested_flat_index_fixture_v1(&exact, 8));
        assert!(proves_nested_flat_index_fixture_v1(&exact, 9));
        let swapped = relational_nested_flat_index_function(
            RelationalNestedFlatIndexHostilityV1::ExactSwappedProducts,
        );
        assert!(proves_nested_flat_index_fixture_v1(&swapped, 8));
        assert!(proves_nested_flat_index_fixture_v1(&swapped, 9));

        for hostility in [
            RelationalNestedFlatIndexHostilityV1::WrongDimensionUpper,
            RelationalNestedFlatIndexHostilityV1::WrongDimensionStride,
            RelationalNestedFlatIndexHostilityV1::MissingInnerBound,
            RelationalNestedFlatIndexHostilityV1::WrongInnerBound,
            RelationalNestedFlatIndexHostilityV1::MissingDimensionAssertion,
            RelationalNestedFlatIndexHostilityV1::MissingOuterWitness,
            RelationalNestedFlatIndexHostilityV1::MissingInnerProductAssertion,
            RelationalNestedFlatIndexHostilityV1::MissingBaseAssertion,
            RelationalNestedFlatIndexHostilityV1::MissingFirstAssertion,
            RelationalNestedFlatIndexHostilityV1::ExtraTailReachesStride,
            RelationalNestedFlatIndexHostilityV1::RedefinedInnerAfterGuard,
            RelationalNestedFlatIndexHostilityV1::RedefinedUpperBetweenDimensionAndGuard,
            RelationalNestedFlatIndexHostilityV1::RedefinedUpperAfterGuard,
            RelationalNestedFlatIndexHostilityV1::RedefinedStrideBetweenProducts,
            RelationalNestedFlatIndexHostilityV1::RedefinedLaneAfterGuard,
            RelationalNestedFlatIndexHostilityV1::EscapedInner,
            RelationalNestedFlatIndexHostilityV1::EscapedUpper,
            RelationalNestedFlatIndexHostilityV1::EscapedStride,
            RelationalNestedFlatIndexHostilityV1::EscapedLane,
        ] {
            assert!(
                !proves_nested_flat_index_fixture_v1(
                    &relational_nested_flat_index_function(hostility),
                    9,
                ),
                "{hostility:?} authenticated a substituted relational flat-index proof",
            );
        }
    }

    #[test]
    fn nested_flat_index_path_is_fail_closed_at_depth_and_type_boundaries() {
        let function = nested_flat_index_function(NestedFlatIndexHostilityV1::Exact);
        let sum_site = ScalarAssignmentSiteV1 {
            block: 8,
            statement: 1,
        };
        let SemanticStatementKindV1::Assign(assignment) =
            function.blocks()[sum_site.block].statements()[sum_site.statement].kind()
        else {
            unreachable!("nested flat-index fixture changed its final assignment")
        };
        let SemanticRvalueKindV1::CheckedBinary(checked) = assignment.value().kind() else {
            unreachable!("nested flat-index fixture changed its final checked sum")
        };
        let types = assertion_proof_types();
        let mut proof = SemanticAssertProofsV1::new(&types, &function).unwrap();
        let mut offsets = vec![(checked.right().clone(), sum_site)];
        assert!(
            !proof
                .proves_strictly_bounded_unsigned_flat_index_path_v1(
                    checked.left(),
                    sum_site,
                    sum_site,
                    U64_TYPE,
                    &mut offsets,
                    0,
                )
                .unwrap()
        );

        let signed = projection_function_with_locals(
            vec![block(216, vec![], SemanticTerminatorKindV1::Return)],
            vec![
                local(216, I32_TYPE, SemanticLocalRoleV1::Return),
                local(217, I32_TYPE, SemanticLocalRoleV1::Argument(0)),
                local(218, I32_TYPE, SemanticLocalRoleV1::Argument(1)),
            ],
        );
        let types = assertion_proof_types();
        let mut proof = SemanticAssertProofsV1::new(&types, &signed).unwrap();
        assert!(
            !proof
                .proves_strictly_bounded_unsigned_nested_flat_index_v1(
                    &SemanticCheckedBinaryRvalueV1::new(
                        SemanticCheckedBinaryOpV1::Add,
                        typed_operand(1, I32_TYPE),
                        typed_operand(2, I32_TYPE),
                    ),
                    ScalarAssignmentSiteV1 {
                        block: 0,
                        statement: 0,
                    },
                )
                .unwrap()
        );

        let mismatched = projection_function_with_locals(
            vec![block(219, vec![], SemanticTerminatorKindV1::Return)],
            vec![
                local(219, U64_TYPE, SemanticLocalRoleV1::Return),
                local(220, U64_TYPE, SemanticLocalRoleV1::Argument(0)),
                local(221, BOOL_TYPE, SemanticLocalRoleV1::Argument(1)),
            ],
        );
        let mut proof = SemanticAssertProofsV1::new(&types, &mismatched).unwrap();
        assert!(
            !proof
                .proves_strictly_bounded_unsigned_nested_flat_index_v1(
                    &SemanticCheckedBinaryRvalueV1::new(
                        SemanticCheckedBinaryOpV1::Add,
                        typed_operand(1, U64_TYPE),
                        typed_operand(2, BOOL_TYPE),
                    ),
                    ScalarAssignmentSiteV1 {
                        block: 0,
                        statement: 0,
                    },
                )
                .unwrap()
        );
    }

    #[test]
    fn exact_product_witness_rejects_a_wider_checked_type() {
        let checked_u128 = SemanticTypeIdV1::from_index(13);
        let mut types = assertion_proof_types();
        types.push(SemanticTypeDeclV1::new(
            SemanticTypeIdentityV1::from_sha256(bytes(53)),
            SemanticLayoutIdentityV1::from_sha256(bytes(53)),
            SemanticTypeLayoutV1::aggregate(
                Some(32),
                16,
                SemanticAggregateLayoutV1::new(
                    vec![0, 16],
                    vec![SemanticPaddingV1::new(17, 15).unwrap()],
                )
                .unwrap(),
            )
            .unwrap(),
            SemanticTypeShapeV1::Tuple(
                SemanticAggregateTypeV1::new(vec![U128_TYPE, BOOL_TYPE]).unwrap(),
            ),
        ));
        let widened_left = typed_operand(3, U128_TYPE);
        let widened_right = typed_operand(4, U128_TYPE);
        let function = projection_function_with_locals(
            vec![
                block(
                    251,
                    vec![
                        typed_assignment(
                            3,
                            U128_TYPE,
                            SemanticRvalueKindV1::Cast {
                                kind: SemanticCastKindV1::Integer,
                                operand: typed_operand(1, U64_TYPE),
                            },
                        ),
                        typed_assignment(
                            4,
                            U128_TYPE,
                            SemanticRvalueKindV1::Cast {
                                kind: SemanticCastKindV1::Integer,
                                operand: typed_operand(2, U64_TYPE),
                            },
                        ),
                        typed_assignment(
                            5,
                            checked_u128,
                            SemanticRvalueKindV1::CheckedBinary(
                                SemanticCheckedBinaryRvalueV1::new(
                                    SemanticCheckedBinaryOpV1::Multiply,
                                    widened_left.clone(),
                                    widened_right.clone(),
                                ),
                            ),
                        ),
                    ],
                    SemanticTerminatorKindV1::Assert {
                        condition: checked_field_operand(5, 1, BOOL_TYPE),
                        expected: false,
                        message: SemanticAssertMessageV1::Overflow {
                            operation: SemanticBinaryOpV1::Multiply,
                            left: widened_left,
                            right: widened_right,
                        },
                        target: cfg_edge(SemanticEdgeRoleV1::AssertSuccess, 1),
                        unwind: SemanticUnwindActionV1::Unreachable,
                    },
                ),
                block(252, vec![], SemanticTerminatorKindV1::Return),
            ],
            vec![
                local(180, U64_TYPE, SemanticLocalRoleV1::Return),
                local(181, U64_TYPE, SemanticLocalRoleV1::Argument(0)),
                local(182, U64_TYPE, SemanticLocalRoleV1::Argument(1)),
                local(183, U128_TYPE, SemanticLocalRoleV1::Temporary),
                local(184, U128_TYPE, SemanticLocalRoleV1::Temporary),
                local(185, checked_u128, SemanticLocalRoleV1::Temporary),
            ],
        );
        let left = typed_operand(1, U64_TYPE);
        let right = typed_operand(2, U64_TYPE);
        let source_use = ScalarAssignmentSiteV1 {
            block: 0,
            statement: 0,
        };
        let use_site = ScalarAssignmentSiteV1 {
            block: 1,
            statement: 0,
        };
        let mut proof = SemanticAssertProofsV1::new(&types, &function).unwrap();
        assert_eq!(
            proof
                .explicit_checked_product_maximum_v1(
                    &left, source_use, &right, source_use, use_site, None,
                )
                .unwrap(),
            Some(u128::MAX),
        );
        let mut proof = SemanticAssertProofsV1::new(&types, &function).unwrap();
        assert_eq!(
            proof
                .explicit_checked_product_maximum_v1(
                    &left,
                    source_use,
                    &right,
                    source_use,
                    use_site,
                    Some(U64_TYPE),
                )
                .unwrap(),
            None,
        );
    }

    #[test]
    fn projected_enum_ranges_require_the_exact_variant_and_field() {
        let mut types = assertion_proof_types();
        let payload_enum = SemanticTypeIdV1::from_index(types.len() as u32);
        types.push(SemanticTypeDeclV1::new(
            SemanticTypeIdentityV1::from_sha256(bytes(51)),
            SemanticLayoutIdentityV1::from_sha256(bytes(51)),
            SemanticTypeLayoutV1::new(Some(16), 8).unwrap(),
            SemanticTypeShapeV1::enum_type(
                SCALAR_TYPE,
                vec![
                    SemanticEnumVariantV1::new(
                        0,
                        SemanticAggregateTypeV1::new(vec![U64_TYPE]).unwrap(),
                    ),
                    SemanticEnumVariantV1::new(
                        1,
                        SemanticAggregateTypeV1::new(vec![U64_TYPE]).unwrap(),
                    ),
                ],
            )
            .unwrap(),
        ));
        let function = projection_function_with_locals(
            vec![block(
                204,
                vec![typed_assignment(
                    1,
                    payload_enum,
                    SemanticRvalueKindV1::Aggregate(
                        SemanticAggregateRvalueV1::new(
                            SemanticAggregateKindV1::EnumVariant(1),
                            vec![typed_constant(U64_TYPE, 7, 8)],
                        )
                        .unwrap(),
                    ),
                )],
                SemanticTerminatorKindV1::Return,
            )],
            vec![
                local(204, U64_TYPE, SemanticLocalRoleV1::Return),
                local(205, payload_enum, SemanticLocalRoleV1::Temporary),
            ],
        );
        let projected = |variant, field| {
            SemanticOperandV1::Copy(
                SemanticPlaceV1::new(
                    SemanticLocalIdV1::from_index(1),
                    vec![
                        SemanticProjectionV1::new(
                            SemanticProjectionKindV1::Downcast(variant),
                            payload_enum,
                        )
                        .unwrap(),
                        SemanticProjectionV1::new(SemanticProjectionKindV1::Field(field), U64_TYPE)
                            .unwrap(),
                    ],
                    U64_TYPE,
                )
                .unwrap(),
            )
        };

        let mut proof = SemanticAssertProofsV1::new(&types, &function).unwrap();
        assert_eq!(
            proof.range_at_operand(&projected(1, 0), 0, 1).unwrap(),
            Some(UnsignedRangeProofV1::exact(7)),
        );
        for hostile in [projected(0, 0), projected(1, 1)] {
            let mut proof = SemanticAssertProofsV1::new(&types, &function).unwrap();
            assert_eq!(proof.range_at_operand(&hostile, 0, 1).unwrap(), None);
        }
    }

    #[derive(Clone, Copy)]
    enum QuotientBoundHostilityV1 {
        Exact,
        RejectingEdge,
        NonDominating,
        AliasedNumeratorMutation,
        UnstableDivisor,
        MismatchedProduct,
        OverflowableProduct,
    }

    fn checked_field_operand(local: u32, field: u32, ty: SemanticTypeIdV1) -> SemanticOperandV1 {
        SemanticOperandV1::Copy(
            SemanticPlaceV1::new(
                SemanticLocalIdV1::from_index(local),
                vec![
                    SemanticProjectionV1::new(SemanticProjectionKindV1::Field(field), ty).unwrap(),
                ],
                ty,
            )
            .unwrap(),
        )
    }

    fn quotient_bound_function(hostility: QuotientBoundHostilityV1) -> SemanticFunctionDeclV1 {
        let divisor = typed_assignment(
            2,
            U64_TYPE,
            SemanticRvalueKindV1::Use(typed_constant(U64_TYPE, 4, 8)),
        );
        let other_divisor = typed_assignment(
            9,
            U64_TYPE,
            SemanticRvalueKindV1::Use(typed_constant(U64_TYPE, 3, 8)),
        );
        let checked_product = typed_assignment(
            4,
            CHECKED_U64_TYPE,
            SemanticRvalueKindV1::CheckedBinary(SemanticCheckedBinaryRvalueV1::new(
                SemanticCheckedBinaryOpV1::Multiply,
                typed_operand(3, U64_TYPE),
                typed_operand(
                    if matches!(hostility, QuotientBoundHostilityV1::MismatchedProduct) {
                        9
                    } else {
                        2
                    },
                    U64_TYPE,
                ),
            )),
        );
        let unprotected_product = typed_assignment(
            5,
            U64_TYPE,
            SemanticRvalueKindV1::Binary {
                operation: SemanticBinaryOpV1::Multiply,
                left: typed_operand(3, U64_TYPE),
                right: typed_operand(2, U64_TYPE),
            },
        );
        let product_result = typed_assignment(
            5,
            U64_TYPE,
            SemanticRvalueKindV1::Use(checked_field_operand(4, 0, U64_TYPE)),
        );
        let mut guard_statements =
            vec![
                if matches!(hostility, QuotientBoundHostilityV1::OverflowableProduct) {
                    unprotected_product
                } else {
                    product_result
                },
            ];
        let tested_numerator = if matches!(
            hostility,
            QuotientBoundHostilityV1::AliasedNumeratorMutation
        ) {
            guard_statements.extend([
                typed_assignment(
                    10,
                    U64_TYPE,
                    SemanticRvalueKindV1::Use(typed_operand(1, U64_TYPE)),
                ),
                typed_assignment(
                    1,
                    U64_TYPE,
                    SemanticRvalueKindV1::Use(typed_constant(U64_TYPE, 0, 8)),
                ),
            ]);
            10
        } else {
            1
        };
        guard_statements.push(typed_assignment(
            6,
            BOOL_TYPE,
            SemanticRvalueKindV1::Binary {
                operation: SemanticBinaryOpV1::LessThan,
                left: typed_operand(tested_numerator, U64_TYPE),
                right: typed_operand(5, U64_TYPE),
            },
        ));
        let (false_target, true_target) =
            if matches!(hostility, QuotientBoundHostilityV1::RejectingEdge) {
                (3, 4)
            } else {
                (4, 3)
            };
        let mut quotient_statements = Vec::new();
        if matches!(hostility, QuotientBoundHostilityV1::UnstableDivisor) {
            quotient_statements.push(typed_assignment(
                2,
                U64_TYPE,
                SemanticRvalueKindV1::Use(typed_constant(U64_TYPE, 5, 8)),
            ));
        }
        quotient_statements.push(typed_assignment(
            7,
            U64_TYPE,
            SemanticRvalueKindV1::Binary {
                operation: SemanticBinaryOpV1::Divide,
                left: typed_operand(1, U64_TYPE),
                right: typed_operand(2, U64_TYPE),
            },
        ));
        let entry = if matches!(hostility, QuotientBoundHostilityV1::NonDominating) {
            zero_switch(8, BOOL_TYPE, 1, 3)
        } else {
            SemanticTerminatorKindV1::Goto(cfg_edge(SemanticEdgeRoleV1::Goto, 1))
        };
        let product_terminator =
            if matches!(hostility, QuotientBoundHostilityV1::OverflowableProduct) {
                SemanticTerminatorKindV1::Goto(cfg_edge(SemanticEdgeRoleV1::Goto, 2))
            } else {
                SemanticTerminatorKindV1::Assert {
                    condition: checked_field_operand(4, 1, BOOL_TYPE),
                    expected: false,
                    message: SemanticAssertMessageV1::Overflow {
                        operation: SemanticBinaryOpV1::Multiply,
                        left: typed_operand(3, U64_TYPE),
                        right: typed_operand(
                            if matches!(hostility, QuotientBoundHostilityV1::MismatchedProduct) {
                                9
                            } else {
                                2
                            },
                            U64_TYPE,
                        ),
                    },
                    target: cfg_edge(SemanticEdgeRoleV1::AssertSuccess, 2),
                    unwind: SemanticUnwindActionV1::Unreachable,
                }
            };
        projection_function_with_locals(
            vec![
                block(206, vec![divisor, other_divisor], entry),
                block(
                    207,
                    if matches!(hostility, QuotientBoundHostilityV1::OverflowableProduct) {
                        vec![]
                    } else {
                        vec![checked_product]
                    },
                    product_terminator,
                ),
                block(
                    208,
                    guard_statements,
                    zero_switch(6, BOOL_TYPE, false_target, true_target),
                ),
                block(209, quotient_statements, SemanticTerminatorKindV1::Return),
                block(210, vec![], SemanticTerminatorKindV1::Return),
            ],
            vec![
                local(206, U64_TYPE, SemanticLocalRoleV1::Return),
                local(207, U64_TYPE, SemanticLocalRoleV1::Argument(0)),
                local(208, U64_TYPE, SemanticLocalRoleV1::Temporary),
                local(209, U64_TYPE, SemanticLocalRoleV1::Argument(1)),
                local(210, CHECKED_U64_TYPE, SemanticLocalRoleV1::Temporary),
                local(211, U64_TYPE, SemanticLocalRoleV1::Temporary),
                local(212, BOOL_TYPE, SemanticLocalRoleV1::Temporary),
                local(213, U64_TYPE, SemanticLocalRoleV1::Temporary),
                local(214, BOOL_TYPE, SemanticLocalRoleV1::Argument(2)),
                local(215, U64_TYPE, SemanticLocalRoleV1::Temporary),
                local(216, U64_TYPE, SemanticLocalRoleV1::Temporary),
            ],
        )
    }

    #[test]
    fn quotient_product_bounds_require_exact_total_dominating_stable_sources() {
        let types = assertion_proof_types();
        let exact = quotient_bound_function(QuotientBoundHostilityV1::Exact);
        let mut proof = SemanticAssertProofsV1::new(&types, &exact).unwrap();
        assert_eq!(
            proof
                .quotient_strict_product_upper_bound_v1(
                    &typed_operand(1, U64_TYPE),
                    &typed_operand(2, U64_TYPE),
                    ScalarAssignmentSiteV1 {
                        block: 3,
                        statement: 0,
                    },
                )
                .unwrap()
                .map(|bound| bound.maximum),
            Some(u128::from(u64::MAX) - 1),
        );

        for hostility in [
            QuotientBoundHostilityV1::RejectingEdge,
            QuotientBoundHostilityV1::NonDominating,
            QuotientBoundHostilityV1::AliasedNumeratorMutation,
            QuotientBoundHostilityV1::UnstableDivisor,
            QuotientBoundHostilityV1::MismatchedProduct,
            QuotientBoundHostilityV1::OverflowableProduct,
        ] {
            let function = quotient_bound_function(hostility);
            let quotient_statement = function.blocks()[3].statements().len() - 1;
            let mut proof = SemanticAssertProofsV1::new(&types, &function).unwrap();
            assert!(
                proof
                    .quotient_strict_product_upper_bound_v1(
                        &typed_operand(1, U64_TYPE),
                        &typed_operand(2, U64_TYPE),
                        ScalarAssignmentSiteV1 {
                            block: 3,
                            statement: quotient_statement,
                        },
                    )
                    .unwrap()
                    .is_none(),
            );
        }
    }

    #[derive(Clone, Copy, Debug)]
    enum ScaledRemainderHostilityV1 {
        Exact,
        WrongNumerator,
        WrongDivisorExtent,
        WrongDivisorScale,
        UnstableNumerator,
        UnstableExtent,
        UnstableScale,
        MissingSumAssertion,
        MissingHeadAssertion,
        RejectingDivisibilityEdge,
        NonDominatingDivisibilityEdge,
        MismatchedDivisibilityScale,
        OffsetNotBelowScale,
        ZeroDivisor,
    }

    fn checked_overflow_terminator(
        result: u32,
        operation: SemanticBinaryOpV1,
        left: SemanticOperandV1,
        right: SemanticOperandV1,
        target: u32,
    ) -> SemanticTerminatorKindV1 {
        SemanticTerminatorKindV1::Assert {
            condition: checked_field_operand(result, 1, BOOL_TYPE),
            expected: false,
            message: SemanticAssertMessageV1::Overflow {
                operation,
                left,
                right,
            },
            target: cfg_edge(SemanticEdgeRoleV1::AssertSuccess, target),
            unwind: SemanticUnwindActionV1::Unreachable,
        }
    }

    fn literal_subtraction_query_position_function() -> SemanticFunctionDeclV1 {
        let capacity = || typed_constant(U64_TYPE, 8_192, 8);
        projection_function_with_locals(
            vec![
                block(
                    201,
                    vec![
                        typed_assignment(
                            3,
                            U64_TYPE,
                            SemanticRvalueKindV1::Cast {
                                kind: SemanticCastKindV1::Integer,
                                operand: typed_operand(1, SCALAR_TYPE),
                            },
                        ),
                        typed_assignment(
                            4,
                            BOOL_TYPE,
                            SemanticRvalueKindV1::Binary {
                                operation: SemanticBinaryOpV1::LessOrEqual,
                                left: typed_operand(3, U64_TYPE),
                                right: capacity(),
                            },
                        ),
                    ],
                    zero_switch(4, BOOL_TYPE, 4, 1),
                ),
                block(
                    202,
                    vec![typed_assignment(
                        5,
                        CHECKED_U64_TYPE,
                        SemanticRvalueKindV1::CheckedBinary(SemanticCheckedBinaryRvalueV1::new(
                            SemanticCheckedBinaryOpV1::Subtract,
                            capacity(),
                            typed_operand(3, U64_TYPE),
                        )),
                    )],
                    checked_overflow_terminator(
                        5,
                        SemanticBinaryOpV1::Subtract,
                        capacity(),
                        typed_operand(3, U64_TYPE),
                        2,
                    ),
                ),
                block(
                    203,
                    vec![
                        typed_assignment(
                            6,
                            U64_TYPE,
                            SemanticRvalueKindV1::Use(checked_field_operand(5, 0, U64_TYPE)),
                        ),
                        typed_assignment(
                            7,
                            BOOL_TYPE,
                            SemanticRvalueKindV1::Binary {
                                operation: SemanticBinaryOpV1::LessThan,
                                left: typed_operand(2, U64_TYPE),
                                right: typed_operand(6, U64_TYPE),
                            },
                        ),
                    ],
                    zero_switch(7, BOOL_TYPE, 4, 3),
                ),
                block(
                    204,
                    vec![typed_assignment(
                        8,
                        CHECKED_U64_TYPE,
                        SemanticRvalueKindV1::CheckedBinary(SemanticCheckedBinaryRvalueV1::new(
                            SemanticCheckedBinaryOpV1::Add,
                            typed_operand(3, U64_TYPE),
                            typed_operand(2, U64_TYPE),
                        )),
                    )],
                    checked_overflow_terminator(
                        8,
                        SemanticBinaryOpV1::Add,
                        typed_operand(3, U64_TYPE),
                        typed_operand(2, U64_TYPE),
                        4,
                    ),
                ),
                block(205, vec![], SemanticTerminatorKindV1::Return),
            ],
            vec![
                local(210, U64_TYPE, SemanticLocalRoleV1::Return),
                local(211, SCALAR_TYPE, SemanticLocalRoleV1::Argument(0)),
                local(212, U64_TYPE, SemanticLocalRoleV1::Argument(1)),
                local(213, U64_TYPE, SemanticLocalRoleV1::Temporary),
                local(214, BOOL_TYPE, SemanticLocalRoleV1::Temporary),
                local(215, CHECKED_U64_TYPE, SemanticLocalRoleV1::Temporary),
                local(216, U64_TYPE, SemanticLocalRoleV1::Temporary),
                local(217, BOOL_TYPE, SemanticLocalRoleV1::Temporary),
                local(218, CHECKED_U64_TYPE, SemanticLocalRoleV1::Temporary),
            ],
        )
    }

    #[test]
    fn authenticated_literal_subtraction_bounds_paged_query_position() {
        let types = assertion_proof_types();
        let function = literal_subtraction_query_position_function();
        let mut proof = SemanticAssertProofsV1::new(&types, &function).unwrap();
        assert_eq!(
            proof
                .range_at_operand(&typed_operand(6, U64_TYPE), 3, 0)
                .unwrap(),
            Some(UnsignedRangeProofV1 {
                minimum: 0,
                maximum: 8_192
            }),
        );
        let proved = SemanticAssertProofsV1::analyze(&types, &function).unwrap();
        assert!(
            proved[1],
            "the exact Le guard proves the producer subtraction"
        );
        assert!(
            proved[3],
            "the bounded subtraction result proves the later addition"
        );
    }

    #[derive(Clone, Copy, Debug)]
    enum LiteralSubtractionSuccessHostilityV1 {
        Exact,
        MissingAssertion,
        NonDominatingAssertion,
        WrongExpected,
        WrongMessageOperation,
        WrongMessageRight,
        WrongConditionCarrier,
        UnwindContinue,
        MutatedCarrier,
        EscapedCarrier,
        UnmatchedOperation,
        BeforeSuccess,
    }

    fn literal_subtraction_success_function(
        minuend: u64,
        hostility: LiteralSubtractionSuccessHostilityV1,
    ) -> SemanticFunctionDeclV1 {
        use LiteralSubtractionSuccessHostilityV1 as H;
        let left = || typed_constant(U64_TYPE, u128::from(minuend), 8);
        let operation = if matches!(hostility, H::UnmatchedOperation) {
            SemanticCheckedBinaryOpV1::Add
        } else {
            SemanticCheckedBinaryOpV1::Subtract
        };
        let mut producer = vec![typed_assignment(
            2,
            CHECKED_U64_TYPE,
            SemanticRvalueKindV1::CheckedBinary(SemanticCheckedBinaryRvalueV1::new(
                operation,
                left(),
                typed_operand(1, U64_TYPE),
            )),
        )];
        if matches!(hostility, H::EscapedCarrier) {
            producer.push(typed_assignment(
                6,
                CHECKED_U64_POINTER_TYPE,
                SemanticRvalueKindV1::AddressOf {
                    mutability: SemanticMutabilityV1::Mutable,
                    place: typed_place(2, CHECKED_U64_TYPE),
                },
            ));
        }
        let assertion = if matches!(hostility, H::MissingAssertion) {
            SemanticTerminatorKindV1::Goto(cfg_edge(SemanticEdgeRoleV1::Goto, 2))
        } else {
            SemanticTerminatorKindV1::Assert {
                condition: checked_field_operand(
                    if matches!(hostility, H::WrongConditionCarrier) {
                        5
                    } else {
                        2
                    },
                    1,
                    BOOL_TYPE,
                ),
                expected: matches!(hostility, H::WrongExpected),
                message: SemanticAssertMessageV1::Overflow {
                    operation: if matches!(
                        hostility,
                        H::WrongMessageOperation | H::UnmatchedOperation
                    ) {
                        SemanticBinaryOpV1::Add
                    } else {
                        SemanticBinaryOpV1::Subtract
                    },
                    left: left(),
                    right: typed_operand(
                        if matches!(hostility, H::WrongMessageRight) {
                            7
                        } else {
                            1
                        },
                        U64_TYPE,
                    ),
                },
                target: cfg_edge(SemanticEdgeRoleV1::AssertSuccess, 2),
                unwind: if matches!(hostility, H::UnwindContinue) {
                    SemanticUnwindActionV1::Continue
                } else {
                    SemanticUnwindActionV1::Unreachable
                },
            }
        };
        let mut consumer = Vec::new();
        if matches!(hostility, H::MutatedCarrier) {
            consumer.push(typed_assignment(
                2,
                CHECKED_U64_TYPE,
                SemanticRvalueKindV1::Use(typed_operand(5, CHECKED_U64_TYPE)),
            ));
        }
        consumer.push(typed_assignment(
            3,
            U64_TYPE,
            SemanticRvalueKindV1::Use(checked_field_operand(2, 0, U64_TYPE)),
        ));
        projection_function_with_locals(
            vec![
                block(
                    201,
                    producer,
                    if matches!(hostility, H::NonDominatingAssertion) {
                        zero_switch(4, BOOL_TYPE, 1, 2)
                    } else {
                        SemanticTerminatorKindV1::Goto(cfg_edge(SemanticEdgeRoleV1::Goto, 1))
                    },
                ),
                block(202, vec![], assertion),
                block(203, consumer, SemanticTerminatorKindV1::Return),
            ],
            vec![
                local(210, U64_TYPE, SemanticLocalRoleV1::Return),
                local(211, U64_TYPE, SemanticLocalRoleV1::Argument(0)),
                local(212, CHECKED_U64_TYPE, SemanticLocalRoleV1::Temporary),
                local(213, U64_TYPE, SemanticLocalRoleV1::Temporary),
                local(214, BOOL_TYPE, SemanticLocalRoleV1::Argument(1)),
                local(215, CHECKED_U64_TYPE, SemanticLocalRoleV1::Argument(2)),
                local(
                    216,
                    CHECKED_U64_POINTER_TYPE,
                    SemanticLocalRoleV1::Temporary,
                ),
                local(217, U64_TYPE, SemanticLocalRoleV1::Argument(3)),
            ],
        )
    }

    #[test]
    fn authenticated_literal_subtraction_success_bounds_do_not_prove_the_producer() {
        let types = assertion_proof_types();
        for minuend in [0, 1, 8_192, u64::MAX] {
            let function = literal_subtraction_success_function(
                minuend,
                LiteralSubtractionSuccessHostilityV1::Exact,
            );
            let mut proof = SemanticAssertProofsV1::new(&types, &function).unwrap();
            assert_eq!(
                proof
                    .range_at_operand(&typed_operand(3, U64_TYPE), 2, 1)
                    .unwrap(),
                Some(UnsignedRangeProofV1 {
                    minimum: 0,
                    maximum: u128::from(minuend)
                }),
            );
            let proved = SemanticAssertProofsV1::analyze(&types, &function).unwrap();
            assert_eq!(
                proved[1],
                minuend == u64::MAX,
                "post-success facts must not circularly prove the producer"
            );
        }
    }

    #[test]
    fn authenticated_literal_subtraction_requires_exact_stable_dominating_success() {
        use LiteralSubtractionSuccessHostilityV1 as H;
        let types = assertion_proof_types();
        for hostility in [
            H::MissingAssertion,
            H::NonDominatingAssertion,
            H::WrongExpected,
            H::WrongMessageOperation,
            H::WrongMessageRight,
            H::WrongConditionCarrier,
            H::UnwindContinue,
            H::MutatedCarrier,
            H::EscapedCarrier,
            H::UnmatchedOperation,
            H::BeforeSuccess,
        ] {
            let function = literal_subtraction_success_function(8_192, hostility);
            let mut proof = SemanticAssertProofsV1::new(&types, &function).unwrap();
            let actual = if matches!(hostility, H::BeforeSuccess) {
                proof.range_at_operand(&checked_field_operand(2, 0, U64_TYPE), 1, 0)
            } else {
                proof.range_at_operand(
                    &typed_operand(3, U64_TYPE),
                    2,
                    function.blocks()[2].statements().len(),
                )
            }
            .unwrap();
            assert!(
                actual.is_none()
                    || actual
                        == Some(UnsignedRangeProofV1 {
                            minimum: 0,
                            maximum: u128::from(u64::MAX)
                        }),
                "{hostility:?}: {actual:?}"
            );
        }
    }

    #[test]
    fn authenticated_literal_subtraction_rejects_signed_unmatched_and_exhausted_forms() {
        let types = assertion_proof_types();
        let function = literal_subtraction_success_function(
            8_192,
            LiteralSubtractionSuccessHostilityV1::Exact,
        );
        let mut proof = SemanticAssertProofsV1::new(&types, &function).unwrap();
        for (operation, left, right) in [
            (
                SemanticCheckedBinaryOpV1::Subtract,
                typed_constant(U64_TYPE, u128::from(u64::MAX) + 1, 16),
                typed_operand(1, U64_TYPE),
            ),
            (
                SemanticCheckedBinaryOpV1::Subtract,
                typed_constant(I32_TYPE, 8_192, 4),
                typed_operand(1, I32_TYPE),
            ),
            (
                SemanticCheckedBinaryOpV1::Subtract,
                typed_constant(U64_TYPE, 8_192, 8),
                typed_operand(1, SCALAR_TYPE),
            ),
            (
                SemanticCheckedBinaryOpV1::Subtract,
                typed_operand(1, U64_TYPE),
                typed_operand(7, U64_TYPE),
            ),
            (
                SemanticCheckedBinaryOpV1::Add,
                typed_constant(U64_TYPE, 8_192, 8),
                typed_operand(1, U64_TYPE),
            ),
            (
                SemanticCheckedBinaryOpV1::Multiply,
                typed_constant(U64_TYPE, 8_192, 8),
                typed_operand(1, U64_TYPE),
            ),
        ] {
            assert_eq!(
                proof.literal_unsigned_subtraction_upper_range_v1(
                    &SemanticCheckedBinaryRvalueV1::new(operation, left, right)
                ),
                None
            );
        }
        proof.work = MAX_PROJECTED_LOOP_GRAPH_WORK_V1;
        assert!(matches!(
            proof.range_at_operand(&typed_operand(3, U64_TYPE), 2, 1),
            Err(ProductionRankedProjectionErrorV1::Unsupported(
                "uniform induction CFG analysis exceeds its work limit"
            ))
        ));
    }

    fn scaled_remainder_function(hostility: ScaledRemainderHostilityV1) -> SemanticFunctionDeclV1 {
        let (extent, scale, offset) =
            if matches!(hostility, ScaledRemainderHostilityV1::ZeroDivisor) {
                (1, 2, 0)
            } else if matches!(hostility, ScaledRemainderHostilityV1::OffsetNotBelowScale) {
                (8, 2, 2)
            } else {
                (8, 2, 1)
            };
        let alternate = if matches!(
            hostility,
            ScaledRemainderHostilityV1::WrongDivisorScale
                | ScaledRemainderHostilityV1::MismatchedDivisibilityScale
        ) {
            4
        } else {
            10
        };
        let divisor_extent = if matches!(hostility, ScaledRemainderHostilityV1::WrongDivisorExtent)
        {
            17
        } else {
            2
        };
        let divisor_scale = if matches!(hostility, ScaledRemainderHostilityV1::WrongDivisorScale) {
            17
        } else {
            3
        };
        let scaled_numerator = if matches!(hostility, ScaledRemainderHostilityV1::WrongNumerator) {
            16
        } else {
            1
        };

        let scaled_left = typed_operand(scaled_numerator, U64_TYPE);
        let scaled_right = typed_operand(3, U64_TYPE);
        let sum_left = typed_operand(8, U64_TYPE);
        let sum_right = typed_operand(4, U64_TYPE);
        let head_left = typed_operand(6, U64_TYPE);
        let head_right = typed_operand(2, U64_TYPE);
        let mut guard_statements = vec![typed_assignment(
            12,
            U64_TYPE,
            SemanticRvalueKindV1::Use(checked_field_operand(11, 0, U64_TYPE)),
        )];
        match hostility {
            ScaledRemainderHostilityV1::UnstableNumerator => {
                guard_statements.push(typed_assignment(
                    1,
                    U64_TYPE,
                    SemanticRvalueKindV1::Use(typed_constant(U64_TYPE, 0, 8)),
                ))
            }
            ScaledRemainderHostilityV1::UnstableExtent => guard_statements.push(typed_assignment(
                2,
                U64_TYPE,
                SemanticRvalueKindV1::Use(typed_constant(U64_TYPE, 9, 8)),
            )),
            ScaledRemainderHostilityV1::UnstableScale => guard_statements.push(typed_assignment(
                3,
                U64_TYPE,
                SemanticRvalueKindV1::Use(typed_constant(U64_TYPE, 4, 8)),
            )),
            _ => {}
        }
        guard_statements.extend([
            typed_assignment(
                13,
                U64_TYPE,
                SemanticRvalueKindV1::Binary {
                    operation: SemanticBinaryOpV1::Remainder,
                    left: typed_operand(2, U64_TYPE),
                    right: typed_operand(
                        if matches!(
                            hostility,
                            ScaledRemainderHostilityV1::MismatchedDivisibilityScale
                        ) {
                            17
                        } else {
                            3
                        },
                        U64_TYPE,
                    ),
                },
            ),
            typed_assignment(
                14,
                BOOL_TYPE,
                SemanticRvalueKindV1::Binary {
                    operation: SemanticBinaryOpV1::Equal,
                    left: typed_operand(13, U64_TYPE),
                    right: typed_constant(U64_TYPE, 0, 8),
                },
            ),
        ]);
        let guard = match hostility {
            ScaledRemainderHostilityV1::RejectingDivisibilityEdge => {
                zero_switch(14, BOOL_TYPE, 4, 5)
            }
            ScaledRemainderHostilityV1::NonDominatingDivisibilityEdge => {
                zero_switch(14, BOOL_TYPE, 6, 4)
            }
            _ => zero_switch(14, BOOL_TYPE, 5, 4),
        };

        projection_function_with_locals(
            vec![
                block(
                    217,
                    vec![
                        typed_assignment(
                            2,
                            U64_TYPE,
                            SemanticRvalueKindV1::Use(typed_constant(U64_TYPE, extent, 8)),
                        ),
                        typed_assignment(
                            3,
                            U64_TYPE,
                            SemanticRvalueKindV1::Use(typed_constant(U64_TYPE, scale, 8)),
                        ),
                        typed_assignment(
                            4,
                            U64_TYPE,
                            SemanticRvalueKindV1::Use(typed_constant(U64_TYPE, offset, 8)),
                        ),
                        typed_assignment(
                            17,
                            U64_TYPE,
                            SemanticRvalueKindV1::Use(typed_constant(U64_TYPE, alternate, 8)),
                        ),
                        typed_assignment(
                            5,
                            U64_TYPE,
                            SemanticRvalueKindV1::Binary {
                                operation: SemanticBinaryOpV1::Divide,
                                left: typed_operand(divisor_extent, U64_TYPE),
                                right: typed_operand(divisor_scale, U64_TYPE),
                            },
                        ),
                        typed_assignment(
                            6,
                            U64_TYPE,
                            SemanticRvalueKindV1::Binary {
                                operation: SemanticBinaryOpV1::Divide,
                                left: typed_operand(1, U64_TYPE),
                                right: typed_operand(5, U64_TYPE),
                            },
                        ),
                        typed_assignment(
                            7,
                            CHECKED_U64_TYPE,
                            SemanticRvalueKindV1::CheckedBinary(
                                SemanticCheckedBinaryRvalueV1::new(
                                    SemanticCheckedBinaryOpV1::Multiply,
                                    scaled_left.clone(),
                                    scaled_right.clone(),
                                ),
                            ),
                        ),
                    ],
                    checked_overflow_terminator(
                        7,
                        SemanticBinaryOpV1::Multiply,
                        scaled_left,
                        scaled_right,
                        1,
                    ),
                ),
                block(
                    218,
                    vec![
                        typed_assignment(
                            8,
                            U64_TYPE,
                            SemanticRvalueKindV1::Use(checked_field_operand(7, 0, U64_TYPE)),
                        ),
                        typed_assignment(
                            9,
                            CHECKED_U64_TYPE,
                            SemanticRvalueKindV1::CheckedBinary(
                                SemanticCheckedBinaryRvalueV1::new(
                                    SemanticCheckedBinaryOpV1::Add,
                                    sum_left.clone(),
                                    sum_right.clone(),
                                ),
                            ),
                        ),
                    ],
                    if matches!(hostility, ScaledRemainderHostilityV1::MissingSumAssertion) {
                        SemanticTerminatorKindV1::Goto(cfg_edge(SemanticEdgeRoleV1::Goto, 2))
                    } else {
                        checked_overflow_terminator(
                            9,
                            SemanticBinaryOpV1::Add,
                            sum_left,
                            sum_right,
                            2,
                        )
                    },
                ),
                block(
                    219,
                    vec![
                        typed_assignment(
                            10,
                            U64_TYPE,
                            SemanticRvalueKindV1::Use(checked_field_operand(9, 0, U64_TYPE)),
                        ),
                        typed_assignment(
                            11,
                            CHECKED_U64_TYPE,
                            SemanticRvalueKindV1::CheckedBinary(
                                SemanticCheckedBinaryRvalueV1::new(
                                    SemanticCheckedBinaryOpV1::Multiply,
                                    head_left.clone(),
                                    head_right.clone(),
                                ),
                            ),
                        ),
                    ],
                    if matches!(hostility, ScaledRemainderHostilityV1::MissingHeadAssertion) {
                        SemanticTerminatorKindV1::Goto(cfg_edge(SemanticEdgeRoleV1::Goto, 3))
                    } else {
                        checked_overflow_terminator(
                            11,
                            SemanticBinaryOpV1::Multiply,
                            head_left,
                            head_right,
                            3,
                        )
                    },
                ),
                block(220, guard_statements, guard),
                block(
                    221,
                    vec![typed_assignment(
                        15,
                        CHECKED_U64_TYPE,
                        SemanticRvalueKindV1::CheckedBinary(SemanticCheckedBinaryRvalueV1::new(
                            SemanticCheckedBinaryOpV1::Subtract,
                            typed_operand(10, U64_TYPE),
                            typed_operand(12, U64_TYPE),
                        )),
                    )],
                    checked_overflow_terminator(
                        15,
                        SemanticBinaryOpV1::Subtract,
                        typed_operand(10, U64_TYPE),
                        typed_operand(12, U64_TYPE),
                        5,
                    ),
                ),
                block(222, vec![], SemanticTerminatorKindV1::Return),
                block(
                    223,
                    vec![],
                    SemanticTerminatorKindV1::Goto(cfg_edge(SemanticEdgeRoleV1::Goto, 4)),
                ),
            ],
            vec![
                local(217, U64_TYPE, SemanticLocalRoleV1::Return),
                local(218, U64_TYPE, SemanticLocalRoleV1::Argument(0)),
                local(219, U64_TYPE, SemanticLocalRoleV1::Temporary),
                local(220, U64_TYPE, SemanticLocalRoleV1::Temporary),
                local(221, U64_TYPE, SemanticLocalRoleV1::Temporary),
                local(222, U64_TYPE, SemanticLocalRoleV1::Temporary),
                local(223, U64_TYPE, SemanticLocalRoleV1::Temporary),
                local(224, CHECKED_U64_TYPE, SemanticLocalRoleV1::Temporary),
                local(225, U64_TYPE, SemanticLocalRoleV1::Temporary),
                local(226, CHECKED_U64_TYPE, SemanticLocalRoleV1::Temporary),
                local(227, U64_TYPE, SemanticLocalRoleV1::Temporary),
                local(228, CHECKED_U64_TYPE, SemanticLocalRoleV1::Temporary),
                local(229, U64_TYPE, SemanticLocalRoleV1::Temporary),
                local(230, U64_TYPE, SemanticLocalRoleV1::Temporary),
                local(231, BOOL_TYPE, SemanticLocalRoleV1::Temporary),
                local(232, CHECKED_U64_TYPE, SemanticLocalRoleV1::Temporary),
                local(233, U64_TYPE, SemanticLocalRoleV1::Argument(1)),
                local(234, U64_TYPE, SemanticLocalRoleV1::Temporary),
            ],
        )
    }

    fn proves_scaled_remainder_subtract_v1(proof: &mut SemanticAssertProofsV1<'_>) -> bool {
        let (condition, expected, message) = match proof.function.blocks()[4].terminator().kind() {
            SemanticTerminatorKindV1::Assert {
                condition,
                expected,
                message,
                ..
            } => (condition.clone(), *expected, message.clone()),
            _ => unreachable!("scaled-remainder fixture retains a checked subtraction"),
        };
        proof
            .proves_checked_overflow_assert_v1(&condition, expected, &message, 4)
            .unwrap()
    }

    #[test]
    fn scaled_quotient_remainder_requires_exact_checked_stable_guarded_sources() {
        let types = assertion_proof_types();
        let use_site = ScalarAssignmentSiteV1 {
            block: 4,
            statement: 0,
        };
        let left = typed_operand(10, U64_TYPE);
        let right = typed_operand(12, U64_TYPE);

        let exact = scaled_remainder_function(ScaledRemainderHostilityV1::Exact);
        let mut proof = SemanticAssertProofsV1::new(&types, &exact).unwrap();
        assert!(
            proof
                .authenticated_scaled_quotient_remainder_v1(&left, &right, use_site)
                .unwrap()
                .is_some()
        );
        assert_eq!(
            proof
                .scaled_quotient_remainder_upper_range_v1(&left, &right, use_site)
                .unwrap(),
            Some(UnsignedRangeProofV1 {
                minimum: 0,
                maximum: 7,
            })
        );
        assert!(
            proof
                .proves_scaled_quotient_remainder_nonnegative_v1(&left, &right, use_site, 4)
                .unwrap()
        );
        assert!(proves_scaled_remainder_subtract_v1(&mut proof));

        for hostility in [
            ScaledRemainderHostilityV1::WrongNumerator,
            ScaledRemainderHostilityV1::WrongDivisorExtent,
            ScaledRemainderHostilityV1::WrongDivisorScale,
            ScaledRemainderHostilityV1::UnstableNumerator,
            ScaledRemainderHostilityV1::UnstableExtent,
            ScaledRemainderHostilityV1::UnstableScale,
            ScaledRemainderHostilityV1::MissingSumAssertion,
            ScaledRemainderHostilityV1::MissingHeadAssertion,
        ] {
            let function = scaled_remainder_function(hostility);
            let mut proof = SemanticAssertProofsV1::new(&types, &function).unwrap();
            assert!(
                proof
                    .authenticated_scaled_quotient_remainder_v1(&left, &right, use_site)
                    .unwrap()
                    .is_none(),
                "{hostility:?} authenticated substituted scaled-remainder sources",
            );
            assert!(
                !proves_scaled_remainder_subtract_v1(&mut proof),
                "{hostility:?} proved the checked subtraction",
            );
        }

        for hostility in [
            ScaledRemainderHostilityV1::RejectingDivisibilityEdge,
            ScaledRemainderHostilityV1::NonDominatingDivisibilityEdge,
            ScaledRemainderHostilityV1::MismatchedDivisibilityScale,
            ScaledRemainderHostilityV1::ZeroDivisor,
        ] {
            let function = scaled_remainder_function(hostility);
            let mut proof = SemanticAssertProofsV1::new(&types, &function).unwrap();
            assert!(
                proof
                    .authenticated_scaled_quotient_remainder_v1(&left, &right, use_site)
                    .unwrap()
                    .is_some(),
                "{hostility:?} changed the structural arithmetic identity",
            );
            assert!(
                !proof
                    .proves_scaled_quotient_remainder_nonnegative_v1(&left, &right, use_site, 4)
                    .unwrap(),
                "{hostility:?} authenticated a nonnegative subtraction",
            );
            assert!(!proves_scaled_remainder_subtract_v1(&mut proof));
        }

        let offset = scaled_remainder_function(ScaledRemainderHostilityV1::OffsetNotBelowScale);
        let mut proof = SemanticAssertProofsV1::new(&types, &offset).unwrap();
        assert_eq!(
            proof
                .scaled_quotient_remainder_upper_range_v1(&left, &right, use_site)
                .unwrap(),
            None,
        );
        assert!(
            proof
                .proves_scaled_quotient_remainder_nonnegative_v1(&left, &right, use_site, 4)
                .unwrap()
        );
        assert!(proves_scaled_remainder_subtract_v1(&mut proof));
    }

    fn compared_zero_guard_assertion_function(
        operation: SemanticBinaryOpV1,
        compared_value: u128,
    ) -> SemanticFunctionDeclV1 {
        let comparison = |destination| {
            typed_assignment(
                destination,
                BOOL_TYPE,
                SemanticRvalueKindV1::Binary {
                    operation,
                    left: typed_operand(1, U64_TYPE),
                    right: typed_constant(U64_TYPE, compared_value, 8),
                },
            )
        };
        let (false_target, true_target) = match operation {
            SemanticBinaryOpV1::Equal => (1, 2),
            SemanticBinaryOpV1::NotEqual => (2, 1),
            _ => unreachable!("fixture admits only equality comparisons"),
        };
        projection_function_with_locals(
            vec![
                block(
                    158,
                    vec![comparison(2)],
                    zero_switch(2, BOOL_TYPE, false_target, true_target),
                ),
                block(
                    159,
                    vec![typed_assignment(
                        3,
                        BOOL_TYPE,
                        SemanticRvalueKindV1::Binary {
                            operation: SemanticBinaryOpV1::Equal,
                            left: typed_operand(1, U64_TYPE),
                            right: typed_constant(U64_TYPE, 0, 8),
                        },
                    )],
                    SemanticTerminatorKindV1::Assert {
                        condition: typed_operand(3, BOOL_TYPE),
                        expected: false,
                        message: SemanticAssertMessageV1::RemainderByZero(typed_operand(
                            1, U64_TYPE,
                        )),
                        target: cfg_edge(SemanticEdgeRoleV1::AssertSuccess, 3),
                        unwind: SemanticUnwindActionV1::Unreachable,
                    },
                ),
                block(160, vec![], SemanticTerminatorKindV1::Return),
                block(161, vec![], SemanticTerminatorKindV1::Return),
            ],
            vec![
                local(158, SCALAR_TYPE, SemanticLocalRoleV1::Return),
                local(159, U64_TYPE, SemanticLocalRoleV1::Argument(0)),
                local(160, BOOL_TYPE, SemanticLocalRoleV1::Temporary),
                local(161, BOOL_TYPE, SemanticLocalRoleV1::Temporary),
            ],
        )
    }

    #[test]
    fn compared_zero_guard_dominates_fresh_rust_remainder_assertion() {
        let types = assertion_proof_types();
        for operation in [SemanticBinaryOpV1::Equal, SemanticBinaryOpV1::NotEqual] {
            let function = compared_zero_guard_assertion_function(operation, 0);
            assert!(SemanticAssertProofsV1::analyze(&types, &function).unwrap()[1]);
        }
        let wrong_constant = compared_zero_guard_assertion_function(SemanticBinaryOpV1::Equal, 1);
        assert!(!SemanticAssertProofsV1::analyze(&types, &wrong_constant).unwrap()[1]);
    }

