    #[derive(Clone, Copy)]
    enum WidenedLatchKind {
        Ordinary,
        Unchecked,
        Checked,
        CheckedWrongMessage,
        CheckedExpectedOverflow,
        CheckedReachableUnwind,
    }

    fn widened_u64_induction_function(step: u64) -> SemanticFunctionDeclV1 {
        widened_u64_induction_function_with_latch(step, WidenedLatchKind::Ordinary)
    }

    fn widened_u64_induction_function_with_latch(
        step: u64,
        latch_kind: WidenedLatchKind,
    ) -> SemanticFunctionDeclV1 {
        let induction = SemanticLocalIdV1::from_index(1);
        let predicate = SemanticLocalIdV1::from_index(2);
        let bound = SemanticLocalIdV1::from_index(3);
        let narrow_bound = SemanticLocalIdV1::from_index(4);
        let checked_result = SemanticLocalIdV1::from_index(5);
        let checked_alias = SemanticLocalIdV1::from_index(6);
        let u64_place = |local| SemanticPlaceV1::new(local, vec![], U64_TYPE).unwrap();
        let u32_place = |local| SemanticPlaceV1::new(local, vec![], SCALAR_TYPE).unwrap();
        let u64_operand = |local| SemanticOperandV1::Copy(u64_place(local));
        let u32_operand = |local| SemanticOperandV1::Copy(u32_place(local));
        let checked_field = |field, ty| {
            SemanticOperandV1::Move(
                SemanticPlaceV1::new(
                    checked_result,
                    vec![
                        SemanticProjectionV1::new(SemanticProjectionKindV1::Field(field), ty)
                            .unwrap(),
                    ],
                    ty,
                )
                .unwrap(),
            )
        };
        let assign = |destination: SemanticPlaceV1,
                      result_type: SemanticTypeIdV1,
                      value: SemanticRvalueKindV1| {
            statement(SemanticStatementKindV1::Assign(SemanticAssignmentV1::new(
                destination,
                SemanticRvalueV1::new(result_type, value),
            )))
        };
        let switch = SemanticTerminatorKindV1::SwitchInt {
            discriminant: u32_operand(predicate),
            targets: SemanticSwitchTargetsV1::new(
                vec![SemanticSwitchTargetV1::new(
                    0,
                    cfg_edge(SemanticEdgeRoleV1::SwitchValue, 5),
                )],
                cfg_edge(SemanticEdgeRoleV1::SwitchOtherwise, 2),
            )
            .unwrap(),
        };
        let step_operand = || typed_constant(U64_TYPE, u128::from(step), 8);
        let (producer_statements, producer_terminator, latch_statements) = match latch_kind {
            WidenedLatchKind::Ordinary => (
                vec![],
                SemanticTerminatorKindV1::Goto(cfg_edge(SemanticEdgeRoleV1::Goto, 4)),
                vec![assign(
                    u64_place(induction),
                    U64_TYPE,
                    SemanticRvalueKindV1::Binary {
                        operation: SemanticBinaryOpV1::Add,
                        left: u64_operand(induction),
                        right: step_operand(),
                    },
                )],
            ),
            WidenedLatchKind::Unchecked => (
                vec![],
                SemanticTerminatorKindV1::Goto(cfg_edge(SemanticEdgeRoleV1::Goto, 4)),
                vec![assign(
                    u64_place(induction),
                    U64_TYPE,
                    SemanticRvalueKindV1::UncheckedBinary(SemanticUncheckedBinaryRvalueV1::new(
                        SemanticUncheckedBinaryOpV1::Add,
                        u64_operand(induction),
                        step_operand(),
                    )),
                )],
            ),
            WidenedLatchKind::Checked
            | WidenedLatchKind::CheckedWrongMessage
            | WidenedLatchKind::CheckedExpectedOverflow
            | WidenedLatchKind::CheckedReachableUnwind => {
                let checked_left = u64_operand(checked_alias);
                let checked_right = step_operand();
                (
                    vec![
                        assign(
                            u64_place(checked_alias),
                            U64_TYPE,
                            SemanticRvalueKindV1::Use(u64_operand(induction)),
                        ),
                        assign(
                            SemanticPlaceV1::new(checked_result, vec![], CHECKED_U64_TYPE).unwrap(),
                            CHECKED_U64_TYPE,
                            SemanticRvalueKindV1::CheckedBinary(
                                SemanticCheckedBinaryRvalueV1::new(
                                    SemanticCheckedBinaryOpV1::Add,
                                    checked_left.clone(),
                                    checked_right.clone(),
                                ),
                            ),
                        ),
                    ],
                    SemanticTerminatorKindV1::Assert {
                        condition: checked_field(1, BOOL_TYPE),
                        expected: matches!(latch_kind, WidenedLatchKind::CheckedExpectedOverflow),
                        message: SemanticAssertMessageV1::Overflow {
                            operation: if matches!(
                                latch_kind,
                                WidenedLatchKind::CheckedWrongMessage
                            ) {
                                SemanticBinaryOpV1::Subtract
                            } else {
                                SemanticBinaryOpV1::Add
                            },
                            left: SemanticOperandV1::Move(u64_place(checked_alias)),
                            right: checked_right,
                        },
                        target: cfg_edge(SemanticEdgeRoleV1::AssertSuccess, 4),
                        unwind: if matches!(latch_kind, WidenedLatchKind::CheckedReachableUnwind) {
                            SemanticUnwindActionV1::Continue
                        } else {
                            SemanticUnwindActionV1::Unreachable
                        },
                    },
                    vec![assign(
                        u64_place(induction),
                        U64_TYPE,
                        SemanticRvalueKindV1::Use(checked_field(0, U64_TYPE)),
                    )],
                )
            }
        };
        projection_function_with_locals(
            vec![
                block(
                    210,
                    vec![
                        assign(
                            u64_place(induction),
                            U64_TYPE,
                            SemanticRvalueKindV1::Use(typed_constant(U64_TYPE, 0, 8)),
                        ),
                        assign(
                            u64_place(bound),
                            U64_TYPE,
                            SemanticRvalueKindV1::Cast {
                                kind: SemanticCastKindV1::Integer,
                                operand: u32_operand(narrow_bound),
                            },
                        ),
                    ],
                    SemanticTerminatorKindV1::Goto(cfg_edge(SemanticEdgeRoleV1::Goto, 1)),
                ),
                block(
                    211,
                    vec![assign(
                        u32_place(predicate),
                        SCALAR_TYPE,
                        SemanticRvalueKindV1::Binary {
                            operation: SemanticBinaryOpV1::LessThan,
                            left: u64_operand(induction),
                            right: u64_operand(bound),
                        },
                    )],
                    switch,
                ),
                block(
                    212,
                    vec![],
                    SemanticTerminatorKindV1::Goto(cfg_edge(SemanticEdgeRoleV1::Goto, 3)),
                ),
                block(213, producer_statements, producer_terminator),
                block(
                    214,
                    latch_statements,
                    SemanticTerminatorKindV1::Goto(cfg_edge(SemanticEdgeRoleV1::Goto, 1)),
                ),
                block(215, vec![], SemanticTerminatorKindV1::Return),
            ],
            vec![
                local(210, U64_TYPE, SemanticLocalRoleV1::Return),
                local(211, U64_TYPE, SemanticLocalRoleV1::Temporary),
                local(212, SCALAR_TYPE, SemanticLocalRoleV1::Temporary),
                local(213, U64_TYPE, SemanticLocalRoleV1::Temporary),
                local(214, SCALAR_TYPE, SemanticLocalRoleV1::Argument(0)),
                local(215, CHECKED_U64_TYPE, SemanticLocalRoleV1::Temporary),
                local(216, U64_TYPE, SemanticLocalRoleV1::Temporary),
            ],
        )
    }

    fn project_test_inductions(
        function: &SemanticFunctionDeclV1,
    ) -> Result<
        (
            Vec<ProjectedUniformInductionV1>,
            Vec<ProductionRankedOperationV1>,
            usize,
        ),
        ProductionRankedProjectionErrorV1,
    > {
        let types = projection_types();
        project_test_inductions_with_types(&types, function)
    }

    fn project_test_inductions_with_types(
        types: &[SemanticTypeDeclV1],
        function: &SemanticFunctionDeclV1,
    ) -> Result<
        (
            Vec<ProjectedUniformInductionV1>,
            Vec<ProductionRankedOperationV1>,
            usize,
        ),
        ProductionRankedProjectionErrorV1,
    > {
        project_test_inductions_with_types_and_callables(types, &[], function)
    }

    fn project_test_inductions_with_types_and_callables(
        types: &[SemanticTypeDeclV1],
        callables: &[SemanticCallableDeclV1],
        function: &SemanticFunctionDeclV1,
    ) -> Result<
        (
            Vec<ProjectedUniformInductionV1>,
            Vec<ProductionRankedOperationV1>,
            usize,
        ),
        ProductionRankedProjectionErrorV1,
    > {
        let constants = constant_locals(function)?;
        let origins = local_stable_argument_origins(types, function).unwrap();
        let definitions = local_definition_counts(function);
        let mut arguments = vec![None; function.locals().len()];
        let mut next_argument = 1;
        let mut operations = Vec::new();
        let mut next_value = 0;
        let mut inductions = project_uniform_inductions_v1(
            callables,
            types,
            function,
            &constants,
            &origins,
            &definitions,
            &mut arguments,
            &mut next_argument,
            &mut operations,
            &mut next_value,
        )?;
        reconcile_source_progress_and_emit_unsigned_casts_v1(
            types,
            function,
            &constants,
            &origins,
            &definitions,
            &arguments,
            &mut inductions,
            &mut operations,
            &mut next_value,
        )?;
        project_induction_body_predicates_v1(
            types,
            function,
            &constants,
            &origins,
            &definitions,
            &mut inductions,
            &mut arguments,
            &mut next_argument,
            &mut operations,
            &mut next_value,
        )?;
        Ok((inductions, operations, next_argument))
    }

    fn assert_incomplete<T>(
        result: Result<T, ProductionRankedProjectionErrorV1>,
        expected: &'static str,
    ) {
        match result {
            Err(ProductionRankedProjectionErrorV1::Incomplete(actual)) => {
                assert_eq!(actual, expected);
            }
            Err(other) => panic!("expected incomplete projection, got {other}"),
            Ok(_) => panic!("expected incomplete projection"),
        }
    }

    fn assert_loop_unsupported<T>(
        result: Result<T, ProductionRankedProjectionErrorV1>,
        expected: &'static str,
    ) {
        match result {
            Err(ProductionRankedProjectionErrorV1::Unsupported(actual)) => {
                assert_eq!(actual, expected);
            }
            Err(other) => panic!("expected unsupported projection, got {other}"),
            Ok(_) => panic!("expected unsupported projection"),
        }
    }

    #[test]
    fn dynamic_parameter_induction_projects_to_legal_ranked_ssa_edges() {
        let function = uniform_induction_function(SemanticLocalRoleV1::Argument(0));
        let constants = constant_locals(&function).unwrap();
        let origins = local_stable_argument_origins(&projection_types(), &function).unwrap();
        let definitions = local_definition_counts(&function);
        let mut arguments = vec![None; function.locals().len()];
        let mut next_argument = 1;
        let mut entry_operations = Vec::new();
        let mut next_value = 0;
        let inductions = project_uniform_inductions_v1(
            &[],
            &projection_types(),
            &function,
            &constants,
            &origins,
            &definitions,
            &mut arguments,
            &mut next_argument,
            &mut entry_operations,
            &mut next_value,
        )
        .unwrap();
        assert_eq!(inductions.len(), 1);

        let (blocks, _, _) = build_ranked_cfg(
            &projection_types(),
            &function,
            &[],
            &vec![None; function.locals().len()],
            &vec![None; function.blocks().len()],
            &inductions,
            entry_operations,
            (0..function.blocks().len())
                .map(|_| ProjectedSemanticBlockV1 { items: vec![] })
                .collect(),
        )
        .unwrap();
        assert_eq!(blocks[2].index_argument_count(), 1);
        assert_eq!(blocks[3].index_argument_count(), 1);
        assert!(matches!(
            blocks[2].terminator(),
            ProductionRankedTerminatorV1::IndexLessThanArgs { .. }
        ));
        assert!(matches!(
            blocks[3].terminator(),
            ProductionRankedTerminatorV1::BranchArgsAddAt { .. }
        ));
        ProductionRankedKernelV1::new("uniform_dynamic_loop", next_argument, blocks).unwrap();
    }

    #[test]
    fn direct_uniform_induction_is_live_only_inside_its_loop() {
        let types = projection_types();
        let function = uniform_induction_function(SemanticLocalRoleV1::Argument(0));
        let (inductions, _, _) = project_test_inductions_with_types(&types, &function).unwrap();
        let induction = typed_operand(1, SCALAR_TYPE);

        assert!(matches!(
            project_pipeline_operand_at(&types, &function, 2, &induction, &inductions),
            Ok(ProjectedPipelineScalarV1::Induction { induction: 0 })
        ));
        assert!(matches!(
            project_pipeline_operand_at(&types, &function, 3, &induction, &inductions),
            Err(ProductionRankedProjectionErrorV1::Incomplete(
                "a pipeline scalar temporary has multiple definitions"
            ))
        ));
    }

    #[test]
    fn optional_uniform_induction_preserves_both_exact_zero_trip_or_header_orientations() {
        for explicit_to_header in [true, false] {
            let function = optional_uniform_induction_function(explicit_to_header);
            let (inductions, switches, operations, next_argument) =
                project_optional_uniform_induction_for_test(&function).unwrap();
            assert_eq!(inductions.len(), 1);
            let projected = switches[0]
                .as_ref()
                .expect("the optional preheader must retain one exact switch");
            assert!(projected.lane_uniform);
            assert_eq!(projected.source_discriminant, typed_operand(4, BOOL_TYPE));
            assert_eq!(projected.targets.len(), 1);

            let (blocks, _, _) = build_ranked_cfg(
                &assertion_proof_types(),
                &function,
                &[],
                &vec![None; function.locals().len()],
                &switches,
                &inductions,
                operations,
                (0..function.blocks().len())
                    .map(|_| ProjectedSemanticBlockV1 { items: vec![] })
                    .collect(),
            )
            .unwrap();
            assert!(matches!(
                blocks[1].terminator(),
                ProductionRankedTerminatorV1::IndexEqualArgs {
                    true_arguments,
                    false_arguments,
                    true_block,
                    false_block,
                    ..
                } if if explicit_to_header {
                    true_arguments.len() == 1
                        && false_arguments.is_empty()
                        && *true_block == 2
                        && *false_block == 4
                } else {
                    true_arguments.is_empty()
                        && false_arguments.len() == 1
                        && *true_block == 4
                        && *false_block == 2
                }
            ));
            ProductionRankedKernelV1::new("optional_uniform_loop", next_argument, blocks).unwrap();
        }
    }

    #[test]
    fn optional_uniform_induction_accepts_only_exact_raw_u32_zero_control() {
        for explicit_to_header in [true, false] {
            for selector in [
                typed_operand(4, SCALAR_TYPE),
                typed_constant(SCALAR_TYPE, 4, 4),
            ] {
                let raw_argument = matches!(&selector, SemanticOperandV1::Copy(_));
                let function = optional_uniform_induction_function_with_selector(
                    explicit_to_header,
                    SCALAR_TYPE,
                    selector.clone(),
                    if raw_argument {
                        SemanticLocalRoleV1::Argument(1)
                    } else {
                        SemanticLocalRoleV1::Temporary
                    },
                    Vec::new(),
                    SemanticTerminatorKindV1::Goto(cfg_edge(SemanticEdgeRoleV1::Goto, 1)),
                    None,
                    Vec::new(),
                    None,
                );
                let (inductions, switches, operations, next_argument) =
                    project_optional_uniform_induction_for_test(&function).unwrap();
                let projected = switches[0]
                    .as_ref()
                    .expect("the raw u32 optional preheader must retain its switch");
                assert!(projected.lane_uniform);
                assert_eq!(projected.source_discriminant, selector);
                assert_eq!(projected.targets[0].0, 0);
                assert!(if raw_argument {
                    matches!(projected.discriminant, ProductionRankedValueV1::Argument(_))
                } else {
                    matches!(projected.discriminant, ProductionRankedValueV1::Local(_))
                });
                let zero = projected.targets[0].1;
                assert!(operations.iter().any(|operation| matches!(
                    operation,
                    ProductionRankedOperationV1::IndexConstant { result, value: 0 }
                        if ProductionRankedValueV1::Local(*result) == zero
                )));

                let (blocks, _, _) = build_ranked_cfg(
                    &assertion_proof_types(),
                    &function,
                    &[],
                    &vec![None; function.locals().len()],
                    &switches,
                    &inductions,
                    operations,
                    (0..function.blocks().len())
                        .map(|_| ProjectedSemanticBlockV1 { items: vec![] })
                        .collect(),
                )
                .unwrap();
                assert!(matches!(
                    blocks[1].terminator(),
                    ProductionRankedTerminatorV1::IndexEqualArgs {
                        lhs,
                        rhs,
                        true_arguments,
                        false_arguments,
                        true_block,
                        false_block,
                    } if *lhs == projected.discriminant
                        && *rhs == zero
                        && if explicit_to_header {
                            true_arguments.len() == 1
                                && false_arguments.is_empty()
                                && *true_block == 2
                                && *false_block == 4
                        } else {
                            true_arguments.is_empty()
                                && false_arguments.len() == 1
                                && *true_block == 4
                                && *false_block == 2
                        }
                ));
                ProductionRankedKernelV1::new("optional_raw_u32_loop", next_argument, blocks)
                    .unwrap();
            }
        }
    }

    #[test]
    fn optional_uniform_induction_rejects_every_non_u32_or_nonraw_integer_selector() {
        let selector_types = optional_selector_types();
        for selector_type in [
            U8_TYPE,
            U16_TYPE,
            U64_TYPE,
            U128_TYPE,
            I32_TYPE,
            CHAR_TYPE,
            F32_TYPE,
            F64_TYPE,
            VALIDITY_U32_TYPE,
            ARRAY_TYPE,
            POINTER_TYPE,
            ENUM_TYPE,
            CHECKED_U64_TYPE,
        ] {
            let function = optional_uniform_induction_function_with_selector(
                false,
                selector_type,
                typed_operand(4, selector_type),
                SemanticLocalRoleV1::Argument(1),
                Vec::new(),
                SemanticTerminatorKindV1::Goto(cfg_edge(SemanticEdgeRoleV1::Goto, 1)),
                None,
                Vec::new(),
                None,
            );
            assert_incomplete(
                project_test_inductions_with_types(&selector_types, &function),
                "an optional uniform induction preheader is not controlled by one exact lane-uniform selector",
            );
        }

        let nonzero_targets = SemanticSwitchTargetsV1::new(
            vec![SemanticSwitchTargetV1::new(
                1,
                cfg_edge(SemanticEdgeRoleV1::SwitchValue, 3),
            )],
            cfg_edge(SemanticEdgeRoleV1::SwitchOtherwise, 1),
        )
        .unwrap();
        let nonzero = optional_uniform_induction_function_with_selector(
            false,
            SCALAR_TYPE,
            typed_operand(4, SCALAR_TYPE),
            SemanticLocalRoleV1::Argument(1),
            Vec::new(),
            SemanticTerminatorKindV1::Goto(cfg_edge(SemanticEdgeRoleV1::Goto, 1)),
            Some(nonzero_targets),
            Vec::new(),
            None,
        );
        assert_incomplete(
            project_test_inductions_with_types(&selector_types, &nonzero),
            "an optional uniform induction preheader is not controlled by one exact lane-uniform selector",
        );

        for definition in [
            SemanticRvalueKindV1::Use(typed_operand(3, SCALAR_TYPE)),
            SemanticRvalueKindV1::Cast {
                kind: SemanticCastKindV1::Integer,
                operand: typed_operand(3, SCALAR_TYPE),
            },
            SemanticRvalueKindV1::Binary {
                operation: SemanticBinaryOpV1::Add,
                left: typed_operand(3, SCALAR_TYPE),
                right: typed_constant(SCALAR_TYPE, 1, 4),
            },
            SemanticRvalueKindV1::Unary {
                operation: SemanticUnaryOpV1::Not,
                operand: typed_operand(3, SCALAR_TYPE),
            },
        ] {
            let function = optional_uniform_induction_function_with_selector(
                false,
                SCALAR_TYPE,
                typed_operand(4, SCALAR_TYPE),
                SemanticLocalRoleV1::Temporary,
                vec![typed_assignment(4, SCALAR_TYPE, definition)],
                SemanticTerminatorKindV1::Goto(cfg_edge(SemanticEdgeRoleV1::Goto, 1)),
                None,
                Vec::new(),
                None,
            );
            assert_incomplete(
                project_test_inductions_with_types(&selector_types, &function),
                "an optional uniform induction preheader is not controlled by one exact lane-uniform selector",
            );
        }

        let mutated_argument = optional_uniform_induction_function_with_selector(
            false,
            SCALAR_TYPE,
            typed_operand(4, SCALAR_TYPE),
            SemanticLocalRoleV1::Argument(1),
            vec![typed_assignment(
                4,
                SCALAR_TYPE,
                SemanticRvalueKindV1::Use(typed_constant(SCALAR_TYPE, 0, 4)),
            )],
            SemanticTerminatorKindV1::Goto(cfg_edge(SemanticEdgeRoleV1::Goto, 1)),
            None,
            Vec::new(),
            None,
        );
        assert_incomplete(
            project_test_inductions_with_types(&selector_types, &mutated_argument),
            "an optional uniform induction preheader is not controlled by one exact lane-uniform selector",
        );

        let escaped_argument = optional_uniform_induction_function_with_selector(
            false,
            SCALAR_TYPE,
            typed_operand(4, SCALAR_TYPE),
            SemanticLocalRoleV1::Argument(1),
            vec![typed_assignment(
                7,
                POINTER_TYPE,
                SemanticRvalueKindV1::AddressOf {
                    mutability: SemanticMutabilityV1::Mutable,
                    place: typed_place(4, SCALAR_TYPE),
                },
            )],
            SemanticTerminatorKindV1::Goto(cfg_edge(SemanticEdgeRoleV1::Goto, 1)),
            None,
            Vec::new(),
            None,
        );
        assert_incomplete(
            project_test_inductions_with_types(&selector_types, &escaped_argument),
            "an optional uniform induction preheader is not controlled by one exact lane-uniform selector",
        );

        let call_redefined_argument = optional_uniform_induction_function_with_selector(
            false,
            SCALAR_TYPE,
            typed_operand(4, SCALAR_TYPE),
            SemanticLocalRoleV1::Argument(1),
            Vec::new(),
            SemanticTerminatorKindV1::Goto(cfg_edge(SemanticEdgeRoleV1::Goto, 1)),
            None,
            Vec::new(),
            Some(SemanticTerminatorKindV1::Call(
                SemanticDirectCallV1::new_callable(
                    SemanticCallableIdV1::from_index(0),
                    vec![],
                    Some(SemanticCallDestinationV1::new(
                        typed_place(4, SCALAR_TYPE),
                        cfg_edge(SemanticEdgeRoleV1::CallReturn, 3),
                    )),
                    SemanticUnwindActionV1::Unreachable,
                )
                .unwrap(),
            )),
        );
        assert_incomplete(
            project_test_inductions_with_types(&selector_types, &call_redefined_argument),
            "an optional uniform induction preheader is not controlled by one exact lane-uniform selector",
        );

        for derived_boolean in [
            SemanticRvalueKindV1::Binary {
                operation: SemanticBinaryOpV1::Equal,
                left: typed_operand(3, SCALAR_TYPE),
                right: typed_constant(SCALAR_TYPE, 0, 4),
            },
            SemanticRvalueKindV1::Unary {
                operation: SemanticUnaryOpV1::Not,
                operand: typed_constant(BOOL_TYPE, 0, 1),
            },
        ] {
            let function = optional_uniform_induction_function_with(
                false,
                SemanticLocalRoleV1::Temporary,
                vec![typed_assignment(4, BOOL_TYPE, derived_boolean)],
                SemanticTerminatorKindV1::Goto(cfg_edge(SemanticEdgeRoleV1::Goto, 1)),
                None,
                Vec::new(),
                None,
            );
            assert_incomplete(
                project_test_inductions_with_types(&selector_types, &function),
                "an optional uniform induction preheader is not controlled by one exact lane-uniform selector",
            );
        }
    }

